window.BANQUE_INFINI = {"module":"annee-1/theorique/semestre-1/anatomie","titre":"Anatomie I","sources":[{"t":"Anatomie I — Introduction à la myologie","q":"qcm/myo-00-introduction.html","f":"fiches/myo-00-introduction.html"},{"t":"Anatomie I — Cervicales et Tête","q":"qcm/myo-01-cervicales-tete.html","f":"fiches/myo-01-cervicales-tete.html"},{"t":"Anatomie I — Colonne, Thorax, Abdomen, Respiration","q":"qcm/myo-02-colonne-thorax-abdomen.html","f":"fiches/myo-02-colonne-thorax-abdomen.html"},{"t":"Anatomie I — Scapulaire, Épaule, Coude, Avant-bras","q":"qcm/myo-03-scapulaire-epaule-coude.html","f":"fiches/myo-03-scapulaire-epaule-coude.html"},{"t":"Anatomie I — Poignet et Main","q":"qcm/myo-04-poignet-main.html","f":"fiches/myo-04-poignet-main.html"},{"t":"Anatomie I — Pelvienne, Hanche, Genou","q":"qcm/myo-05-pelvienne-hanche-genou.html","f":"fiches/myo-05-pelvienne-hanche-genou.html"},{"t":"Anatomie I — Cheville et Pied","q":"qcm/myo-06-cheville-pied.html","f":"fiches/myo-06-cheville-pied.html"},{"t":"Anatomie I — Introduction à la neuro-anatomie","q":"qcm/neuro-01-introduction.html","f":"fiches/neuro-01-introduction.html"},{"t":"Anatomie I — Système Nerveux Périphérique","q":"qcm/neuro-02-snp.html","f":"fiches/neuro-02-snp.html"},{"t":"Anatomie I — SNC — Moelle et voies sensitives","q":"qcm/neuro-03-moelle-voies-sensitives.html","f":"fiches/neuro-03-moelle-voies-sensitives.html"},{"t":"Anatomie I — Tronc cérébral et voies motrices","q":"qcm/neuro-04-tronc-cerebral-voies-motrices.html","f":"fiches/neuro-04-tronc-cerebral-voies-motrices.html"},{"t":"Anatomie I — Cervelet et Cerveau","q":"qcm/neuro-05-cervelet-cerveau.html","f":"fiches/neuro-05-cervelet-cerveau.html"},{"t":"Anatomie I — Système Nerveux Végétatif","q":"qcm/neuro-06-systeme-vegetatif.html","f":"fiches/neuro-06-systeme-vegetatif.html"},{"t":"Anatomie I — Introduction à l'anatomie","q":"qcm/osteo-00-introduction.html","f":"fiches/osteo-00-introduction.html"},{"t":"Anatomie I — Crâne et Face","q":"qcm/osteo-01-crane-face.html","f":"fiches/osteo-01-crane-face.html"},{"t":"Anatomie I — Arthrologie — Crâne et Face","q":"qcm/osteo-02-arthro-crane-face.html","f":"fiches/osteo-02-arthro-crane-face.html"},{"t":"Anatomie I — Colonne Vertébrale","q":"qcm/osteo-03-colonne.html","f":"fiches/osteo-03-colonne.html"},{"t":"Anatomie I — Thorax","q":"qcm/osteo-04-thorax.html","f":"fiches/osteo-04-thorax.html"},{"t":"Anatomie I — Membre Supérieur","q":"qcm/osteo-05-membre-sup.html","f":"fiches/osteo-05-membre-sup.html"},{"t":"Anatomie I — Membre Inférieur","q":"qcm/osteo-06-membre-inf.html","f":"fiches/osteo-06-membre-inf.html"}],"questions":[{"q":"Le mouvement du corps humain dépend principalement :","o":["Du système nerveux seul","Des muscles squelettiques","Du système digestif","Du squelette seul"],"r":1,"e":"Les muscles squelettiques sont fondamentaux pour produire le mouvement.","s":0},{"q":"Quelle est une fonction des muscles squelettiques ?","o":["Digérer","Contrôle postural","Filtrer le sang","Sécréter des hormones"],"r":1,"e":"Les muscles ont des fonctions de locomotion, contrôle postural et protection.","s":0},{"q":"L'organisation fonctionnelle des muscles se fait par :","o":["Leur couleur, rouge ou blanche","Leur taille, du plus grand au plus petit","Leur action sur une articulation","Leur origine embryologique"],"r":2,"e":"L'organisation fonctionnelle classe les muscles par leur action sur un complexe articulaire.","s":0},{"q":"L'origine d'un muscle est généralement :","o":["Distale et mobile","Proximale et fixe","Au milieu","Sur la peau"],"r":1,"e":"L'origine est habituellement proximale et reste fixe pendant la contraction.","s":0},{"q":"L'insertion d'un muscle est généralement :","o":["Proximale et fixe","Distale et mobile","Centrale","Sur l'origine opposée"],"r":1,"e":"L'insertion est distale et mobile pendant la contraction.","s":0},{"q":"Le muscle qui produit le mouvement est :","o":["Antagoniste","Agoniste","Synergiste","Stabilisateur"],"r":1,"e":"L'agoniste est le muscle principal responsable du mouvement.","s":0},{"q":"Le muscle qui s'oppose au mouvement est :","o":["Agoniste","Antagoniste","Synergiste","Stabilisateur"],"r":1,"e":"L'antagoniste s'oppose à l'action de l'agoniste.","s":0},{"q":"Une contraction où le muscle se raccourcit est :","o":["Excentrique","Concentrique","Isométrique","Isotonique"],"r":1,"e":"Concentrique = raccourcissement du muscle (action positive).","s":0},{"q":"Une contraction où le muscle s'allonge en travaillant est :","o":["Excentrique","Concentrique","Isométrique","Isokinétique"],"r":0,"e":"Excentrique = le muscle s'allonge en se contractant (freine un mouvement, ex : descendre les escaliers).","s":0},{"q":"Une contraction sans changement de longueur est :","o":["Concentrique","Excentrique","Isométrique","Isokinétique"],"r":2,"e":"Isométrique = pas de mouvement (ex : tenir une charge en statique).","s":0},{"q":"Combien de zones régionales sont traditionnellement utilisées ?","o":["2","3","4","5"],"r":1,"e":"3 zones : extrémité supérieure, squelette axial, extrémité inférieure.","s":0},{"q":"Les muscles du squelette axial comprennent :","o":["Bras, avant-bras, cuisses et jambes","Face, cervicales, colonne, thorax et abdomen","Hanche, bassin, cuisse, genou, cheville et pied","Épaule, coude, poignet et main"],"r":1,"e":"Squelette axial = visage/mâchoire, cervicales/tête, colonne, thorax/abdomen/respiration.","s":0},{"q":"Pour chaque muscle, il faut connaître :","o":["Origine, insertion, action et innervation","Origine seule, sans l'insertion ni l'action","Action seule, sans l'origine ni l'innervation","Nom latin seul, sans aucun autre élément"],"r":0,"e":"Pour chaque muscle : origine, insertion, action, innervation.","s":0},{"q":"Un muscle synergiste :","o":["S'oppose à l'agoniste","Aide l'agoniste","Bloque l'articulation","N'a pas d'action"],"r":1,"e":"Le synergiste aide à l'action de l'agoniste.","s":0},{"q":"Un stabilisateur :","o":["Crée le mouvement principal du segment","Fixe une articulation pour qu'une autre bouge","Allonge le muscle agoniste pendant le mouvement","S'oppose à l'action de l'agoniste"],"r":1,"e":"Le stabilisateur fixe une articulation pour permettre le mouvement à un autre endroit (ex : scapula stabilisée pour mouvement du bras).","s":0},{"q":"Les muscles permettent :","o":["La seule locomotion, sans autre fonction","Le mouvement, la posture, la protection","La digestion, le transit et la sécrétion","La seule respiration, sans autre fonction"],"r":1,"e":"Multiples fonctions : mouvement, posture, protection des organes internes. Il s'agit de la protection des organes internes.","s":0},{"q":"Le ventre musculaire :","o":["Est composé de tissu conjonctif","Contient les fibres contractiles","Est avasculaire","Est composé d'os"],"r":1,"e":"Le ventre (corps) musculaire contient les fibres musculaires contractiles.","s":0},{"q":"Le tendon relie :","o":["Le muscle à un autre muscle","Le muscle à l'os","L'os à l'os","Le muscle à la peau"],"r":1,"e":"Le tendon (tissu conjonctif fibreux) relie le muscle à l'os.","s":0},{"q":"Le ligament relie :","o":["Le muscle à l'os","L'os à l'os","Les organes","La peau"],"r":1,"e":"Le ligament (à distinguer du tendon) relie un os à un autre os.","s":0},{"q":"L'innervation motrice d'un muscle est :","o":["Sensitive, par des nerfs afférents","Motrice, par un nerf moteur somatique","Autonome, par le système sympathique","Visuelle, par les voies optiques du cortex"],"r":1,"e":"Les muscles squelettiques sont innervés par des nerfs moteurs (somatiques).","s":0},{"q":"Pour le mouvement humain, l'analyse musculaire est :","o":["Sans importance en kiné","Essentielle en kiné","Réservée aux médecins","Toujours secondaire"],"r":1,"e":"L'analyse musculaire est centrale en kinésithérapie pour le mouvement.","s":0},{"q":"Une contraction excentrique se voit lors :","o":["Montée d'escaliers","Descente d'escaliers","Maintien statique","Levée de bras lente"],"r":1,"e":"Descente des escaliers = travail excentrique du quadriceps.","s":0},{"q":"Lors d'une flexion de coude, le biceps est :","o":["Antagoniste","Agoniste","Stabilisateur","Synergiste seul"],"r":1,"e":"Lors de flexion du coude, le biceps brachial est l'agoniste.","s":0},{"q":"Lors d'une flexion de coude, le triceps est :","o":["Agoniste","Antagoniste","Synergiste","Sans rôle"],"r":1,"e":"Le triceps est antagoniste à la flexion (il fait l'extension).","s":0},{"q":"La fonction de protection des organes internes par les muscles est :","o":["Une fonction mineure","Une fonction essentielle","Une fonction inexistante","Une fonction limitée au thorax"],"r":1,"e":"Les muscles protègent les organes internes (ex : muscles abdominaux protègent les viscères).","s":0},{"q":"Le contrôle postural :","o":["Ne nécessite aucun muscle squelettique","Est une fonction musculaire essentielle","Est une fonction uniquement osseuse","Dépend du seul squelette, sans les muscles"],"r":1,"e":"Le contrôle postural est une fonction essentielle des muscles squelettiques (notamment via contractions isométriques).","s":0},{"q":"Combien de leçons couvre le programme de myologie ?","o":["4","5","6","7"],"r":2,"e":"6 leçons : 1) ATM/cervicales, 2) Colonne/thorax/abdomen, 3) Scapulaire/épaule/coude, 4) Poignet/main, 5) Pelvienne/hanche/genou, 6) Cheville/pied.","s":0},{"q":"Un muscle agit toujours en :","o":["Tirant","Poussant","Bloquant","Détendant l'os"],"r":0,"e":"Un muscle tire (en se contractant), il ne pousse jamais.","s":0},{"q":"La contraction concentrique est aussi appelée :","o":["Action freinatrice","Action motrice positive","Action statique","Action passive"],"r":1,"e":"Concentrique = positive (le muscle raccourcit pour produire le mouvement).","s":0},{"q":"Une analyse fonctionnelle d'un muscle implique de comprendre :","o":["Sa couleur et sa vascularisation","Son action sur les articulations","Sa température pendant l'effort prolongé","Sa position par rapport à la peau"],"r":1,"e":"L'analyse fonctionnelle d'un muscle nécessite de comprendre son action sur une ou plusieurs articulations.","s":0},{"q":"Selon l'organisation traditionnelle, en quelles trois régions classe-t-on les muscles ?","o":["Extrémité supérieure, squelette axial, extrémité inférieure","Tête, tronc et membres, de haut en bas","Plans superficiel, intermédiaire et profond","Agonistes, antagonistes et synergistes, selon chaque mouvement"],"r":0,"e":"L'organisation régionale traditionnelle distingue extrémité supérieure, squelette axial et extrémité inférieure ; l'autre classement, fonctionnel, se fait par complexe articulaire.","s":0},{"q":"Dans l'organisation fonctionnelle du cours, quels ensembles relèvent du squelette axial ?","o":["Face, cou, colonne, thorax, abdomen et respiration","Ceinture scapulaire, épaule, coude et poignet","Ceinture pelvienne, hanche, genou et cheville","Colonne vertébrale seule, de l'atlas jusqu'au coccyx"],"r":0,"e":"Le squelette axial regroupe ces quatre ensembles ; les ceintures scapulaire et pelvienne relèvent des membres. La face inclut la mâchoire.","s":0},{"q":"Sur quel critère l'organisation fonctionnelle du cours regroupe-t-elle les muscles ?","o":["Par action dans un complexe articulaire","Par ordre alphabétique du nom latin du muscle","Par taille, du plus grand au plus petit","Par type de fibres, lentes ou rapides"],"r":0,"e":"Le cours systématise les muscles selon leur action au sein d'un complexe articulaire donné.","s":0},{"q":"Qu'est-ce qui caractérise l'origine d'un muscle pendant le mouvement ?","o":["Elle reste fixe","Elle est mobile","Elle est toujours tendineuse","Elle est toujours distale"],"r":0,"e":"L'origine, habituellement proximale, sert de point fixe alors que l'insertion distale se déplace.","s":0},{"q":"De quel tissu les tendons sont-ils faits ?","o":["Tissu conjonctif fibreux","Tissu musculaire strié","Tissu cartilagineux","Tissu adipeux"],"r":0,"e":"Le tendon est un tissu conjonctif fibreux reliant le muscle à l'os ; les fibres contractiles sont dans le ventre musculaire.","s":0},{"q":"Quel rôle joue un muscle stabilisateur ?","o":["Il fixe une articulation pour permettre l'action","Il produit le mouvement principal de tout le segment","Il s'oppose au mouvement produit par l'agoniste","Il allonge l'agoniste en fin de mouvement"],"r":0,"e":"Le stabilisateur immobilise un segment afin que l'agoniste puisse travailler efficacement ; le synergiste, lui, aide directement l'action de l'agoniste.","s":0},{"q":"Quelle contraction freine un mouvement en s'allongeant ?","o":["La contraction excentrique","La contraction concentrique","La contraction isométrique","La contraction isotonique concentrique"],"r":0,"e":"Le muscle excentrique produit de la force tout en s'allongeant, ce qui freine le mouvement.","s":0},{"q":"Quelles sont les quatre fonctions essentielles des muscles squelettiques citées en introduction ?","o":["Locomotion, prise d'objets, posture et protection","Locomotion, digestion, thermorégulation et posture","Posture, respiration, circulation et protection","Mouvement, croissance osseuse, équilibre et protection"],"r":0,"e":"La fiche liste ces quatre fonctions ; la digestion et la circulation relèvent des muscles lisse et cardiaque. Il s'agit du contrôle postural et de la protection des organes internes.","s":0},{"q":"Quels sont les quatre éléments à étudier pour chaque muscle ?","o":["Localisation, insertions, actions, innervation","Nom, taille, forme, couleur","Origine, vascularisation, type de fibres, force","Insertions, vascularisation, innervation, action"],"r":0,"e":"La fiche impose localisation, description des insertions (origine et insertion), actions et innervation.","s":0},{"q":"Qu'est-ce qui contient les fibres contractiles d'un muscle ?","o":["Le corps musculaire, ou ventre","Le tendon, ou partie terminale","L'aponévrose, ou lame tendineuse large","Le périoste, ou enveloppe de l'os"],"r":0,"e":"Les fibres contractiles sont dans le ventre ; le tendon, non contractile, transmet la force à l'os.","s":0},{"q":"Qu'est-ce qu'un muscle antagoniste ?","o":["Le muscle qui s'oppose au mouvement de l'agoniste","Le muscle qui aide l'agoniste dans son action","Le muscle qui fixe l'articulation voisine","Le muscle le plus profond du groupe musculaire"],"r":0,"e":"L'antagoniste s'oppose au mouvement de l'agoniste ; le synergiste l'assiste et le stabilisateur fixe l'articulation.","s":0},{"q":"Quelle contraction se fait sans changement de longueur du muscle ?","o":["L'isométrique","La concentrique","L'excentrique","L'isotonique"],"r":0,"e":"Isométrique signifie « même longueur » : contraction statique, sans déplacement articulaire.","s":0},{"q":"Le muscle masséter a pour action :","o":["Abaissement de la mandibule","Élévation de la mandibule","Rotation de la tête","Flexion du cou"],"r":1,"e":"Le masséter est le principal élévateur de la mandibule (fermeture de la bouche).","s":1},{"q":"L'innervation des muscles masticateurs est assurée par :","o":["Le nerf facial, VII","Le nerf mandibulaire, V3","Le nerf grand hypoglosse, XII","Les racines cervicales C1-C3"],"r":1,"e":"Tous les muscles masticateurs sont innervés par le V3 (nerf mandibulaire, branche du trijumeau). Le V3 est une branche du trijumeau.","s":1},{"q":"Le ptérygoïdien latéral est responsable de :","o":["Élévation, fermeture et rétropulsion","Abaissement, propulsion et diduction","Rotation pure, sans autre mouvement","Fermeture, serrage et rétropulsion de la mâchoire"],"r":1,"e":"Le ptérygoïdien latéral abaisse, propulse et fait la diduction de la mandibule.","s":1},{"q":"Le SCM est innervé par :","o":["Nerf trijumeau, V, avec C1 et C2","Nerf accessoire, XI, avec C2-C3","Nerf facial, VII, avec C4","Anse cervicale, C1-C3"],"r":1,"e":"Le SCM est innervé par le nerf accessoire (XI) avec contribution de C2-C3.","s":1},{"q":"L'action bilatérale du SCM produit :","o":["Une rotation de la tête","Une flexion du cou et de la tête","Une extension du cou","Une inclinaison latérale du cou et de la tête"],"r":1,"e":"Action bilatérale du SCM = flexion du cou/tête.","s":1},{"q":"L'action unilatérale du SCM est :","o":["Inclinaison contro + rotation homo","Inclinaison homo + rotation contro","Flexion pure","Extension pure"],"r":1,"e":"Action unilatérale du SCM : inclinaison HOMOlatérale + rotation CONTROlatérale.","s":1},{"q":"Les muscles peauciers de la face sont innervés par :","o":["Le trijumeau, nerf V3","Le facial, nerf VII","L'accessoire, nerf XI","L'hypoglosse, XII"],"r":1,"e":"Tous les muscles peauciers/de l'expression du visage sont innervés par le nerf facial (VII).","s":1},{"q":"Le scalène antérieur s'insère sur :","o":["Le bord supérieur de la 2ᵉ côte","Le tubercule de Lisfranc de la 1ʳᵉ côte","Le tiers moyen de la clavicule","Le bord supérieur du manubrium du sternum"],"r":1,"e":"Le scalène antérieur s'insère sur le tubercule de Lisfranc de la 1ère côte.","s":1},{"q":"Le buccinateur est innervé par :","o":["Le trijumeau, nerf V","Le facial, nerf VII","L'accessoire, nerf XI","L'hypoglosse, nerf XII"],"r":1,"e":"Buccinateur = muscle peaucier = nerf facial (VII).","s":1},{"q":"Le scalène postérieur s'insère sur :","o":["La 1ère côte","La 2e côte","Le sternum","La clavicule"],"r":1,"e":"Scalène postérieur → 2e côte.","s":1},{"q":"L'orbiculaire des paupières est innervé par :","o":["V","VII","III","IV"],"r":1,"e":"Tous les muscles peauciers = VII (facial).","s":1},{"q":"Les muscles sous-hyoïdiens sont innervés par :","o":["L'anse cervicale, C1 à C3","Le trijumeau, par le V3","Le facial, par le VII et C1","Le vague, par le X et par C2"],"r":0,"e":"Les sous-hyoïdiens sont innervés par l'anse cervicale (C1-C3).","s":1},{"q":"Le digastrique a une innervation :","o":["Mixte, par le V3 et le VII","Unique, par le V3 seul","Unique, par le VII seul, en arrière","Unique, par le XII seul"],"r":0,"e":"Le digastrique a 2 ventres : antérieur = V3 (mylo-hyoïdien), postérieur = VII.","s":1},{"q":"L'action principale des muscles sus-hyoïdiens est :","o":["Abaisser l'hyoïde","Élever l'hyoïde","Tourner la tête","Mouvement oculaire"],"r":1,"e":"Les sus-hyoïdiens élèvent l'os hyoïde (déglutition).","s":1},{"q":"Le long du cou (longus colli) produit :","o":["Une extension","Une flexion","Une rotation pure","Une abduction"],"r":1,"e":"Le long du cou fléchit la tête et le cou (muscle prévertébral).","s":1},{"q":"Les muscles suboccipitaux sont innervés par :","o":["Le trijumeau, V3","L'accessoire, XI, avec C2","Le sous-occipital, C1","L'anse cervicale, C1-C3"],"r":2,"e":"Les muscles suboccipitaux sont innervés par le nerf sous-occipital (C1).","s":1},{"q":"Le grand droit postérieur de la tête participe à :","o":["La flexion pure de la tête","L'extension et la rotation de la tête","L'élévation de la mandibule","La flexion et l'inclinaison de la tête"],"r":1,"e":"Grand droit postérieur : extension + rotation de la tête.","s":1},{"q":"Le temporal s'insère sur :","o":["Le condyle mandibulaire","Le processus coronoïde","La trochlée","La mastoïde"],"r":1,"e":"Le temporal s'insère sur le processus coronoïde de la mandibule.","s":1},{"q":"Le muscle qui sourit (élévation des commissures) est :","o":["Le risorius, muscle du rire","Le zygomatique majeur","L'orbiculaire des lèvres","Le muscle mentonnier"],"r":1,"e":"Le zygomatique majeur tire la commissure vers le haut et l'extérieur (sourire).","s":1},{"q":"Le platysma est innervé par :","o":["V","VII","XI","XII"],"r":1,"e":"Le platysma (peaucier du cou) est innervé par le VII (facial).","s":1},{"q":"Le sterno-thyroïdien fait partie des :","o":["Sus-hyoïdiens","Sous-hyoïdiens","Masticateurs","Suboccipitaux"],"r":1,"e":"Sterno-thyroïdien = sous-hyoïdien.","s":1},{"q":"Le ptérygoïdien médial (interne) a pour action :","o":["Abaissement, ouverture et diduction","Élévation, propulsion et diduction","Rotation pure, sans autre mouvement","Aucune, il ne fait que stabiliser le disque"],"r":1,"e":"Ptérygoïdien médial : élévation, propulsion, diduction (controlatérale).","s":1},{"q":"L'oblique inférieur du cou produit :","o":["La flexion de la tête","L'extension complète de la tête et du cou","La rotation homolatérale de la tête","L'abduction de la tête"],"r":2,"e":"L'oblique inférieur : rotation homolatérale de la tête (atlas-axis).","s":1},{"q":"Le scalène antérieur a pour innervation :","o":["Le nerf accessoire, XI, et C2","Les rameaux antérieurs de C4 à C6","Le nerf trijumeau, V, et C1","Les branches du plexus brachial, de C5 à T1"],"r":1,"e":"Les scalènes sont innervés par les rameaux antérieurs cervicaux (C4-C6).","s":1},{"q":"Le muscle frontal (occipito-frontal) :","o":["Ferme l'œil","Élève les sourcils","Sourit","Ouvre la bouche"],"r":1,"e":"Le frontal élève les sourcils et plisse le front.","s":1},{"q":"L'action principale des scalènes sur le rachis est :","o":["L'extension du rachis cervical","L'inclinaison homolatérale du rachis","La rotation controlatérale du rachis","Aucune action sur le rachis, seulement sur les côtes"],"r":1,"e":"Les scalènes font la flexion latérale (homolatérale) du rachis cervical.","s":1},{"q":"L'action sur la respiration des scalènes est :","o":["L'abaissement des côtes 11 et 12, en expiration","L'élévation des côtes 1 et 2, en inspiration","L'abaissement des côtes 1 et 2, en expiration","Une action sur le diaphragme, en inspiration"],"r":1,"e":"En inspiration profonde : les scalènes (muscles inspirateurs accessoires) élèvent les 1ère et 2e côtes.","s":1},{"q":"Le muscle qui ferme la bouche est :","o":["Le buccinateur de la joue","L'orbiculaire des lèvres","Le grand zygomatique de la face","Le muscle mentonnier"],"r":1,"e":"L'orbiculaire des lèvres ferme la bouche.","s":1},{"q":"Le mylo-hyoïdien est innervé par :","o":["VII","V3","XII","C1"],"r":1,"e":"Le mylo-hyoïdien est innervé par le V3 (nerf mandibulaire).","s":1},{"q":"L'oblique supérieur du cou fait :","o":["L'extension et l'inclinaison de la tête","La rotation pure de la tête","L'élévation de l'os hyoïde","Aucune action propre sur la tête seule"],"r":0,"e":"L'oblique supérieur : extension + flexion latérale de la tête.","s":1},{"q":"Quelle est l'origine du masséter ?","o":["Arcade zygomatique","Fosse temporale","Fosse ptérygoïdienne","Processus mastoïde"],"r":0,"e":"Le masséter naît de l'arcade zygomatique et s'insère sur l'angle et la branche latérale de la mandibule. La fosse temporale est l'origine du temporal, la fosse ptérygoïdienne celle du ptérygoïdien médial.","s":1},{"q":"Sur quoi s'insère le temporal ?","o":["Processus coronoïde de la mandibule","Col du condyle mandibulaire","Angle de la mandibule (face interne)","Os hyoïde"],"r":0,"e":"Le temporal se termine sur le processus coronoïde. Le col du condyle est l'insertion du ptérygoïdien latéral, la face interne de l'angle celle du ptérygoïdien médial.","s":1},{"q":"Quelle est l'origine du ptérygoïdien latéral ?","o":["Grande aile du sphénoïde et lame ptérygoïde latérale","Fosse ptérygoïdienne et tubérosité du maxillaire","Arcade zygomatique et toute la fosse temporale du crâne","Ligne nuchale supérieure et processus mastoïde"],"r":0,"e":"La fiche précise cette double origine sphénoïdale et ptérygoïdienne. La fosse ptérygoïdienne est l'origine du ptérygoïdien médial. C'est la face externe de la lame latérale du processus ptérygoïde.","s":1},{"q":"Quelle particularité présente l'insertion du ptérygoïdien latéral ?","o":["Il s'insère aussi sur le disque articulaire","Il s'insère aussi sur l'os hyoïde, en avant du cou","Il s'insère aussi sur le coronoïde","Il s'insère aussi sur la mastoïde"],"r":0,"e":"Outre le col du condyle, il se fixe sur le disque de l'ATM, ce qui explique son rôle dans la dynamique discale. Le coronoïde reçoit le temporal. Il s'agit du disque de l'articulation temporo-mandibulaire.","s":1},{"q":"Quel muscle peaucier applique les joues contre les dents ?","o":["Le buccinateur","Le risorius","Le mentonnier","Le platysma"],"r":0,"e":"Le buccinateur plaque la joue contre l'arcade dentaire (souffler, mastiquer). Le risorius tire la commissure latéralement, le mentonnier pointe le menton.","s":1},{"q":"Quel muscle peaucier tire la commissure labiale latéralement ?","o":["Le risorius","Le zygomatique majeur","L'orbiculaire des lèvres","Le frontal"],"r":0,"e":"Le risorius a cette action horizontale. Le zygomatique majeur élève la commissure (sourire), l'orbiculaire des lèvres ferme la bouche.","s":1},{"q":"Quelle est l'action du platysma sur la commissure labiale ?","o":["Il l'abaisse","Il l'élève","Il la ferme","Il n'a aucune action sur elle"],"r":0,"e":"Le platysma abaisse la peau du cou et la commissure labiale. Son innervation est faciale (VII).","s":1},{"q":"Quels sont les deux chefs d'origine du SCM ?","o":["Un chef sternal et un chef claviculaire","Un chef mastoïdien et un chef occipital, en haut","Un chef costal et un chef claviculaire","Un chef sternal et un chef scapulaire"],"r":0,"e":"Le SCM naît par un chef sternal sur le manubrium et un chef claviculaire sur le tiers médial. Le mastoïde et la ligne nuchale sont ses terminaisons, pas ses origines. Le chef sternal naît du manubrium, le claviculaire du tiers médial de la clavicule.","s":1},{"q":"Sur quoi se termine le SCM ?","o":["Processus mastoïde et ligne nuchale supérieure","Manubrium sternal et tiers médial de la clavicule","Apophyses transverses de C3 à C6","Corps et grandes cornes de l'os hyoïde"],"r":0,"e":"Il se fixe sur le mastoïde et la ligne nuchale supérieure. Le manubrium et la clavicule sont ses origines.","s":1},{"q":"Quelle est l'origine du platysma ?","o":["Peau de la région sus-claviculaire","Manubrium sternal","Clavicule (tiers latéral)","Apophyse transverse de l'atlas"],"r":0,"e":"Peaucier, le platysma naît de la peau sus-claviculaire pour se terminer sur la peau du menton et de la mandibule.","s":1},{"q":"Où s'insère le scalène moyen ?","o":["Sur la 1ʳᵉ côte, en arrière du sillon sous-clavier","Sur le tubercule de Lisfranc de la 1ʳᵉ côte","Sur la face externe de la 2ᵉ côte, en arrière du sillon","Sur le processus mastoïde du temporal"],"r":0,"e":"Le scalène moyen se fixe sur la 1ère côte en arrière du sillon sous-clavier ; le tubercule de Lisfranc reçoit le scalène antérieur et la 2e côte le scalène postérieur.","s":1},{"q":"Quelle est l'origine du scalène moyen ?","o":["Apophyses transverses C2-C7","Apophyses transverses C3-C6","Apophyses transverses C4-C6","Corps vertébraux C1-T3"],"r":0,"e":"Le scalène moyen a l'étendue la plus large (C2-C7). L'antérieur naît de C3-C6 et le postérieur de C4-C6.","s":1},{"q":"Quelle est l'origine du scalène postérieur ?","o":["Apophyses transverses C4-C6","Apophyses transverses C2-C7","Apophyses transverses C1-C4","1ère côte"],"r":0,"e":"Le scalène postérieur naît des transverses C4-C6 et descend sur la 2e côte.","s":1},{"q":"Combien de muscles sous-hyoïdiens la fiche énumère-t-elle ?","o":["4","3","5","6"],"r":0,"e":"Sterno-thyroïdien, thyro-hyoïdien, sterno-cléido-hyoïdien et omo-hyoïdien : quatre muscles, tous innervés par l'anse cervicale.","s":1},{"q":"Quelle est l'action des muscles sous-hyoïdiens ?","o":["Abaisser l'os hyoïde et le larynx","Élever l'os hyoïde et le larynx vers le haut","Fermer la mandibule contre le maxillaire","Faire tourner la tête du côté opposé"],"r":0,"e":"Les sous-hyoïdiens abaissent l'hyoïde et le larynx ; ce sont les sus-hyoïdiens qui l'élèvent.","s":1},{"q":"Par quoi est innervé le génio-hyoïdien ?","o":["C1","V3","VII","XI"],"r":0,"e":"Le génio-hyoïdien est innervé par C1. Le mylo-hyoïdien dépend de V3 et le stylo-hyoïdien du VII.","s":1},{"q":"Quel nerf innerve le stylo-hyoïdien ?","o":["Le nerf facial (VII)","Le nerf mandibulaire (V3)","Le nerf accessoire (XI)","C1"],"r":0,"e":"Le stylo-hyoïdien relève du VII, comme le ventre postérieur du digastrique.","s":1},{"q":"Quelle est l'étendue du long du cou (longus colli) ?","o":["De C1 à T3, en avant des corps vertébraux","De C3 à C6, en avant des transverses","De l'atlas à l'occipital, en arrière","De C7 à T12, en avant des côtes"],"r":0,"e":"Le longus colli s'étend de C1 à T3 en avant des corps vertébraux, plan prévertébral.","s":1},{"q":"Quelle est l'insertion du long de la tête (longus capitis) ?","o":["L'apophyse basilaire de l'occipital","Le processus mastoïde du temporal","L'arc antérieur de l'atlas","Le corps de C7, à la base du rachis cervical"],"r":0,"e":"Le longus capitis naît des transverses C3-C6 et se termine sur l'apophyse basilaire de l'occipital ; il fléchit la tête.","s":1},{"q":"Quelle est l'action du droit latéral de la tête ?","o":["Flexion latérale","Flexion","Extension","Rotation controlatérale"],"r":0,"e":"Tendu de l'atlas à l'occipital, le droit latéral incline la tête ; le droit antérieur, lui, la fléchit.","s":1},{"q":"Le muscle inspiratoire principal est :","o":["Le SCM","Le diaphragme","Les scalènes","L'intercostal interne"],"r":1,"e":"Le diaphragme est le muscle inspiratoire principal.","s":2},{"q":"Le diaphragme est innervé par :","o":["Le nerf phrénique, issu de C3 à C5","Les nerfs intercostaux, de T7 à T12","Le plexus brachial, de C5 à T1","Le nerf vague, X, par ses rameaux"],"r":0,"e":"Le diaphragme est innervé par le nerf phrénique (C3-C4-C5).","s":2},{"q":"L'orifice œsophagien du diaphragme est au niveau :","o":["T8","T10","T12","L1"],"r":1,"e":"Orifice œsophagien = T10. L'aortique = T12. Veine cave = T8.","s":2},{"q":"L'orifice aortique du diaphragme est à :","o":["T8","T10","T12","L1"],"r":2,"e":"Orifice aortique = T12.","s":2},{"q":"L'orifice de la veine cave inférieure est à :","o":["T8","T10","T12","L1"],"r":0,"e":"Orifice de la veine cave inférieure = T8.","s":2},{"q":"Les intercostaux externes ont une action :","o":["Expiratoire","Inspiratoire","Mixte","Aucune"],"r":1,"e":"Les intercostaux externes élèvent les côtes : inspiration.","s":2},{"q":"Les intercostaux internes ont une action :","o":["Inspiratoire","Expiratoire forcée","Mixte sans rôle","Tonique"],"r":1,"e":"Les intercostaux internes abaissent les côtes : expiration forcée.","s":2},{"q":"L'érecteur du rachis comprend (de latéral à médial) :","o":["Épineux, longissimus, ilio-costal","Ilio-costal, longissimus, épineux","Longissimus, épineux, ilio-costal","Multifidus, semi-épineux, rotateurs"],"r":1,"e":"Erector spinae de latéral à médial : ilio-costal, longissimus, épineux.","s":2},{"q":"L'action bilatérale de l'érecteur du rachis est :","o":["Flexion","Extension","Rotation","Inclinaison"],"r":1,"e":"Action bilatérale = extension du rachis. Unilatérale = inclinaison + rotation.","s":2},{"q":"Le multifidus a une fonction de :","o":["Mouvement seul, sans rôle de stabilisation","Stabilisation, extension et rotation controlatérale","Élévation des côtes, lors de l'inspiration forcée profonde","Rotation homolatérale, sans rôle de stabilisation"],"r":1,"e":"Multifidus : extension + rotation controlatérale + stabilisation segmentaire fine.","s":2},{"q":"Le grand droit de l'abdomen est innervé par :","o":["Le nerf phrénique, issu de C3 à C5","Les nerfs intercostaux, de T6 à T12","Le plexus lombaire, de L1 à L4","L'anse cervicale, de C1 à C3"],"r":1,"e":"Le grand droit est innervé par les nerfs intercostaux T6-T12.","s":2},{"q":"L'oblique externe abdominal fait, en unilatéral :","o":["Inclinaison homolatérale et rotation homolatérale","Inclinaison homolatérale et rotation controlatérale","Inclinaison controlatérale et rotation homolatérale","Inclinaison controlatérale et rotation controlatérale"],"r":1,"e":"Oblique EXTERNE : inclinaison homolatérale + rotation CONTROlatérale.","s":2},{"q":"L'oblique interne abdominal fait, en unilatéral :","o":["Inclinaison contro + rotation homo","Inclinaison homo + rotation homo","Inclinaison homo + rotation contro","Pure flexion"],"r":1,"e":"Oblique INTERNE : inclinaison homolatérale + rotation HOMOlatérale (à l'inverse de l'externe).","s":2},{"q":"Le transverse de l'abdomen a pour fonction principale :","o":["Une flexion forte du tronc, contre résistance","Une compression abdominale et une stabilité","Une rotation du tronc, du côté opposé","Une extension du tronc, en fin d'expiration"],"r":1,"e":"Le transverse de l'abdomen : compression de l'abdomen, expiration forcée, stabilisation du tronc (« gaine »).","s":2},{"q":"Le carré des lombes a pour innervation :","o":["Le nerf phrénique, de C3 à C5","T12 et le plexus lombaire, de L1 à L3","Le plexus sacré, de L4 à S2","Le nerf pudendal et le plexus sacré, de S2 à S4"],"r":1,"e":"Carré des lombes : T12 + L1-L3.","s":2},{"q":"Le carré des lombes participe à :","o":["À l'inspiration, en fixant la 12ᵉ côte","À la rotation, en tirant la 1ʳᵉ côte","À l'élévation du bras, via la 5ᵉ côte","À l'expiration, en abaissant la 2ᵉ côte"],"r":0,"e":"Carré des lombes fixe la 12e côte → permet l'action du diaphragme (inspiration).","s":2},{"q":"L'expiration calme est :","o":["Active, par les muscles abdominaux","Passive, par l'élasticité pulmonaire","Forcée, par les intercostaux internes","Volontaire, par une commande corticale consciente"],"r":1,"e":"L'expiration calme est passive, due à l'élasticité du poumon et de la cage thoracique.","s":2},{"q":"Les muscles inspiratoires accessoires comprennent :","o":["Le grand droit et le transverse de l'abdomen","Le sterno-cléido-mastoïdien et les scalènes","Le transverse et l'oblique interne","Les obliques externes et internes de l'abdomen"],"r":1,"e":"Inspirateurs accessoires : SCM, scalènes, petit pectoral, grand pectoral, dentelé antérieur.","s":2},{"q":"Le grand dorsal a pour origine :","o":["Crête iliaque, sacrum, épineuses et côtes basses","Crête iliaque seule, sur toute sa partie postérieure","Sacrum seul, sur sa face postérieure","Épineuses cervicales, de C3 à C7"],"r":0,"e":"Le grand dorsal : épineuses T6-L5, sacrum, crête iliaque post., côtes 9-12, fascia lombaire. Épineuses T6-L5, côtes 9-12 et fascia lombaire.","s":2},{"q":"Le grand dorsal s'insère sur :","o":["Sur l'angle inférieur de l'omoplate","Sur le tiers latéral de la clavicule, en haut","Sur le sillon bicipital de l'humérus","Sur la tubérosité bicipitale du radius"],"r":2,"e":"Le grand dorsal s'insère sur le sillon intertuberculaire (lèvre interne) de l'humérus. Le sillon bicipital est le sillon intertuberculaire.","s":2},{"q":"L'action du grand dorsal sur l'épaule est :","o":["Flexion, abduction et rotation externe","Extension, adduction et rotation interne","Élévation, abduction et rotation externe","Flexion, adduction et rotation interne"],"r":1,"e":"Grand dorsal : extension, adduction, rotation interne de l'humérus.","s":2},{"q":"Le grand dorsal est innervé par :","o":["Nerf axillaire","Nerf radial","Nerf thoraco-dorsal","Nerf médian"],"r":2,"e":"Nerf thoraco-dorsal (C6-C8) pour le grand dorsal.","s":2},{"q":"Le diaphragme a 3 origines :","o":["Sternale, costale, lombaire","Cervicale, thoracique, lombaire","Sternale, abdominale, vertébrale","Vertébrale, lombaire, sacrée"],"r":0,"e":"Le diaphragme s'origine du sternum (xiphoïde), des côtes 7-12 et des corps L1-L3 (piliers).","s":2},{"q":"Le centre phrénique est :","o":["Une zone nerveuse du diaphragme","Le tendon central du diaphragme","Un muscle accessoire inspirateur","Une artère du diaphragme"],"r":1,"e":"Le centre phrénique est le tendon central (insertion centrale du diaphragme).","s":2},{"q":"Les rameaux postérieurs innervent :","o":["Les muscles abdominaux","Les muscles spinaux dorsaux","Le diaphragme","Le SCM"],"r":1,"e":"Les rameaux postérieurs des nerfs spinaux innervent les muscles spinaux dorsaux profonds.","s":2},{"q":"La ligne blanche est :","o":["Un muscle médian de l'abdomen, très fin","Une aponévrose médiane de l'abdomen","Un ligament médian, du sternum au pubis","Une artère médiane de la paroi"],"r":1,"e":"La ligne blanche (linea alba) est une aponévrose médiane formée par la fusion des aponévroses des muscles larges abdominaux.","s":2},{"q":"Le diaphragme augmente :","o":["La pression à l'intérieur du thorax","Les diamètres du thorax, en descendant","Le volume de l'abdomen, en remontant","La pression dans les voies aériennes"],"r":1,"e":"En se contractant, le diaphragme descend → augmente les diamètres verticaux du thorax (inspiration).","s":2},{"q":"Une augmentation de pression intra-abdominale est due à :","o":["La seule contraction du diaphragme","La contraction des abdominaux et du diaphragme","L'élévation des côtes par les intercostaux","La détente de tous les muscles du tronc"],"r":1,"e":"La pression intra-abdominale augmente par contraction des abdominaux + descente du diaphragme.","s":2},{"q":"Les semi-épineux et multifidus appartiennent au système :","o":["Superficiel","Transverso-épineux","Diaphragmatique","Abdominal"],"r":1,"e":"Semi-épineux, multifidus, rotateurs = système transverso-épineux profond.","s":2},{"q":"L'érecteur du rachis s'origine principalement de :","o":["Le crâne, au niveau de l'occiput","Le sacrum, la crête iliaque et les épineuses basses","Les côtes 1 et 2, sur leur face postérieure","La clavicule et l'épine de l'omoplate, en arrière du tronc"],"r":1,"e":"Origine commune : sacrum, crête iliaque, épineuses lombaires.","s":2},{"q":"Quelle est l'origine des trois colonnes de l'érecteur du rachis ?","o":["Sacrum, crête iliaque, épineuses lombaires et thoraciques","Apophyses transverses cervicales et thoraciques hautes","Côtes 9 à 12, sur leur face externe uniquement","Face antérieure des corps vertébraux lombaires"],"r":0,"e":"La fiche donne une origine commune sacro-iliaque et épineuse basse. Les côtes sont l'insertion de l'ilio-costal, pas son origine. Les épineuses sont lombaires et thoraciques basses.","s":2},{"q":"Sur quoi se termine l'ilio-costal ?","o":["Les côtes","Les apophyses transverses","Les apophyses épineuses","Le sacrum"],"r":0,"e":"Colonne latérale, l'ilio-costal se termine sur les côtes ; le longissimus va aux transverses et l'épineux aux épineuses.","s":2},{"q":"Sur quoi se termine le longissimus ?","o":["Les apophyses transverses","Les côtes","Les apophyses épineuses","La crête iliaque"],"r":0,"e":"Colonne intermédiaire, le longissimus gagne les apophyses transverses.","s":2},{"q":"Sur combien de niveaux le semi-épineux s'étend-il ?","o":["4 à 6 niveaux","2 à 3 niveaux","1 à 2 niveaux","8 à 10 niveaux"],"r":0,"e":"Le semi-épineux couvre 4 à 6 niveaux, le multifidus 2 à 3 et les rotateurs 1 à 2.","s":2},{"q":"Sur combien de niveaux le multifidus s'étend-il ?","o":["2 à 3 niveaux","4 à 6 niveaux","1 à 2 niveaux","6 à 8 niveaux"],"r":0,"e":"Le multifidus est un transverso-épineux court (2-3 niveaux), ce qui en fait un stabilisateur segmentaire.","s":2},{"q":"Quelle est l'action de rotation du semi-épineux et du multifidus ?","o":["Rotation controlatérale","Rotation homolatérale","Aucune rotation","Rotation alternée selon le niveau"],"r":0,"e":"Les transverso-épineux produisent une rotation controlatérale, contrairement à l'érecteur du rachis dont la rotation unilatérale s'accompagne d'une inclinaison homolatérale.","s":2},{"q":"Quelle est l'action principale des rotateurs (transverso-épineux courts) ?","o":["La rotation","L'extension pure","L'inclinaison latérale","La flexion"],"r":0,"e":"Les rotateurs, sur 1 à 2 niveaux, assurent essentiellement la rotation.","s":2},{"q":"Quelle est l'origine du carré des lombes ?","o":["La crête iliaque et le ligament ilio-lombaire","Le bord inférieur de la 12ᵉ côte","Les apophyses transverses de L1 à L4","Le sacrum, le coccyx et le ligament sacro-épineux"],"r":0,"e":"Il naît de la crête iliaque et du ligament ilio-lombaire pour se terminer sur la 12e côte et les transverses L1-L4.","s":2},{"q":"Quelle partie du diaphragme naît du processus xiphoïde ?","o":["La partie sternale","La partie costale","La partie lombaire","Le centre phrénique"],"r":0,"e":"La portion sternale naît de la face postérieure du xiphoïde ; la costale des côtes 7-12 et la lombaire des piliers L1-L3.","s":2},{"q":"De quelles côtes naît la portion costale du diaphragme ?","o":["Les faces internes des côtes 7 à 12","Les faces internes des côtes 5 à 12","Les faces internes des côtes 1 à 8","Les faces externes des côtes 9 à 12, en bas"],"r":0,"e":"La portion costale s'attache aux faces internes des côtes 7 à 12.","s":2},{"q":"Combien de piliers forment la portion lombaire du diaphragme ?","o":["Deux, l'un droit et l'autre gauche","Un seul, en position médiane","Trois, un médian et deux latéraux obliques","Quatre, deux de chaque côté"],"r":0,"e":"Deux piliers, droit et gauche, s'attachent aux corps de L1 à L3.","s":2},{"q":"Que traverse l'orifice aortique du diaphragme, outre l'aorte ?","o":["Le conduit thoracique","Les nerfs vagues","La veine cave inférieure","L'œsophage"],"r":0,"e":"Le conduit thoracique accompagne l'aorte en T12. Les nerfs vagues passent par l'orifice œsophagien (T10).","s":2},{"q":"Que traverse l'orifice œsophagien, outre l'œsophage ?","o":["Les deux nerfs vagues","Le conduit thoracique","La veine cave inférieure","Le nerf phrénique droit et gauche"],"r":0,"e":"Les nerfs vagues accompagnent l'œsophage en T10 ; le conduit thoracique passe en T12 avec l'aorte. Ce sont les nerfs X.","s":2},{"q":"Combien de paires d'intercostaux externes compte-t-on ?","o":["11","12","10","9"],"r":0,"e":"Onze paires d'intercostaux externes comblent les onze espaces intercostaux.","s":2},{"q":"Quelle est la direction des fibres des intercostaux externes ?","o":["Oblique en bas et en avant","Oblique en bas et en arrière","Horizontale","Verticale"],"r":0,"e":"Les externes sont obliques en bas et en avant (inspirateurs) ; les internes, en bas et en arrière (expiration forcée).","s":2},{"q":"Quels muscles ont une fonction identique aux intercostaux internes ?","o":["Les intercostaux intimes","Les intercostaux externes","Les scalènes","Le dentelé antérieur"],"r":0,"e":"Les intercostaux intimes, plus profonds, partagent la fonction expiratrice des internes.","s":2},{"q":"Quelle est l'origine de l'oblique externe de l'abdomen ?","o":["Les faces externes des côtes 5 à 12","La crête iliaque, puis les côtes 10 à 12 en haut","Les faces internes des côtes 7 à 12","Le fascia thoraco-lombaire, de L1 à L5"],"r":0,"e":"L'oblique externe descend des côtes 5-12 vers la crête iliaque et la ligne blanche ; c'est l'oblique interne qui naît de la crête iliaque.","s":2},{"q":"Sur quoi s'insère l'oblique interne de l'abdomen ?","o":["Les côtes 10 à 12 et la ligne blanche","La crête iliaque et la ligne blanche, de L1 à L5","Le pubis, l'épine du pubis et la côte 12","Le processus xiphoïde et les côtes 5 à 7"],"r":0,"e":"L'oblique interne monte de la crête iliaque vers les côtes 10-12 et la ligne blanche.","s":2},{"q":"Quelle est l'insertion supérieure du grand droit de l'abdomen ?","o":["Les cartilages costaux 5 à 7 et le xiphoïde","Les côtes 10 à 12, sur leur bord inférieur","La ligne blanche, au niveau des côtes 8 à 10","La crête iliaque et les côtes 11 et 12"],"r":0,"e":"Le grand droit va du pubis aux cartilages costaux 5-7 et au xiphoïde.","s":2},{"q":"Quel muscle abdominal est le plus profond ?","o":["Le transverse de l'abdomen","L'oblique interne de l'abdomen","L'oblique externe du flanc","Le grand droit de l'abdomen"],"r":0,"e":"Le transverse constitue le plan le plus profond et forme la « gaine abdominale ».","s":2},{"q":"Le trapèze est innervé par :","o":["Le nerf phrénique, C3 à C5","Le nerf XI, avec C3 et C4","Le nerf axillaire, C5 et C6, par le plexus","Le nerf radial, de C5 à T1"],"r":1,"e":"Trapèze : nerf accessoire (XI) + racines C3-C4.","s":3},{"q":"Le dentelé antérieur est innervé par :","o":["Le nerf accessoire, XI, avec C3","Le nerf long thoracique, de C5 à C7","Le nerf supra-scapulaire, C5 et C6","Les nerfs pectoraux, de C5 à T1"],"r":1,"e":"Dentelé antérieur = nerf long thoracique.","s":3},{"q":"Le rôle principal du dentelé antérieur est :","o":["L'élévation de la scapula","La protraction de la scapula","La rétraction de la scapula","La dépression de la scapula"],"r":1,"e":"Le dentelé antérieur fait la protraction (et rotation supérieure) de la scapula.","s":3},{"q":"Quelle scapula s'origine sur C1-C4 ?","o":["Le trapèze supérieur","L'élévateur de la scapula","Le grand rhomboïde","Le petit pectoral, en avant"],"r":1,"e":"L'élévateur de la scapula (levator scapulae) : transverses C1-C4.","s":3},{"q":"Les rhomboïdes sont innervés par :","o":["Le nerf accessoire, XI, et C3","Le nerf scapulaire dorsal, issu de C5","Le nerf axillaire, issu de C5 et C6","Le nerf long thoracique, de C5 à C7"],"r":1,"e":"Rhomboïdes = nerf scapulaire dorsal (C5).","s":3},{"q":"Le petit pectoral s'insère sur :","o":["L'humérus","Le processus coracoïde","La clavicule","L'épine de la scapula"],"r":1,"e":"Petit pectoral → processus coracoïde.","s":3},{"q":"Le sous-clavier est innervé par :","o":["Le nerf sous-clavier, issu de C5 et C6","Le nerf accessoire, XI, avec C3 et C4","Les nerfs pectoraux, de C5 à T1","Le nerf médian, de C6 à T1"],"r":0,"e":"Sous-clavier = nerf sous-clavier (C5-C6).","s":3},{"q":"Le deltoïde est innervé par :","o":["Nerf axillaire","Nerf radial","Nerf musculo-cutané","Nerf supra-scapulaire"],"r":0,"e":"Deltoïde = nerf axillaire (C5-C6).","s":3},{"q":"La fonction principale du deltoïde est :","o":["Flexion du coude","Abduction de l'humérus","Pronation","Rotation externe"],"r":1,"e":"Le deltoïde (toutes fibres) fait l'abduction de l'humérus.","s":3},{"q":"Le supra-épineux a pour action :","o":["Rotation interne","Abduction de l'humérus","Rotation externe","Adduction"],"r":1,"e":"Supra-épineux : abduction de l'humérus (initiation).","s":3},{"q":"L'infra-épineux a pour action :","o":["Rotation interne","Rotation externe","Abduction","Flexion"],"r":1,"e":"Infra-épineux : rotation externe.","s":3},{"q":"Le sous-scapulaire a pour action :","o":["Rotation interne","Rotation externe","Abduction","Extension"],"r":0,"e":"Sous-scapulaire : rotation interne.","s":3},{"q":"La coiffe des rotateurs (SITS) comprend :","o":["Supra-épineux, infra-épineux, petit rond, subscapulaire","Deltoïde, biceps brachial, triceps brachial et grand rond","Trapèze, rhomboïdes, élévateur et dentelé antérieur","Grand pectoral, petit pectoral et sous-clavier"],"r":0,"e":"SITS : Supra-épineux, Infra-épineux, Teres minor (petit rond), Subscapularis.","s":3},{"q":"Le grand pectoral a une double innervation :","o":["Pectoraux latéral, C5 à C7, et médial, C8 à T1","Axillaire, C5 et C6, et radial, C5 à T1","Médian, C6 à T1, et ulnaire, C8 et T1","Musculo-cutané, C5 à C7, et axillaire, C5 et C6"],"r":0,"e":"Grand pectoral : nerfs pectoraux latéral (C5-C7) + médial (C8-T1).","s":3},{"q":"Le coraco-brachial est innervé par :","o":["Nerf axillaire","Nerf musculo-cutané","Nerf radial","Nerf médian"],"r":1,"e":"Coraco-brachial = nerf musculo-cutané.","s":3},{"q":"Le grand dorsal s'insère sur :","o":["Le trochiter, sur sa facette moyenne et inférieure","Le sillon intertuberculaire, lèvre interne","L'olécrane, sur sa face postérieure","La tubérosité bicipitale du radius"],"r":1,"e":"Grand dorsal → sillon intertuberculaire (= sillon bicipital), lèvre interne de l'humérus.","s":3},{"q":"Le grand rond est innervé par :","o":["Nerf axillaire","Nerf sous-scapulaire","Nerf radial","Nerf médian"],"r":1,"e":"Grand rond = nerf sous-scapulaire (C5-C6).","s":3},{"q":"Le biceps brachial a pour origine :","o":["Le trochiter et le trochin de l'humérus","Le tubercule supra-glénoïdien et la coracoïde","Le tubercule infra-glénoïdien et la coracoïde","L'olécrane et l'épicondyle latéral"],"r":1,"e":"Biceps : long chef = tubercule supra-glénoïdien ; court chef = coracoïde. Le long chef naît du tubercule supra-glénoïdien, le court chef de la coracoïde.","s":3},{"q":"Le biceps brachial est innervé par :","o":["Le nerf radial, de C5 à T1","Le nerf musculo-cutané, C5 et C6","Le nerf médian, de C6 à T1, en avant","Le nerf ulnaire, C8 et T1"],"r":1,"e":"Biceps brachial = musculo-cutané.","s":3},{"q":"L'action principale du biceps brachial est :","o":["L'extension du coude et la pronation","La flexion du coude et la supination","La flexion du coude et la pronation","L'extension du coude et la supination"],"r":1,"e":"Biceps brachial : flexion du coude (HU) + supination (RU).","s":3},{"q":"Le brachio-radial est innervé par :","o":["Le nerf médian, de C6 à T1","Le nerf ulnaire, C8 et T1","Le nerf radial, C5 et C6","Le musculo-cutané, C5 à C7"],"r":2,"e":"Brachio-radial = nerf radial.","s":3},{"q":"Le brachio-radial est plus efficace en :","o":["En pronation, paume vers le bas","En supination, paume vers le haut","En position neutre, poignée de main","En flexion totale, coude à 140°"],"r":2,"e":"Brachio-radial : fléchisseur du coude le plus efficace en position neutre (poignée de main).","s":3},{"q":"Le rond pronateur a pour origine :","o":["L'épicondyle latéral et le bord postérieur du radius","L'épicondyle médial et le processus coronoïde","La tête radiale et le col du radius","L'olécrane et la face postérieure de l'ulna"],"r":1,"e":"Rond pronateur : épicondyle médial + processus coronoïde du cubitus.","s":3},{"q":"Le triceps brachial s'origine en 3 chefs :","o":["Long, latéral, médial","Long, court, accessoire","Antérieur, postérieur, latéral","Distal, proximal, moyen"],"r":0,"e":"Triceps : chef long (tubercule infra-glénoïdien), latéral (humérus prox), médial (humérus distal).","s":3},{"q":"Le triceps brachial est innervé par :","o":["Le nerf médian, de C6 à T1","Le nerf ulnaire, C8 et T1","Le nerf radial, C7 et C8","Le nerf musculo-cutané, C5 et C6"],"r":2,"e":"Triceps brachial = nerf radial.","s":3},{"q":"Le carré pronateur est innervé par :","o":["Le nerf médian, C8 et T1","Le nerf radial, de C5 à T1","Le nerf ulnaire, C8 et T1","Le musculo-cutané, C5"],"r":0,"e":"Carré pronateur = médian (C8-T1).","s":3},{"q":"Le supinateur est innervé par :","o":["Le nerf médian, C6 et C7","Le nerf radial, issu de C6","Le nerf ulnaire, issu de C8 et T1","Le musculo-cutané, C5 et C6"],"r":1,"e":"Supinateur = nerf radial (C6).","s":3},{"q":"L'anconé aide à :","o":["La flexion du coude, en pronation","L'extension du coude et sa stabilisation","La pronation de l'avant-bras, contre résistance","L'abduction de l'avant-bras"],"r":1,"e":"Anconé : aide l'extension du coude + stabilisation lors de prono/supination.","s":3},{"q":"Le trapèze (fibres moyennes) fait :","o":["L'élévation de la scapula","La rétraction, ou adduction, de la scapula","La dépression de la scapula","La rotation inférieure, ou bascule, de la scapula"],"r":1,"e":"Fibres moyennes du trapèze : rétraction (adduction) de la scapula.","s":3},{"q":"Les fibres inférieures du trapèze font :","o":["L'élévation et la rotation inférieure, ou bascule","La dépression et la rotation supérieure","L'adduction pure, sans rotation","La rotation inférieure seule"],"r":1,"e":"Fibres inférieures du trapèze : dépression + rotation supérieure de la scapula.","s":3},{"q":"Quelle est l'origine du trapèze ?","o":["Occipital, ligament nucal et épineuses de C7 à T12","Apophyses transverses de C1 à C4, sur leur tubercule postérieur","Épineuses de C7 à T5, sur leur sommet","Faces externes des côtes 1 à 8"],"r":0,"e":"Le trapèze naît de l'occipital, du ligament nucal et des épineuses C7-T12. C1-C4 est l'origine de l'élévateur de la scapula, C7-T5 celle des rhomboïdes. Au niveau de l'occipital, c'est la ligne courbe supérieure.","s":3},{"q":"Sur quoi s'insère l'élévateur de la scapula ?","o":["Angle supérieur de la scapula","Bord interne de la scapula","Processus coracoïde","Épine de la scapula"],"r":0,"e":"Le levator scapulae se fixe sur l'angle supérieur ; les rhomboïdes et le dentelé antérieur gagnent le bord interne.","s":3},{"q":"Quelle est l'action de l'élévateur de la scapula sur la rotation scapulaire ?","o":["Rotation inférieure","Rotation supérieure","Aucune rotation","Rotation supérieure puis inférieure"],"r":0,"e":"Il associe élévation et rotation inférieure de la scapula, comme les rhomboïdes ; le trapèze et le dentelé antérieur font la rotation supérieure.","s":3},{"q":"Quelle est l'origine du petit rhomboïde ?","o":["Épineuses C7-T1","Épineuses T2-T5","Apophyses transverses C1-C4","Épineuses C7-T12"],"r":0,"e":"Le petit rhomboïde naît de C7-T1 et le grand de T2-T5.","s":3},{"q":"De quelles côtes naît le dentelé antérieur ?","o":["Côtes 1 à 8/9","Côtes 3 à 5","Côtes 5 à 12","Côtes 9 à 12"],"r":0,"e":"Le dentelé antérieur naît de la surface antérolatérale des côtes 1 à 8/9 ; les côtes 3-5 donnent le petit pectoral.","s":3},{"q":"Quelle est l'origine du petit pectoral ?","o":["Les faces antérieures des côtes 3 à 5","Les faces externes des côtes 1 à 8","Le bord supérieur de la 1ʳᵉ côte","Le sternum et les cartilages costaux 1 à 6"],"r":0,"e":"Le petit pectoral naît des côtes 3-5 pour gagner le processus coracoïde.","s":3},{"q":"Quelle est l'action du petit pectoral sur la scapula ?","o":["Une bascule antérieure, protraction et dépression","Une rotation supérieure, avec élévation","Une élévation pure, sans rotation","Une rétraction, avec rotation inférieure de la scapula"],"r":0,"e":"Le petit pectoral bascule la scapula en avant (protraction + dépression), d'où son implication dans les épaules enroulées.","s":3},{"q":"Quelle est l'origine du sous-clavier ?","o":["La 1ʳᵉ côte et son cartilage","La 2ᵉ côte, sur son bord supérieur","Le manubrium du sternum","Le processus coracoïde"],"r":0,"e":"Le sous-clavier naît de la 1ère côte et se termine sous la clavicule, stabilisant l'articulation sterno-claviculaire.","s":3},{"q":"Sur quoi s'insère le deltoïde ?","o":["Le V deltoïdien de la diaphyse humérale","Le trochiter, sur sa facette supérieure","Le trochin, sur la face antérieure","Le sillon intertuberculaire, en avant"],"r":0,"e":"Le deltoïde se termine sur le V deltoïdien de la diaphyse humérale ; le trochiter reçoit le supra-épineux, l'infra-épineux et le petit rond.","s":3},{"q":"Quelle est l'action des fibres postérieures du deltoïde ?","o":["Extension, rotation externe, abduction horizontale","Flexion, rotation interne, adduction horizontale","Abduction pure uniquement","Adduction et rotation interne"],"r":0,"e":"Les fibres postérieures étendent et tournent l'humérus en dehors ; ce sont les antérieures qui fléchissent et tournent en dedans.","s":3},{"q":"Sur quelle face du trochiter s'insère l'infra-épineux ?","o":["La face postérieure","La face supérieure","La face antérieure","Il ne s'insère pas sur le trochiter"],"r":0,"e":"L'infra-épineux et le petit rond gagnent la face postérieure du trochiter, le supra-épineux sa face supérieure.","s":3},{"q":"Quelle est l'origine du petit rond (teres minor) ?","o":["Bord latéral de la scapula","Fosse infra-épineuse","Fosse sub-scapulaire","Angle inférieur de la scapula"],"r":0,"e":"Le petit rond naît du bord latéral de la scapula ; l'angle inférieur donne le grand rond.","s":3},{"q":"Quel nerf innerve le petit rond ?","o":["Le nerf axillaire, issu de C5","Le nerf supra-scapulaire, C5","Le nerf sous-scapulaire, C5 et C6","Le nerf thoraco-dorsal, de C6 à C8"],"r":0,"e":"Le petit rond partage le nerf axillaire avec le deltoïde ; l'infra-épineux dépend du supra-scapulaire.","s":3},{"q":"Sur quel relief humeral s'insère le sous-scapulaire ?","o":["Le trochin, en avant","Le trochiter, en dehors","Le sillon intertuberculaire, entre les deux","Le V deltoïdien, sur la diaphyse"],"r":0,"e":"Seul rotateur interne de la coiffe, le sous-scapulaire se fixe sur le trochin, en avant.","s":3},{"q":"Quels sont les deux chefs d'origine du grand pectoral ?","o":["Un chef claviculaire et un chef sterno-costal","Un chef long et un chef court, côte à côte","Un chef sternal et un chef scapulaire","Un chef costal et un chef coracoïdien"],"r":0,"e":"Le grand pectoral naît de la moitié interne de la clavicule et du sternum avec les cartilages 1-6.","s":3},{"q":"Quelle est l'origine du coraco-brachial ?","o":["Le processus coracoïde","Le tubercule supra-glénoïdien","Le bord latéral de la scapula","L'acromion"],"r":0,"e":"Le coraco-brachial naît de la coracoïde, comme le chef court du biceps et le petit pectoral.","s":3},{"q":"Quelle est l'origine du grand rond (teres major) ?","o":["L'angle inférieur et le bas du bord latéral","La fosse infra-épineuse, dans sa partie moyenne","Le haut du bord latéral de la scapula","La fosse sub-scapulaire, en avant"],"r":0,"e":"Le grand rond naît de l'angle inférieur de la scapula et rejoint le sillon intertuberculaire. Il s'agit du bord latéral de la scapula.","s":3},{"q":"Sur quoi s'insère le brachial antérieur ?","o":["La tubérosité ulnaire et le processus coronoïde","La tubérosité radiale et le col du radius, en avant","L'olécrane, sur sa face supérieure","Le processus styloïde du radius"],"r":0,"e":"Le brachial antérieur se fixe sur l'ulna (tubérosité ulnaire + coronoïde), ce qui en fait un fléchisseur huméro-ulnaire pur.","s":3},{"q":"Sur quoi s'insère le brachio-radial ?","o":["Le processus styloïde du radius","La tubérosité radiale","Le corps médian du radius","L'olécrane"],"r":0,"e":"Le brachio-radial descend jusqu'au processus styloïde radial, bras de levier très distal.","s":3},{"q":"Sur quoi s'insère le carré pronateur ?","o":["La face antérieure du radius distal","Le tiers moyen du corps du radius","La face latérale du radius proximal, en haut","Le bec de l'olécrane, en arrière"],"r":0,"e":"Le carré pronateur relie les extrémités distales antérieures de l'ulna et du radius ; le rond pronateur se fixe au tiers moyen du radius.","s":3},{"q":"Le fléchisseur radial du carpe (FCR) est innervé par :","o":["Nerf médian","Nerf ulnaire","Nerf radial","Nerf musculo-cutané"],"r":0,"e":"FCR = nerf médian (C6-C7).","s":4},{"q":"Le fléchisseur ulnaire du carpe (FCU) est innervé par :","o":["Le nerf médian, de C6 à T1","Le nerf ulnaire, C8 et T1","Le nerf radial, de C5 à T1","Le nerf axillaire, C5 et C6, en arrière"],"r":1,"e":"FCU = nerf ULNAIRE (exception parmi les fléchisseurs).","s":4},{"q":"Le fléchisseur profond des doigts a une innervation :","o":["Médian seul, pour les quatre doigts","Ulnaire seul, pour les quatre doigts","Médian pour 2 et 3, ulnaire pour 4 et 5","Radial pour les doigts 2 et 3, médian pour 4 et 5"],"r":2,"e":"FDP : double innervation — médian pour les doigts 2-3 et ulnaire pour 4-5.","s":4},{"q":"Tous les extenseurs du poignet et des doigts sont innervés par :","o":["Nerf médian","Nerf ulnaire","Nerf radial","Nerf axillaire"],"r":2,"e":"Tous les extenseurs de l'avant-bras (poignet, doigts, pouce) sont innervés par le nerf radial.","s":4},{"q":"L'extenseur ulnaire du carpe a pour action :","o":["Flexion + déviation ulnaire","Extension + déviation ulnaire","Extension + déviation radiale","Pronation"],"r":1,"e":"ECU : extension + déviation ULNAIRE du poignet.","s":4},{"q":"Le long abducteur du pouce s'insère sur :","o":["La phalange distale du 1ᵉʳ doigt","La base du 1ᵉʳ métacarpien","La phalange proximale du 1ᵉʳ doigt","Le tubercule du trapèze, près du 1ᵉʳ doigt"],"r":1,"e":"APL → base du 1er métacarpien.","s":4},{"q":"L'opposition du pouce nécessite :","o":["Adduction, extension et rotation, en même temps","Abduction, flexion et rotation du pouce","Extension pure, sans rotation","Adduction et rotation seules"],"r":1,"e":"Opposition du pouce = abduction + flexion + rotation à la CMC1.","s":4},{"q":"Les muscles de l'éminence hypothénar sont tous innervés par :","o":["Médian","Ulnaire","Radial","Musculo-cutané"],"r":1,"e":"Tous les muscles de l'éminence hypothénar = nerf ulnaire.","s":4},{"q":"Le court abducteur du pouce est innervé par :","o":["Médian","Ulnaire","Radial","Mixte"],"r":0,"e":"Court abducteur du pouce (APB) = médian.","s":4},{"q":"L'adducteur du pouce est innervé par :","o":["Le nerf médian, de C6 à T1","Le nerf ulnaire, C8 et T1","Le nerf radial, de C5 à T1, en arrière","Les nerfs médian et ulnaire, C8 et T1"],"r":1,"e":"Adducteur du pouce = ulnaire (exception parmi les muscles thénar).","s":4},{"q":"Les interosseux palmaires font :","o":["Abduction des doigts","Adduction des doigts","Flexion pure","Extension pure"],"r":1,"e":"PAD : Palmaires Adduisent (vers le 3e doigt).","s":4},{"q":"Les interosseux dorsaux font :","o":["Adduction","Abduction des doigts","Flexion pure","Extension pure"],"r":1,"e":"DAB : Dorsaux Abductent (s'écartent du 3e doigt).","s":4},{"q":"Tous les interosseux sont innervés par :","o":["Médian","Ulnaire","Radial","Mixte"],"r":1,"e":"Tous les interosseux (palmaires + dorsaux) = nerf ulnaire.","s":4},{"q":"Les lombricaux 2 et 3 sont innervés par :","o":["Ulnaire","Médian","Radial","Mixte"],"r":1,"e":"Lombricaux 2 et 3 = médian. Lombricaux 4 et 5 = ulnaire.","s":4},{"q":"Les lombricaux ont pour origine :","o":["Les bases des métacarpiens","Les os du carpe, en avant","Les tendons du fléchisseur profond","Le trapèze et le tubercule du scaphoïde"],"r":2,"e":"Origine des lombricaux : 4 tendons du fléchisseur profond des doigts.","s":4},{"q":"L'action des lombricaux est :","o":["L'extension des MP et des IP","La flexion des MP et l'extension des IP","L'adduction des doigts, avec les MP en flexion","L'abduction des doigts, IP tendues"],"r":1,"e":"Lombricaux : flexion des MP + extension des IP (position d'écriture).","s":4},{"q":"Le long fléchisseur du pouce est innervé par :","o":["Le nerf ulnaire, C8 et T1","Le nerf médian, de C8 à T1","Le nerf radial, de C5 à T1","Le nerf axillaire, C5"],"r":1,"e":"Long fléchisseur du pouce (FPL) = médian (C8-T1).","s":4},{"q":"Le long extenseur du pouce est innervé par :","o":["Médian","Ulnaire","Radial","Musculo-cutané"],"r":2,"e":"Tous les extenseurs du pouce = nerf radial.","s":4},{"q":"Le fléchisseur superficiel des doigts s'insère sur :","o":["Les phalanges distales des doigts 2 à 5","Les phalanges moyennes des doigts 2 à 5","Les phalanges proximales des doigts 2 à 5","Les têtes des métacarpiens 2 à 5"],"r":1,"e":"FDS → phalanges moyennes des doigts 2-5.","s":4},{"q":"Le fléchisseur profond des doigts s'insère sur :","o":["Les phalanges moyennes des doigts 2 à 5, en avant","Les phalanges distales des doigts 2 à 5","Les phalanges proximales des doigts 2 à 5","Les têtes des métacarpiens 2 à 5"],"r":1,"e":"FDP → phalanges distales des doigts 2-5 (pour fermer le poing complètement).","s":4},{"q":"L'extenseur commun des doigts a pour origine :","o":["Épicondyle médial","Épicondyle latéral","Olécrane","Cubitus"],"r":1,"e":"EDC = épicondyle latéral (comme tous les extenseurs).","s":4},{"q":"L'origine de la plupart des fléchisseurs est :","o":["Épicondyle latéral","Épicondyle médial","Olécrane","Radius distal"],"r":1,"e":"Les fléchisseurs ont leur origine à l'épicondyle MÉDIAL (« tendon des fléchisseurs »).","s":4},{"q":"Le tendon du long palmaire s'insère sur :","o":["Le pisiforme","L'aponévrose palmaire","Le 5e métacarpien","Le scaphoïde"],"r":1,"e":"Long palmaire → aponévrose palmaire (fascia palmaire).","s":4},{"q":"L'éminence thénar est constituée de :","o":["Court fléchisseur, court abducteur et opposant du pouce","Abducteur, court fléchisseur et opposant de l'auriculaire","Lombricaux et interosseux palmaires des doigts 2 et 3","Interosseux dorsaux et palmaires du premier espace"],"r":0,"e":"Thénar = court fléchisseur pouce, court abducteur pouce, opposant pouce (+ parfois l'adducteur considéré à part). L'adducteur du pouce y est souvent rattaché, à part.","s":4},{"q":"L'opposition du pouce permet :","o":["De pincer fermement","De tendre le bras","D'étendre le poignet","De fléchir l'épaule"],"r":0,"e":"L'opposition du pouce est essentielle à la pince fine (toucher l'extrémité des autres doigts).","s":4},{"q":"Le fléchisseur radial du carpe fait, sur le poignet :","o":["Flexion + déviation ulnaire","Flexion + déviation radiale","Extension + déviation radiale","Extension pure"],"r":1,"e":"FCR : flexion + déviation radiale.","s":4},{"q":"Le long extenseur radial du carpe s'insère sur :","o":["Base du 2e métacarpien","Base du 3e métacarpien","Base du 5e métacarpien","Phalange proximale"],"r":0,"e":"ECRL → base du 2e métacarpien (côté dorsal).","s":4},{"q":"Le court extenseur radial du carpe s'insère sur :","o":["Base du 2e métacarpien","Base du 3e métacarpien","Base du 5e métacarpien","Trapèze"],"r":1,"e":"ECRB → base du 3e métacarpien.","s":4},{"q":"Lors de la paralysie du nerf médian, la main devient :","o":["Une main en griffe, sur les deux derniers doigts","Une main de singe, sans opposition du pouce","Une main tombante, sans extension du poignet","Une main en supination, sans pronation"],"r":1,"e":"Atteinte du médian : « main de singe » avec perte de l'opposition du pouce.","s":4},{"q":"Lors d'une paralysie du nerf radial, la main est :","o":["En griffe, doigts 4 et 5 fléchis","En main de singe, pouce aligné","Tombante, sans extension du poignet","En supination, paume vers le haut"],"r":2,"e":"Atteinte du radial : main tombante (incapacité d'étendre le poignet).","s":4},{"q":"Sur quoi s'insère le fléchisseur radial du carpe (FCR) ?","o":["Les bases palmaires des métacarpiens 2 et 3","Le pisiforme et l'hamatum, en dedans","L'aponévrose palmaire, au centre de la main","La base dorsale du 1ᵉʳ métacarpien, côté radial"],"r":0,"e":"Le FCR gagne les bases palmaires de M2 et M3 ; le pisiforme et l'hamatum reçoivent le FCU.","s":4},{"q":"Quelle est l'action du long palmaire sur le fascia palmaire ?","o":["Il le met en tension","Il le relâche","Il l'abduit","Il n'a aucun rapport avec lui"],"r":0,"e":"Le long palmaire se termine sur l'aponévrose palmaire et la tend, en plus de fléchir le poignet.","s":4},{"q":"Quelle est l'origine du fléchisseur ulnaire du carpe (FCU) ?","o":["L'épicondyle médial et la face postérieure du cubitus","L'épicondyle latéral seul, sans chef ulnaire","La crête supracondylienne latérale de l'humérus","La face antérieure du radius et la membrane interosseuse"],"r":0,"e":"Le FCU naît de l'épicondyle médial, origine commune des fléchisseurs, avec un chef ulnaire proximal.","s":4},{"q":"Quelle particularité présente le tendon du fléchisseur superficiel des doigts ?","o":["Il est bifurqué et se termine sur les phalanges moyennes","Il est entier et se termine sur les phalanges distales","Il est bifurqué et se termine sur les phalanges proximales","Il est entier et se termine sur l'aponévrose palmaire"],"r":0,"e":"Le tendon du FDS se bifurque pour laisser passer celui du FDP et se fixe sur la phalange moyenne des doigts 2-5.","s":4},{"q":"Quelle est l'origine du fléchisseur profond des doigts (FDP) ?","o":["Le cubitus proximal et la membrane interosseuse","L'épicondyle médial, origine commune des fléchisseurs","La face antérieure du radius, sur son tiers moyen","L'épicondyle latéral et le ligament annulaire"],"r":0,"e":"Le FDP naît de l'ulna et de la membrane interosseuse ; le FDS a une origine épicondylienne médiale.","s":4},{"q":"Quel mouvement exige spécifiquement le fléchisseur profond des doigts ?","o":["Fermer le poing serré, en fléchissant l'IFD","Fléchir isolément l'IFP, l'IFD restant libre","Étendre les doigts, MP et IP comprises","Écarter les doigts, en abduction depuis le majeur"],"r":0,"e":"Seul le FDP fléchit l'interphalangienne distale, d'où le poing serré.","s":4},{"q":"Quelle est l'origine du long extenseur radial du carpe (ECRL) ?","o":["Crête supracondylienne latérale","Épicondyle latéral","Épicondyle médial","Corps postérieur du cubitus"],"r":0,"e":"L'ECRL naît plus haut que les autres extenseurs, sur la crête supracondylienne latérale, ce qui lui permet d'aider la flexion du coude.","s":4},{"q":"Quelle est l'origine de l'extenseur ulnaire du carpe (ECU) ?","o":["L'épicondyle latéral et le bord postérieur du cubitus","L'épicondyle médial et le bord antérieur du cubitus","La crête supracondylienne latérale de l'humérus","La face postérieure du radius distal"],"r":0,"e":"L'ECU naît de l'épicondyle latéral avec un chef ulnaire, et gagne la base dorsale de M5.","s":4},{"q":"Sur quoi s'insère l'extenseur commun des doigts (EDC) ?","o":["Les phalanges proximales et distales des doigts 2 à 5","Les seules phalanges moyennes des doigts 2 à 5","Les bases dorsales des métacarpiens 2 à 5, côté radial","L'aponévrose palmaire, en avant des doigts 2 à 5"],"r":0,"e":"L'EDC se termine sur les phalanges proximale et distale des quatre derniers doigts par l'appareil extenseur dorsal. Il agit par l'appareil extenseur dorsal.","s":4},{"q":"Quelle est l'origine du long fléchisseur du pouce (FPL) ?","o":["La face antérieure du radius et la membrane interosseuse","L'épicondyle médial, avec tous les autres fléchisseurs","La face postérieure du cubitus, en arrière","La face postérieure du radius, en distal"],"r":0,"e":"Le FPL naît de la face antérieure du radius et de la membrane interosseuse, et fléchit la phalange distale du pouce.","s":4},{"q":"Quelle action le long abducteur du pouce exerce-t-il sur le poignet ?","o":["Une déviation radiale","Une déviation ulnaire","Une flexion pure","Aucune action sur le poignet"],"r":0,"e":"En plus de l'abduction et de l'extension du pouce, l'APL participe à la déviation radiale du poignet.","s":4},{"q":"Sur quoi s'insère le court extenseur du pouce (EPB) ?","o":["La base dorsale de la phalange proximale du pouce","La base dorsale de la phalange distale du pouce","La base dorsale du 1ᵉʳ métacarpien","Le tubercule du trapèze, côté palmaire"],"r":0,"e":"L'EPB s'arrête à la phalange proximale (MP, CM) alors que l'EPL va jusqu'à la phalange distale.","s":4},{"q":"Quelle est l'origine du court extenseur du pouce (EPB) ?","o":["Le radius distal postérieur et la membrane interosseuse","Le cubitus, sur sa face postérieure moyenne","L'épicondyle latéral, avec les extenseurs","La face antérieure du radius et la membrane interosseuse"],"r":0,"e":"L'EPB naît du radius distal postérieur ; l'EPL naît du cubitus médian postérieur.","s":4},{"q":"Quelle est l'innervation du court fléchisseur du pouce (FPB) ?","o":["Double, par le médian et par l'ulnaire","Simple, par le médian uniquement","Simple, par l'ulnaire uniquement","Simple, par le radial uniquement"],"r":0,"e":"Le FPB a une double innervation, chef superficiel par le médian et chef profond par l'ulnaire.","s":4},{"q":"Quelle est l'origine de l'adducteur du pouce ?","o":["Le capitatum et les métacarpiens 2 et 3","Le scaphoïde, le trapèze et le 1ᵉʳ métacarpien","Le pisiforme, l'hamatum et le 5ᵉ métacarpien","L'aponévrose palmaire et le 4ᵉ métacarpien"],"r":0,"e":"L'adducteur du pouce naît du plan profond du carpe et de M3, et se fixe sur la base de la phalange proximale du pouce, côté ulnaire. Il naît surtout du 3ᵉ métacarpien, de l'os capité et des bases des métacarpiens 2 et 3.","s":4},{"q":"Combien y a-t-il d'interosseux palmaires ?","o":["3","4","5","2"],"r":0,"e":"Trois interosseux palmaires (adducteurs) pour quatre interosseux dorsaux (abducteurs).","s":4},{"q":"Quelle est l'origine des interosseux palmaires ?","o":["Les métacarpiens 2, 4 et 5, côté du 3ᵉ doigt","Les tendons du fléchisseur profond, doigts 2 à 5","L'os capité et les métacarpiens 2 et 3","L'épicondyle médial et le métacarpien 5"],"r":0,"e":"Ils naissent des métacarpiens 2, 4 et 5 et rapprochent les doigts du 3e ; ce sont les lombricaux qui naissent des tendons du FDP.","s":4},{"q":"Quelle action les interosseux ont-ils sur les métacarpo-phalangiennes et les interphalangiennes ?","o":["Flexion MP et extension IP","Extension MP et flexion IP","Flexion MP et IP","Extension MP et IP"],"r":0,"e":"Palmaires comme dorsaux fléchissent les MP et étendent les IP via les expansions dorsales, comme les lombricaux.","s":4},{"q":"Que signifie le moyen mnémotechnique DAB / PAD ?","o":["Dorsal Abduct, Palmar Adduct","Dorsal Adduct, Palmar Abduct","Doigts Abducteurs, Pouce Adducteur","Distal Abduct, Proximal Adduct"],"r":0,"e":"Les interosseux dorsaux abduisent (écartent) et les palmaires adduisent (rapprochent) par rapport à l'axe du 3e doigt.","s":4},{"q":"Sur quoi se terminent les lombricaux ?","o":["Les expansions dorsales de l'extenseur commun","Les bases des phalanges distales, en avant","Les bases des métacarpiens, en avant","L'aponévrose palmaire, au centre"],"r":0,"e":"Nés des tendons du fléchisseur profond, les lombricaux rejoignent l'appareil extenseur dorsal, d'où leur action flexion MP / extension IP.","s":4},{"q":"Le grand fessier (gluteus maximus) est innervé par :","o":["Le nerf glutéal supérieur, de L4 à S1","Le nerf glutéal inférieur, de L5 à S2","Le nerf fémoral, de L2 à L4","Le nerf sciatique, de L4 à S3, par sa partie tibiale"],"r":1,"e":"Gluteus maximus = nerf glutéal INFÉRIEUR.","s":5},{"q":"Le moyen fessier (gluteus medius) est innervé par :","o":["Le nerf glutéal supérieur, issu de L4 à S1","Le nerf glutéal inférieur, de L5 à S2","Le nerf fémoral, de L2 à L4","Le nerf obturateur, de L2 à L4"],"r":0,"e":"Gluteus medius = nerf glutéal SUPÉRIEUR.","s":5},{"q":"L'action principale du moyen fessier est :","o":["Flexion","Abduction de la hanche","Extension","Rotation interne pure"],"r":1,"e":"Moyen fessier = abducteur principal de la hanche.","s":5},{"q":"L'action principale du grand fessier est :","o":["La flexion et la rotation interne","L'extension et la rotation externe","L'abduction et la rotation interne","L'adduction et la rotation externe"],"r":1,"e":"Grand fessier : extension + rotation externe de la hanche.","s":5},{"q":"Tous les rotateurs profonds s'insèrent sur :","o":["Le petit trochanter","Le grand trochanter","Le col fémoral","La tête fémorale"],"r":1,"e":"Tous les rotateurs profonds (6) s'insèrent sur le grand trochanter.","s":5},{"q":"L'action commune des rotateurs profonds est :","o":["La rotation interne de la hanche","La rotation latérale de la hanche","La flexion pure de la hanche","L'abduction de la hanche"],"r":1,"e":"Tous les rotateurs profonds = rotation externe de la hanche.","s":5},{"q":"L'iliopsoas est composé de :","o":["Iliaque + psoas","Pectiné + iliaque","Psoas + sartorius","Iliaque + sartorius"],"r":0,"e":"Iliopsoas = iliaque + psoas (fléchisseur principal de la hanche).","s":5},{"q":"L'iliaque s'insère sur :","o":["Le grand trochanter","Le petit trochanter","La crête iliaque","La rotule"],"r":1,"e":"Iliaque → petit trochanter.","s":5},{"q":"L'iliaque est innervé par :","o":["Le nerf obturateur, L2 à L4","Le nerf fémoral, issu de L2 et L3","Le nerf glutéal supérieur, L4","Le nerf sciatique, L4 à S3"],"r":1,"e":"Iliaque = nerf fémoral.","s":5},{"q":"Le psoas est innervé par :","o":["Le nerf fémoral, de L2 à L4","Le plexus lombaire, de L2 à L4","Le nerf obturateur, par ses branches de L2 à L4","Le nerf glutéal supérieur, de L4 à S1"],"r":1,"e":"Psoas = plexus lombaire (rameaux directs L2-L4).","s":5},{"q":"Le sartorius (couturier) a pour origine :","o":["EIAI","EIAS","Pubis","Ischium"],"r":1,"e":"Sartorius = EIAS (épine iliaque antéro-supérieure).","s":5},{"q":"Le TFL (tensor fascia latae) s'insère sur :","o":["Le grand trochanter, par sa face latérale","Le condyle latéral du tibia, par le tractus","Le condyle médial du tibia, par la patte d'oie","La rotule, par l'aileron latéral et le tendon rotulien"],"r":1,"e":"TFL s'insère via le tractus iliotibial sur le condyle latéral du tibia. Il s'agit du tractus iliotibial.","s":5},{"q":"Les adducteurs sont principalement innervés par :","o":["Nerf obturateur","Nerf fémoral","Nerf sciatique","Nerf glutéal"],"r":0,"e":"La majorité des adducteurs (long, court, gracile, magnus partiel) = nerf obturateur.","s":5},{"q":"L'adducteur magnus a une double innervation :","o":["Obturateur + sciatique","Fémoral + obturateur","Sciatique + fémoral","Obturateur seul"],"r":0,"e":"Adducteur magnus : nerf obturateur (fibres antérieures) + nerf sciatique (fibres postérieures ischio-condylaires).","s":5},{"q":"La patte d'oie (pes anserinus) est composée de :","o":["Sartorius, gracile, semi-tendineux","Sartorius, droit fémoral, semi-membraneux","Sartorius, gracile, semi-membraneux","Semi-tendineux, semi-membraneux, biceps"],"r":0,"e":"Patte d'oie : Sartorius + Gracile + Semi-tendineux (de superficiel à profond).","s":5},{"q":"Le quadriceps a combien de chefs ?","o":["Deux, le droit fémoral et un vaste","Trois, le droit fémoral et deux vastes","Quatre, le droit fémoral et trois vastes","Cinq, le droit fémoral et quatre vastes distincts"],"r":2,"e":"Quadriceps = droit fémoral + vaste latéral + vaste médial + vaste intermédiaire.","s":5},{"q":"Le quadriceps est innervé par :","o":["Le nerf obturateur, de L2 à L4, en dedans","Le nerf fémoral, de L2 à L4","Le nerf sciatique, de L4 à S3","Le nerf tibial, de L4 à S3"],"r":1,"e":"Tous les chefs du quadriceps = nerf fémoral.","s":5},{"q":"L'action commune du quadriceps est :","o":["Flexion du genou","Extension du genou","Rotation","Adduction"],"r":1,"e":"Quadriceps = extension du genou.","s":5},{"q":"Le droit fémoral est biarticulaire car :","o":["Il agit sur la hanche et sur le genou","Il possède deux chefs d'origine distincts","Il reçoit deux nerfs, fémoral et obturateur","Il se termine sur la rotule et le tibia"],"r":0,"e":"Le droit fémoral : extension du genou + flexion de la hanche (biarticulaire).","s":5},{"q":"Les ischio-jambiers comprennent :","o":["Biceps fémoral, semi-tendineux et semi-membraneux","Quadriceps, gracile et sartorius du genou","Sartorius, tenseur du fascia lata et gracile","Grand, moyen et court adducteurs"],"r":0,"e":"Ischio-jambiers : biceps fémoral + semi-tendineux + semi-membraneux.","s":5},{"q":"Le biceps fémoral s'insère sur :","o":["Le tibia","La tête du péroné","Le condyle médial","La rotule"],"r":1,"e":"Biceps fémoral → tête du péroné (latéralement).","s":5},{"q":"L'action des ischio-jambiers sur le genou est :","o":["Extension","Flexion","Rotation pure","Abduction"],"r":1,"e":"Ischio-jambiers = flexion du genou (+ extension de la hanche).","s":5},{"q":"Le biceps fémoral fait quelle rotation du genou ?","o":["Une rotation médiale, ou interne, du tibia","Une rotation latérale, ou externe","Aucune rotation, il fléchit seulement","Une pronation, comme à l'avant-bras"],"r":1,"e":"Biceps fémoral : flexion + rotation LATÉRALE du genou.","s":5},{"q":"Le semi-tendineux fait quelle rotation du genou ?","o":["Latérale","Médiale","Aucune","Externe"],"r":1,"e":"Semi-tendineux et semi-membraneux : flexion + rotation MÉDIALE du genou.","s":5},{"q":"Les ischio-jambiers sont innervés par :","o":["Le nerf fémoral, par ses branches musculaires","Le nerf sciatique, surtout par sa partie tibiale","Le nerf glutéal inférieur, avec le grand fessier","Le nerf obturateur, par sa branche postérieure"],"r":1,"e":"Ischio-jambiers = nerf sciatique (partie tibiale L5-S2, sauf chef court du biceps = partie péronière).","s":5},{"q":"Le poplité agit sur :","o":["La cheville, en flexion plantaire et en inversion du pied","Le genou, en rotation médiale pour le déverrouiller","La hanche, en rotation latérale","Le pied, en inversion et en adduction"],"r":1,"e":"Poplité : rotation médiale du genou, débloque le genou en extension. Il débloque le genou en extension.","s":5},{"q":"Le poplité est innervé par :","o":["Nerf fémoral","Nerf sciatique","Nerf tibial","Nerf péronier"],"r":2,"e":"Poplité = nerf tibial (L4, L5, S1).","s":5},{"q":"Le piriforme (pyramidal) est innervé par :","o":["Le nerf obturateur, de L2 à L4, en avant","Le plexus sacré, par S1 et S2","Le nerf fémoral, de L2 à L4","Le nerf sciatique, de L4 à S3"],"r":1,"e":"Piriforme = plexus sacré (S1, S2).","s":5},{"q":"L'obturateur externe est le seul rotateur profond innervé par :","o":["Le plexus sacré, par S1 et S2","Le nerf obturateur, par L3 et L4","Le nerf fémoral, par L2 et L3","Le nerf sciatique, par L4 à S3, partie tibiale"],"r":1,"e":"Obturateur externe = nerf obturateur (les 5 autres rotateurs profonds = plexus sacré).","s":5},{"q":"L'adducteur magnus, partie postérieure, fait :","o":["Flexion","Extension de la hanche","Rotation externe","Abduction"],"r":1,"e":"Les fibres postérieures (ischio-condylaires) du grand adducteur participent à l'EXTENSION de la hanche (rôle ischio-jambier-like).","s":5},{"q":"Quelle est l'origine du grand fessier ?","o":["Crête iliaque, sacrum, coccyx et ligament sacro-tubéreux","Face supéro-latérale de l'ilium, sous la crête iliaque","Face inféro-latérale de l'ilium, sous le moyen fessier","Tubérosité ischiatique, branche ischio-pubienne et pubis"],"r":0,"e":"Le grand fessier a une large origine postérieure ; la face supéro-latérale de l'ilium donne le moyen fessier. L'ilium postérieur en fait aussi partie.","s":5},{"q":"Sur quoi s'insère le grand fessier ?","o":["La tubérosité glutéale du fémur et la bande iliotibiale","Le grand trochanter, sur sa face latérale et antérieure","Le petit trochanter, avec le tendon du psoas","La tête du péroné, par le tractus iliotibial"],"r":0,"e":"Le grand fessier se termine en partie sur la tubérosité glutéale et en partie sur le tractus iliotibial ; le grand trochanter reçoit les moyen et petit fessiers.","s":5},{"q":"Que font les fibres inférieures du grand fessier ?","o":["Une adduction","Une abduction","Une rotation interne","Une flexion"],"r":0,"e":"Les fibres inférieures adduisent, les fibres supérieures abduisent.","s":5},{"q":"Quelle est l'action des fibres antérieures du moyen fessier ?","o":["Flexion et rotation interne","Extension et rotation externe","Adduction pure","Rotation externe seule"],"r":0,"e":"Les fibres antérieures du gluteus medius fléchissent et tournent en dedans, les postérieures étendent et tournent en dehors.","s":5},{"q":"Quelle est l'origine du petit fessier ?","o":["La face inféro-latérale de l'ilium, en profondeur","La face supéro-latérale de l'ilium, sous la crête","La face antérieure du sacrum, près des trous sacrés","La crête iliaque postérieure, en arrière du sacrum"],"r":0,"e":"Le gluteus minimus est situé sous le moyen fessier, sur la face inféro-latérale de l'ilium. Il est situé sous le moyen fessier.","s":5},{"q":"Quelle est l'action du petit fessier ?","o":["Abduction et rotation interne","Abduction et rotation externe","Extension et rotation externe","Adduction"],"r":0,"e":"Le petit fessier abduit et tourne en dedans, comme les fibres antérieures du moyen fessier.","s":5},{"q":"Combien de rotateurs profonds de la hanche la fiche décrit-elle ?","o":["6","4","5","7"],"r":0,"e":"Piriforme, gemellus supérieur, obturateur interne, gemellus inférieur, obturateur externe et carré fémoral : six muscles.","s":5},{"q":"Quelle est l'origine du piriforme ?","o":["La face antérieure du sacrum","La tubérosité de l'ischium, en arrière","Le pourtour du foramen obturateur","La crête iliaque postérieure"],"r":0,"e":"Le piriforme naît du sacrum antérieur et gagne le grand trochanter ; les gemelli et le carré fémoral naissent de l'ischium.","s":5},{"q":"Quelle est l'origine du psoas ?","o":["Les corps et transverses de T12 à L5","La fosse iliaque interne et la base du sacrum, en avant","Les transverses de L4 et L5 et la crête iliaque","La branche supérieure du pubis"],"r":0,"e":"Le psoas naît du rachis thoraco-lombaire ; l'iliaque naît de la fosse iliaque.","s":5},{"q":"Que provoque la contraction de l'iliopsoas lorsque le fémur est fixe ?","o":["Une inclinaison pelvienne antérieure","Une inclinaison pelvienne postérieure","Une rotation du bassin","Une abduction de hanche"],"r":0,"e":"Fémur fixé, l'iliopsoas bascule le bassin en avant, le psoas majorant en outre la lordose lombaire.","s":5},{"q":"Quelle est l'origine du tenseur du fascia lata (TFL) ?","o":["La crête iliaque, juste en arrière de l'EIAS","L'EIAS elle-même, avec le muscle sartorius voisin","L'EIAI, avec le tendon direct du droit fémoral","La branche inférieure du pubis, en dedans"],"r":0,"e":"Le TFL naît juste en arrière de l'EIAS ; l'EIAS elle-même donne le sartorius et l'EIAI le droit fémoral.","s":5},{"q":"Quelle rotation de hanche le sartorius produit-il ?","o":["Une rotation externe","Une rotation interne","Aucune rotation","Une rotation externe puis interne"],"r":0,"e":"Le sartorius fléchit, abduit et tourne la hanche en dehors, tout en fléchissant et tournant le genou en dedans. Le TFL, lui, tourne la hanche en dedans.","s":5},{"q":"Quelle est l'origine du pectiné ?","o":["Branche supérieure du pubis","Branche inférieure du pubis","Tubercule pubien","Tubérosité ischiatique"],"r":0,"e":"Le pectiné naît de la branche supérieure du pubis et gagne la ligne pectinée du fémur.","s":5},{"q":"Quelle est l'origine de l'adducteur long ?","o":["Le tubercule pubien","La branche inférieure du pubis","La branche supérieure du pubis","La tubérosité ischiatique"],"r":0,"e":"L'adducteur long naît du tubercule pubien ; l'adducteur court naît de la branche inférieure du pubis.","s":5},{"q":"Quel muscle adducteur se termine sur le tubercule de l'adducteur ?","o":["L'adducteur magnus","L'adducteur long","Le pectiné","Le gracile"],"r":0,"e":"Le grand adducteur s'étend sur toute la ligne âpre et atteint le tubercule de l'adducteur, au-dessus du condyle médial.","s":5},{"q":"Quelle est l'action du gracile sur le genou ?","o":["Flexion et rotation interne","Extension et rotation externe","Extension pure","Aucune action sur le genou"],"r":0,"e":"Le gracile, membre de la patte d'oie, fléchit et tourne le genou en dedans, en plus d'adduire la hanche.","s":5},{"q":"Quelle est l'origine du droit fémoral ?","o":["L'EIAI","L'EIAS","La ligne âpre médiale","Le grand trochanter"],"r":0,"e":"Le droit fémoral naît de l'épine iliaque antéro-inférieure, ce qui le rend biarticulaire ; l'EIAS donne le sartorius.","s":5},{"q":"Où s'insère le chef court du biceps fémoral ?","o":["De la ligne âpre distale à la tête du péroné","De la tubérosité ischiatique au péroné","De la ligne âpre distale à la patte d'oie","De la ligne âpre au condyle médial du tibia"],"r":0,"e":"Le chef court naît de la ligne âpre (donc non biarticulaire) et rejoint le chef long sur la tête du péroné.","s":5},{"q":"Sur quoi s'insère le semi-membraneux ?","o":["Le condyle médial du tibia, en arrière","La patte d'oie, en dedans du tibia","La tête du péroné, en dehors","Le tubercule de Gerdy, sur la face latérale du tibia"],"r":0,"e":"Le semi-membraneux gagne le condyle tibial postéro-médial ; c'est le semi-tendineux qui participe à la patte d'oie.","s":5},{"q":"Quelle est l'origine du poplité ?","o":["Le condyle latéral du fémur","Le condyle médial du fémur","La tubérosité ischiatique","La tête du péroné"],"r":0,"e":"Le poplité naît du condyle fémoral latéral et se termine sur le tibia postéro-médial : il débloque le genou en extension par rotation médiale du tibia.","s":5},{"q":"Le triceps sural est formé par :","o":["Gastrocnémien, soléaire et plantaire grêle","Gastrocnémien seul, avec ses deux chefs","Soléaire seul, avec le tendon d'Achille commun","Soléaire, poplité et tibial postérieur"],"r":0,"e":"Triceps sural = gastrocnémiens (2 chefs) + soléaire + plantaire grêle. Tous se terminent par le tendon d'Achille. Le gastrocnémien a 2 chefs ; tous se terminent par le tendon d'Achille.","s":6},{"q":"Le tendon d'Achille s'insère sur :","o":["L'astragale","Le calcanéum","Le naviculaire","Le cuboïde"],"r":1,"e":"Tendon d'Achille → calcanéum (os du talon).","s":6},{"q":"Le gastrocnémien est biarticulaire car :","o":["Il agit sur la cheville et sur le genou","Il possède deux chefs distincts","Il reçoit deux nerfs différents","Il a deux origines, sur chaque condyle"],"r":0,"e":"Gastrocnémien : flexion plantaire de la cheville + flexion du genou (biarticulaire — origine sur les condyles fémoraux).","s":6},{"q":"Le soléaire est :","o":["Biarticulaire, sur genou et cheville","Uniarticulaire, sur la seule cheville","Triarticulaire, de la hanche au pied","Sans action, simple muscle de soutien veineux"],"r":1,"e":"Soléaire : uniarticulaire, agit uniquement sur la cheville (flexion plantaire). Origine sur tibia + péroné.","s":6},{"q":"Tous les muscles de la loge postérieure de la jambe sont innervés par :","o":["Nerf fibulaire profond","Nerf fibulaire superficiel","Nerf tibial","Nerf fémoral"],"r":2,"e":"Loge postérieure = nerf tibial.","s":6},{"q":"Le tibial postérieur a pour action :","o":["Flexion dorsale + éversion","Flexion plantaire + inversion","Extension orteils","Éversion pure"],"r":1,"e":"Tibial postérieur : flexion plantaire + inversion (inverseur principal).","s":6},{"q":"Le long fléchisseur du gros orteil fléchit :","o":["Tous les orteils, du 1ᵉʳ au 5ᵉ","Le 1ᵉʳ orteil, ou gros orteil","Les orteils 2 à 5, sans le gros orteil","Aucun orteil, il agit sur la cheville"],"r":1,"e":"LFGO (FHL) = flexion du gros orteil (orteil 1).","s":6},{"q":"Le long fléchisseur des orteils fléchit :","o":["Le gros orteil seul, ou 1ᵉʳ orteil","Les orteils 2 à 5, sans le gros orteil","Tous les orteils, du 1ᵉʳ au 5ᵉ","Aucun orteil, il agit sur la cheville"],"r":1,"e":"LFD (FDL) = flexion des orteils 2-5.","s":6},{"q":"Le court et le long fibulaire (peroneus) sont dans la loge :","o":["Antérieure, avec le tibial antérieur","Latérale, ou externe, de la jambe","Postérieure, avec le triceps","Médiale, avec le tibial postérieur"],"r":1,"e":"Loge latérale (externe) = muscles fibulaires (court + long).","s":6},{"q":"Les muscles fibulaires sont innervés par :","o":["Nerf tibial","Nerf fibulaire superficiel","Nerf fibulaire profond","Nerf fémoral"],"r":1,"e":"Loge latérale = nerf fibulaire SUPERFICIEL.","s":6},{"q":"L'action principale des fibulaires (court + long) est :","o":["Inversion","Éversion","Flexion dorsale","Extension"],"r":1,"e":"Court et long fibulaires : éversion du pied.","s":6},{"q":"Le long fibulaire s'insère sur :","o":["La tubérosité du 5ᵉ métatarsien, sur le bord latéral","Le 1ᵉʳ cunéiforme et la base du 1ᵉʳ métatarsien","Le calcanéum, sur sa face latérale","Le scaphoïde tarsien, sur sa tubérosité"],"r":1,"e":"Long fibulaire → 1er cunéiforme + base du 1er métatarsien (tendon passe sous le pied).","s":6},{"q":"Le court fibulaire s'insère sur :","o":["Tubérosité du 5e métatarsien","Base du 1er métatarsien","Calcanéum","Naviculaire"],"r":0,"e":"Court fibulaire → tubérosité du 5e métatarsien.","s":6},{"q":"Le tibial antérieur est dans la loge :","o":["Antérieure","Latérale","Postérieure","Médiale"],"r":0,"e":"Tibial antérieur = loge ANTÉRIEURE.","s":6},{"q":"Le tibial antérieur fait :","o":["La flexion plantaire et l'éversion","La flexion dorsale et l'inversion du pied","La flexion dorsale et l'éversion","La flexion plantaire et l'inversion"],"r":1,"e":"Tibial antérieur : flexion dorsale + inversion du pied.","s":6},{"q":"Tous les muscles de la loge antérieure sont innervés par :","o":["Nerf tibial","Nerf fibulaire superficiel","Nerf fibulaire profond","Nerf fémoral"],"r":2,"e":"Loge antérieure = nerf fibulaire PROFOND.","s":6},{"q":"Le long extenseur des orteils a pour action :","o":["Flexion des orteils 2 à 5 et flexion plantaire","Extension des orteils 2 à 5, flexion dorsale, éversion","Inversion pure du pied, sans action sur les orteils 2 à 5","Flexion plantaire seule, sans action sur les orteils"],"r":1,"e":"LED : extension des orteils 2-5 + flexion dorsale + éversion.","s":6},{"q":"Le long extenseur du gros orteil fait :","o":["La flexion du gros orteil et la flexion plantaire","L'extension du gros orteil et la flexion dorsale","L'inversion du pied, sans action sur l'orteil","L'éversion du pied, sans action sur l'orteil"],"r":1,"e":"LEGO (EHL) : extension du gros orteil + flexion dorsale cheville.","s":6},{"q":"L'inversion du pied combine :","o":["Adduction + supination","Abduction + pronation","Extension + flexion","Rotation interne pure"],"r":0,"e":"Inversion = adduction + supination du pied (face plantaire vers l'intérieur).","s":6},{"q":"L'éversion du pied combine :","o":["Adduction + supination","Abduction + pronation","Flexion plantaire","Rotation interne"],"r":1,"e":"Éversion = abduction + pronation du pied (face plantaire vers l'extérieur).","s":6},{"q":"Les inverseurs du pied sont :","o":["Tibiaux antérieur et postérieur, LFD et LFGO","Long et court fibulaires, et LED","Triceps sural et plantaire grêle","Tibial postérieur seul, sans LFD ni LFGO"],"r":0,"e":"Inverseurs : tibial antérieur, tibial postérieur, LFD, LFGO.","s":6},{"q":"Les éverseurs du pied sont :","o":["Long et court fibulaires, troisième fibulaire et LED","Tibial antérieur, tibial postérieur, LFD et LFGO réunis","Triceps sural, plantaire grêle et LFD","Tibial postérieur seul, avec le LFGO"],"r":0,"e":"Éverseurs : long et court fibulaires + peroneus tertius + LED. Le troisième fibulaire est le peroneus tertius.","s":6},{"q":"Le peroneus tertius (3e fibulaire) est innervé par :","o":["Nerf tibial","Nerf fibulaire superficiel","Nerf fibulaire profond","Nerf fémoral"],"r":2,"e":"Peroneus tertius = nerf fibulaire PROFOND (et non superficiel, exception dans le groupe des fibulaires).","s":6},{"q":"Le plantaire grêle est :","o":["Le muscle principal de flexion plantaire","Un muscle accessoire faible","Le plus important inverseur","Le muscle d'éversion"],"r":1,"e":"Le plantaire grêle : muscle faible, accessoire — aide à la flexion plantaire.","s":6},{"q":"La paralysie du nerf fibulaire profond entraîne :","o":["Une main tombante, par atteinte radiale","Un pied tombant, avec une marche en steppage","Une perte d'inversion, sans steppage","Une perte de flexion plantaire"],"r":1,"e":"Atteinte du fibulaire profond → pied tombant (steppage) — perte de la flexion dorsale.","s":6},{"q":"Le gastrocnémien et le soléaire partagent :","o":["L'origine, sur les condyles du fémur","L'insertion, par le même tendon d'Achille","Le nerf, sans autre point commun","L'action sur le genou, en flexion"],"r":1,"e":"Gastrocnémien et soléaire convergent vers le tendon d'Achille pour s'insérer sur le calcanéum.","s":6},{"q":"Le carré plantaire est un muscle :","o":["De la loge antérieure de la jambe","De la face dorsale du pied, couche 1","Intrinsèque plantaire, de la couche 2","Du membre supérieur, à l'avant-bras, couche 3"],"r":2,"e":"Carré plantaire : muscle intrinsèque du pied, couche 2 plantaire.","s":6},{"q":"L'arche longitudinale médiale du pied est soutenue par :","o":["Le tibial antérieur seul, sans ligament plantaire","Le long fibulaire seul, sans ligament plantaire","Le tibial postérieur, le long fibulaire, les ligaments","Le triceps sural, par le tendon d'Achille seul"],"r":2,"e":"Arche médiale soutenue par le tibial postérieur, le long fibulaire, les muscles intrinsèques et les ligaments plantaires (notamment le ligament calcanéo-naviculaire plantaire). Le ligament calcanéo-naviculaire plantaire y contribue notamment.","s":6},{"q":"Tous les muscles de la loge latérale (peroneus) sont des :","o":["Inverseurs","Éverseurs","Fléchisseurs dorsaux","Extenseurs des orteils"],"r":1,"e":"Loge latérale (peronei) = éverseurs.","s":6},{"q":"Le tibial postérieur est innervé par :","o":["Le fibulaire superficiel, L5","Le fibulaire profond, L4 et L5","Le nerf tibial, issu de L5 et S1","Le nerf fémoral, de L2 à L4"],"r":2,"e":"Tibial postérieur = nerf tibial.","s":6},{"q":"Quelle est l'origine du gastrocnémien ?","o":["Les deux condyles postérieurs du fémur","La ligne soléaire du tibia, en arrière","La face postérieure de la tête du péroné, en haut","Le seul épicondyle latéral du fémur"],"r":0,"e":"Le gastrocnémien naît des condyles fémoraux, ce qui explique son caractère biarticulaire ; le soléaire naît du tibia et du péroné.","s":6},{"q":"Quelle est l'origine du soléaire ?","o":["Le péroné postérieur et la ligne soléaire du tibia","Les condyles postérieurs du fémur, en haut","La membrane interosseuse seule, sur sa hauteur","Le calcanéum, sur sa face postérieure"],"r":0,"e":"Le soléaire naît uniquement de la jambe, d'où son action uniarticulaire de flexion plantaire. Il naît aussi du bord médial du tibia.","s":6},{"q":"Quelle est l'origine du plantaire grêle ?","o":["L'épicondyle latéral postérieur du fémur","L'épicondyle médial postérieur du fémur","La face postérieure du tibia proximal","La face postérieure du péroné distal"],"r":0,"e":"Le plantaire grêle naît juste au-dessus du condyle latéral et aide faiblement la flexion plantaire et l'inversion.","s":6},{"q":"Sur quoi s'insère le tibial postérieur ?","o":["Naviculaire, cuboïde, cunéiformes et métatarsiens","Base du 1ᵉʳ métatarsien seule, face plantaire","Tubérosité du 5ᵉ métatarsien, bord latéral","Calcanéum, sur sa face postérieure"],"r":0,"e":"Le tibial postérieur a une insertion plantaire très étalée, clé du soutien de l'arche médiale. Insertion plantaire, sur les 3 cunéiformes et les métatarsiens 2 à 4.","s":6},{"q":"Quelle est l'origine du long fléchisseur des orteils ?","o":["Le tiers médian du tibia postérieur","Le tiers médian du péroné postérieur","La membrane interosseuse seule","Le condyle latéral du tibia"],"r":0,"e":"Le LFD naît du tibia ; c'est le long fléchisseur du gros orteil qui naît du péroné.","s":6},{"q":"Quelle est l'origine du long fléchisseur du gros orteil ?","o":["Le tiers médian du péroné postérieur","Le tiers médian du tibia postérieur","Le calcanéum","La membrane interosseuse uniquement"],"r":0,"e":"Le LFGO naît du péroné postérieur et se termine sur la base plantaire de la phalange distale de l'hallux.","s":6},{"q":"Quelle est l'origine du court fibulaire ?","o":["La moitié distale du péroné latéral","La tête et les 2/3 proximaux du péroné","Le condyle latéral du tibia","Le tiers distal antérieur du péroné"],"r":0,"e":"Le court fibulaire occupe la moitié distale du péroné, le long fibulaire les deux tiers proximaux.","s":6},{"q":"Quelle particularité présente le trajet du tendon du long fibulaire ?","o":["Il passe sous le pied, jusqu'au bord médial","Il reste latéral, jusqu'au 5ᵉ métatarsien","Il passe en avant de la malléole médiale","Il se termine sur le calcanéum"],"r":0,"e":"Le long fibulaire traverse la plante du pied, ce qui en fait aussi un soutien de l'arche transversale ; c'est le court fibulaire qui s'arrête sur le 5e métatarsien. Il rejoint le 1ᵉʳ cunéiforme et la base du 1ᵉʳ métatarsien.","s":6},{"q":"Quelle est l'origine du tibial antérieur ?","o":["Le condyle latéral et la moitié proximale du tibia","La face antérieure du péroné, dans sa moitié distale","Le condyle médial du tibia, en dedans","La membrane interosseuse seule, en avant"],"r":0,"e":"Le tibial antérieur naît du tibia proximal latéral et se termine sur le 1er cunéiforme et la base de M1.","s":6},{"q":"Sur quoi s'insère le tibial antérieur ?","o":["Le 1ᵉʳ cunéiforme et la base du 1ᵉʳ métatarsien","La tubérosité du 5ᵉ métatarsien, en dehors","Le naviculaire seul, sur sa tubérosité","La base de la phalange distale du gros orteil, en dorsal"],"r":0,"e":"Il partage son insertion avec le long fibulaire, mais par la face médiale, ce qui explique l'inversion. Il s'y fixe par la face médiale et plantaire.","s":6},{"q":"Quelle est l'origine du long extenseur des orteils ?","o":["Le condyle latéral du tibia et les 2/3 proximaux du péroné","La face postérieure du tibia, sur ses 2/3 proximaux et moyens","Le tiers distal du péroné, en avant de la malléole","La membrane interosseuse seule, sur sa partie distale"],"r":0,"e":"Le LED naît du tibia et du péroné en avant, et s'insère sur les phalanges médianes et distales des orteils 2-5.","s":6},{"q":"Quelle est l'origine du 3e fibulaire (peroneus tertius) ?","o":["Le tiers distal et antérieur du péroné","La moitié distale du péroné latéral","La tête du péroné","Le condyle latéral du tibia"],"r":0,"e":"Le peroneus tertius, bien que « fibulaire », appartient à la loge antérieure et naît du péroné distal antérieur.","s":6},{"q":"Sur quoi s'insère le 3e fibulaire ?","o":["La base du 5e métatarsien","La base du 1er métatarsien","Le calcanéum","Le cuboïde"],"r":0,"e":"Comme le court fibulaire, il gagne le 5e métatarsien, mais par la face dorsale et avec le nerf fibulaire profond.","s":6},{"q":"Quelle est l'insertion du long extenseur du gros orteil ?","o":["La base dorsale de la phalange distale du gros orteil","La base plantaire de la phalange distale","La base dorsale du 1ᵉʳ métatarsien du gros orteil","La face dorsale du 1ᵉʳ cunéiforme, en dedans"],"r":0,"e":"Le LEGO est dorsal (extension) alors que le LFGO est plantaire (flexion).","s":6},{"q":"Quels muscles composent la face dorsale intrinsèque du pied ?","o":["Les courts extenseurs des orteils et du gros orteil","Le carré plantaire et les quatre lombricaux de la plante","Les interosseux plantaires, au nombre de trois","L'abducteur et le court fléchisseur du gros orteil"],"r":0,"e":"Ces deux courts extenseurs dorsaux sont innervés par le nerf fibulaire profond ; les autres muscles cités sont plantaires.","s":6},{"q":"En combien de couches s'organisent les muscles intrinsèques plantaires ?","o":["4","3","2","5"],"r":0,"e":"La plante comporte quatre couches, de la superficielle (court fléchisseur des orteils) à la profonde (interosseux).","s":6},{"q":"À quelle couche plantaire appartiennent les lombricaux du pied ?","o":["La couche 2","La couche 1","La couche 3","La couche 4"],"r":0,"e":"Les lombricaux accompagnent le carré plantaire dans la deuxième couche.","s":6},{"q":"Quel nerf innerve l'abducteur du 5e orteil ?","o":["Le nerf plantaire latéral","Le nerf plantaire médial","Le nerf fibulaire profond","Le nerf fibulaire superficiel"],"r":0,"e":"L'abducteur du 5e orteil dépend du plantaire latéral, alors que l'abducteur du gros orteil et le court fléchisseur des orteils dépendent du plantaire médial.","s":6},{"q":"Combien compte-t-on d'interosseux plantaires au pied ?","o":["3","4","2","5"],"r":0,"e":"Trois interosseux plantaires pour quatre interosseux dorsaux, comme à la main.","s":6},{"q":"Que recouvre exactement l'inversion du pied ?","o":["Adduction + supination","Abduction + pronation","Flexion plantaire + abduction","Flexion dorsale + pronation"],"r":0,"e":"L'inversion combine adduction et supination ; l'éversion associe abduction et pronation.","s":6},{"q":"Le SNC est composé de :","o":["L'encéphale et la moelle épinière","Les nerfs crâniens et spinaux","Les plexus et les ganglions nerveux","Le système autonome seul"],"r":0,"e":"SNC = encéphale + moelle épinière.","s":7},{"q":"Le SNP inclut :","o":["L'encéphale et le tronc cérébral","La moelle épinière et ses racines","Les nerfs situés hors du crâne et du rachis","Le cortex cérébral et les noyaux gris centraux"],"r":2,"e":"SNP : toutes les structures nerveuses situées en dehors du crâne et du canal vertébral.","s":7},{"q":"L'unité fonctionnelle du système nerveux est :","o":["L'axone","Le neurone","La cellule gliale","La synapse"],"r":1,"e":"Le neurone est l'unité fonctionnelle du SN.","s":7},{"q":"Combien de paires de nerfs spinaux existe-t-il ?","o":["28","30","31","33"],"r":2,"e":"31 paires de nerfs spinaux (8 cervicaux, 12 thoraciques, 5 lombaires, 5 sacrés, 1 coccygien).","s":7},{"q":"La moelle épinière se termine au niveau de :","o":["T12","L1","L2","S2"],"r":2,"e":"La moelle épinière se termine en L2 (cône médullaire).","s":7},{"q":"Les méninges, de l'extérieur vers l'intérieur :","o":["Pie-mère, arachnoïde, dure-mère","Dure-mère, arachnoïde, pie-mère","Arachnoïde, dure-mère, pie-mère","Dure-mère, pie-mère, arachnoïde"],"r":1,"e":"De l'extérieur : dure-mère (la plus épaisse) → arachnoïde → pie-mère (adhère au SNC).","s":7},{"q":"Le système nerveux somatique a pour effecteur :","o":["Muscle lisse","Muscle squelettique","Muscle cardiaque","Glandes"],"r":1,"e":"SN somatique = vie relationnelle, effecteur = muscle squelettique.","s":7},{"q":"Le système nerveux végétatif a pour effecteurs :","o":["Les muscles squelettiques, les tendons et les os","Les muscles lisse et cardiaque, et les glandes","Les os, les cartilages et les ligaments","Les articulations, les capsules et les bourses"],"r":1,"e":"SN végétatif (autonome) : muscle lisse, muscle cardiaque, glandes.","s":7},{"q":"Le liquide céphalo-rachidien est produit dans :","o":["Les ventricules","La moelle épinière","Le cervelet","Les méninges"],"r":0,"e":"Le LCR est produit dans les ventricules cérébraux (par les plexus choroïdes).","s":7},{"q":"Combien de ventricules cérébraux y a-t-il ?","o":["2","3","4","5"],"r":2,"e":"4 ventricules : 2 latéraux + 3e ventricule + 4e ventricule.","s":7},{"q":"L'aqueduc de Sylvius relie :","o":["Les 2 ventricules latéraux","3e et 4e ventricule","Le 4e ventricule à la moelle","Le ventricule latéral au 3e"],"r":1,"e":"L'aqueduc de Sylvius (aqueduc cérébral) passe dans le mésencéphale et relie le 3e au 4e ventricule.","s":7},{"q":"Les oligodendrocytes myélinisent :","o":["Le SNP","Le SNC","Les ganglions","La moelle uniquement"],"r":1,"e":"Oligodendrocytes : myélinisation des neurones du SNC.","s":7},{"q":"Les cellules de Schwann myélinisent :","o":["Le SNC","Le SNP","Les ganglions cérébraux","Le cortex"],"r":1,"e":"Cellules de Schwann : myélinisation des neurones du SNP.","s":7},{"q":"Les nœuds de Ranvier sont :","o":["Des cellules gliales qui produisent la myéline","Des zones sans myéline entre deux gaines voisines","Des synapses entre deux axones voisins","Des récepteurs sensitifs situés sur l'axone"],"r":1,"e":"Les nœuds de Ranvier sont les espaces non myélinisés entre 2 cellules myélinisantes — perméables aux ions.","s":7},{"q":"La conduction saltatoire est :","o":["Plus lente que celle des fibres non myélinisées","Plus rapide que celle des fibres non myélinisées","Identique à celle des fibres non myélinisées, à diamètre égal","Sans rôle sur la vitesse de l'influx nerveux"],"r":1,"e":"La conduction saltatoire (de nœud en nœud) est bien plus rapide.","s":7},{"q":"La substance blanche est composée principalement de :","o":["Corps cellulaires","Axones myélinisés","Dendrites","Synapses"],"r":1,"e":"Substance blanche = axones myélinisés. Sa fonction = transport de l'information.","s":7},{"q":"La substance grise est composée principalement de :","o":["Axones myélinisés","Corps cellulaires","Myéline","Synapses isolées"],"r":1,"e":"Substance grise = corps cellulaires (somas). Fonction = traitement.","s":7},{"q":"Un regroupement de corps cellulaires dans le SNP s'appelle :","o":["Cortex","Ganglion","Noyau","Faisceau"],"r":1,"e":"SNP : « ganglion ». SNC : « noyau ».","s":7},{"q":"Un regroupement de corps cellulaires dans le SNC s'appelle :","o":["Ganglion","Noyau / Cortex","Faisceau","Plexus"],"r":1,"e":"Dans le SNC, les regroupements de corps cellulaires = noyaux ou cortex.","s":7},{"q":"Le soma est :","o":["L'axone, qui conduit l'influx","Le corps cellulaire du neurone","Une dendrite, qui reçoit l'influx","Une synapse, entre deux neurones voisins"],"r":1,"e":"Le soma est le corps cellulaire du neurone (contient noyau + organites).","s":7},{"q":"Les dendrites sont spécialisées dans :","o":["L'envoi d'information","La réception d'information","Le stockage","La protection"],"r":1,"e":"Dendrites : réception de l'information depuis d'autres cellules.","s":7},{"q":"L'axone se termine par :","o":["Par le soma du neurone","Par des dendrites réceptrices","Par des terminaisons présynaptiques","Par une gaine protectrice"],"r":2,"e":"L'axone se termine par des terminaisons présynaptiques (libérant les neurotransmetteurs).","s":7},{"q":"La fente synaptique est :","o":["L'intérieur du neurone présynaptique","L'espace entre deux neurones","Le noyau du neurone postsynaptique","L'axone du neurone présynaptique, en entier"],"r":1,"e":"Fente synaptique = espace entre 2 neurones (ou neurone-effecteur).","s":7},{"q":"La microglie est spécialisée dans :","o":["Myélinisation","Phagocytose / immunité","Production de LCR","Nutrition"],"r":1,"e":"Microglie : cellules phagocytaires (immunité du SNC).","s":7},{"q":"Le liquide céphalo-rachidien a pour fonction principale :","o":["Le mouvement des membres, par pression","La nutrition et la protection, comme un coussin","La digestion des déchets du cerveau, par phagocytose","L'innervation des méninges, par contact direct"],"r":1,"e":"LCR : nutrition + coussin hydraulique (protection contre traumatismes).","s":7},{"q":"Les 2 ventricules latéraux communiquent avec le 3e ventricule via :","o":["Par l'aqueduc du mésencéphale","Par les foramens interventriculaires de Monro","Par la grande citerne, sous le cervelet en arrière","Par le canal épendymaire de la moelle"],"r":1,"e":"Foramen interventriculaire de Monro relie ventricule latéral au 3e ventricule.","s":7},{"q":"Le 4e ventricule est situé entre :","o":["Le cervelet et le tronc cérébral","Les deux hémisphères cérébraux, au milieu","Le cortex et la voûte crânienne","La moelle épinière et le bulbe"],"r":0,"e":"4e ventricule : entre le cervelet (en arrière) et le tronc cérébral (en avant).","s":7},{"q":"Combien de cellules gliales y a-t-il pour chaque neurone ?","o":["1","Environ 10","Environ 100","Aucune"],"r":1,"e":"Environ 10 cellules gliales par neurone.","s":7},{"q":"En moyenne, combien de synapses par neurone ?","o":["100","1 000","10 000","100 000"],"r":2,"e":"Chaque neurone fait en moyenne 10 000 synapses.","s":7},{"q":"Le SNC est protégé par :","o":["La peau et le tissu sous-cutané du crâne","Les méninges, les os et le LCR","Les os seuls, sans autre structure","Aucune structure, hormis le LCR et la peau"],"r":1,"e":"Protection : os (crâne, vertèbres) + 3 méninges + LCR. Les os sont le crâne et la colonne vertébrale.","s":7},{"q":"Quelles sont les trois étapes du fonctionnement du système nerveux ?","o":["Réception, traitement, exécution","Perception, mémorisation, action","Stimulation, inhibition, régulation","Afférence, synapse, efférence"],"r":0,"e":"La fiche décrit la réception par les récepteurs, le traitement de l'information puis l'exécution par les effecteurs.","s":7},{"q":"Le système nerveux somatique relève de quelle vie et de quel niveau de contrôle ?","o":["Vie relationnelle, contrôle surtout conscient","Vie viscérale, contrôle inconscient","Vie relationnelle, contrôle inconscient","Vie viscérale, contrôle conscient et volontaire"],"r":0,"e":"Le somatique gère la vie de relation, essentiellement consciente ; le végétatif gère la vie viscérale, inconsciente.","s":7},{"q":"Entre quels repères la moelle épinière s'étend-elle ?","o":["Du foramen magnum à L2","Du foramen magnum à L5","De C1 à T12","De l'atlas au sacrum"],"r":0,"e":"Elle va du foramen magnum jusqu'à L2, où elle se termine par le cône médullaire.","s":7},{"q":"Comment se nomme l'extrémité inférieure de la moelle épinière ?","o":["Le cône médullaire","Le filum terminale","La queue de cheval","Le canal épendymaire"],"r":0,"e":"La fiche nomme cette terminaison le cône médullaire, situé en regard de L2.","s":7},{"q":"Combien de segments médullaires compte la moelle épinière ?","o":["31","33","30","29"],"r":0,"e":"31 segments donnent naissance aux 31 paires de nerfs spinaux.","s":7},{"q":"De quoi la dure-mère est-elle principalement constituée ?","o":["Collagène et élastine","Cartilage","Tissu adipeux","Fibres musculaires lisses"],"r":0,"e":"La dure-mère, méninge externe épaisse, associe collagène et élastine ; l'arachnoïde n'a que du collagène.","s":7},{"q":"Quelle méninge adhère directement au tissu nerveux ?","o":["La pie-mère","L'arachnoïde","La dure-mère","Le périnèvre"],"r":0,"e":"La pie-mère, très fine et interne, épouse la surface du SNC.","s":7},{"q":"Quelle est la fonction des méninges ?","o":["Protéger le SNC tout en permettant son mouvement","Produire le liquide céphalo-rachidien","Myéliniser les axones du système central","Assurer l'immunité du SNC contre toutes les infections"],"r":0,"e":"Les méninges protègent tout en autorisant la mobilité ; le LCR est produit dans les ventricules et l'immunité revient à la microglie.","s":7},{"q":"Comment les ventricules cérébraux se prolongent-ils dans la moelle ?","o":["Par le canal de l'épendyme","Par l'aqueduc de Sylvius","Par les foramens de Monro","Par l'espace sous-arachnoïdien"],"r":0,"e":"Le canal épendymaire prolonge le 4e ventricule dans la moelle ; l'aqueduc de Sylvius relie les 3e et 4e ventricules.","s":7},{"q":"Où se situe le 3e ventricule ?","o":["Au centre du diencéphale","Dans chaque hémisphère","Entre cervelet et tronc cérébral","Dans le mésencéphale"],"r":0,"e":"Le 3e ventricule occupe le centre du diencéphale ; le 4e est entre cervelet et tronc cérébral.","s":7},{"q":"À quel liquide la composition du LCR est-elle comparable ?","o":["À la lymphe","Au plasma sanguin pur","À la synovie","À l'humeur vitrée"],"r":0,"e":"La fiche décrit un liquide incolore de composition similaire à la lymphe.","s":7},{"q":"Dans quels espaces le LCR circule-t-il ?","o":["Ventricules, espace sous-arachnoïdien et canal épendymaire","Ventricules seuls, sans espace sous-arachnoïdien","Espace épidural, ventricules et sinus veineux de la dure-mère","Canal épendymaire seul, au centre de la moelle"],"r":0,"e":"Le LCR circule dans les trois compartiments cités, assurant nutrition et amortissement.","s":7},{"q":"Combien de neurones compte approximativement le système nerveux ?","o":["Plus de 100 milliards","Environ 10 milliards","Environ 1 milliard","Environ 1 000 milliards"],"r":0,"e":"La fiche indique plus de 100 milliards de neurones, chacun réalisant en moyenne 10 000 synapses.","s":7},{"q":"Où sont produits les neurotransmetteurs dans le neurone ?","o":["Dans le soma, ou corps cellulaire","Dans les dendrites, près du soma","Dans les nœuds de Ranvier","Dans la fente synaptique"],"r":0,"e":"Le soma, qui contient noyau et organites, est le lieu de production des neurotransmetteurs.","s":7},{"q":"À quelle catégorie de glie appartiennent les astrocytes ?","o":["À la macroglie","À la microglie","Aux neurones","Aux cellules épendymaires phagocytaires"],"r":0,"e":"Astrocytes, oligodendrocytes et cellules de Schwann forment la macroglie ; la microglie regroupe les phagocytes.","s":7},{"q":"Quelles sont les seules cellules de soutien du système nerveux périphérique ?","o":["Les cellules de Schwann","Les oligodendrocytes","Les astrocytes","Les cellules microgliales"],"r":0,"e":"La fiche précise que les cellules de Schwann sont les seules cellules de soutien du SNP.","s":7},{"q":"De quoi la gaine de myéline est-elle composée ?","o":["De lipides et de protéines","De collagène et d'élastine","De glucides et de sels minéraux","D'eau et d'électrolytes"],"r":0,"e":"La myéline est un complexe lipido-protéique, imperméable aux ions.","s":7},{"q":"Pourquoi la myéline modifie-t-elle la conduction de l'influx ?","o":["Elle est imperméable aux ions, sauf au niveau des nœuds","Elle accélère la synthèse des neurotransmetteurs","Elle élargit la fente synaptique, à chaque terminaison","Elle multiplie le nombre de synapses de l'axone"],"r":0,"e":"L'imperméabilité ionique impose une dépolarisation limitée aux nœuds de Ranvier, d'où la conduction saltatoire.","s":7},{"q":"Quels termes désignent des structures de substance blanche ?","o":["Voie, faisceau, lemnisque, fascicule, pédoncule, capsule","Ganglion, noyau, cortex, gyrus et corne","Soma, dendrite, axone, synapse et bouton","Gyrus, sillon, scissure, lobe, circonvolution et pôle frontal"],"r":0,"e":"Ces termes désignent des ensembles d'axones myélinisés ; ganglion, noyau et cortex désignent la substance grise. La colonne en fait aussi partie.","s":7},{"q":"Quelle est la fonction principale de la substance grise ?","o":["Le traitement de l'information","Le transport de l'information","La production de LCR","La myélinisation"],"r":0,"e":"La substance grise, faite de corps cellulaires, traite l'information ; la substance blanche la transporte.","s":7},{"q":"Un nerf spinal est toujours :","o":["Sensitif","Moteur","Mixte","Autonome"],"r":2,"e":"Les nerfs spinaux sont TOUS mixtes (union d'une racine antérieure motrice et postérieure sensitive).","s":8},{"q":"La racine postérieure d'un nerf spinal est :","o":["Motrice","Sensitive","Mixte","Autonome"],"r":1,"e":"Racine postérieure = sensitive (afférente), avec ganglion spinal.","s":8},{"q":"Le ganglion spinal contient :","o":["Les corps cellulaires des motoneurones","Les corps des neurones sensitifs","Des cellules gliales seulement","Des terminaisons motrices"],"r":1,"e":"Le ganglion de la racine postérieure contient les corps cellulaires des neurones sensitifs.","s":8},{"q":"Combien y a-t-il de paires de nerfs spinaux ?","o":["28","30","31","33"],"r":2,"e":"31 paires.","s":8},{"q":"Combien y a-t-il de nerfs cervicaux ?","o":["6","7","8","10"],"r":2,"e":"8 nerfs cervicaux (C1-C8) bien qu'il n'y ait que 7 vertèbres cervicales.","s":8},{"q":"Le nerf phrénique provient de :","o":["Le plexus brachial, de C5 à T1","Le plexus cervical, de C3 à C5","Le plexus lombaire, de L1 à L4","Le plexus sacré, de L4 à S4, en arrière"],"r":1,"e":"Nerf phrénique = plexus cervical (C3-C4-C5), innerve le diaphragme.","s":8},{"q":"Le plexus brachial provient des racines :","o":["C1-C4","C5-T1","T2-T6","L1-L4"],"r":1,"e":"Plexus brachial : C5-T1.","s":8},{"q":"Le nerf médian a pour racines :","o":["C5-C6","C6-T1","C8-T1","L1-L4"],"r":1,"e":"Nerf médian : C6-T1.","s":8},{"q":"Le nerf cubital (ulnaire) a pour racines :","o":["C5-C6","C7-C8","C8-T1","C6-T1"],"r":2,"e":"Nerf ulnaire (cubital) : C8-T1.","s":8},{"q":"Le nerf radial a pour racines :","o":["C5-T1","C8-T1","C5-C6","C6-T1"],"r":0,"e":"Nerf radial : C5-T1.","s":8},{"q":"Le plexus lombaire provient des racines :","o":["L1-L4","T12-L5","L1-S1","L4-S3"],"r":0,"e":"Plexus lombaire : L1-L4.","s":8},{"q":"Le nerf fémoral a pour racines :","o":["L1-L3","L2-L4","L4-S1","L4-S3"],"r":1,"e":"Nerf fémoral : L2-L4.","s":8},{"q":"Le nerf obturateur a pour racines :","o":["L2-L4","S1-S2","L4-S2","T12-L1"],"r":0,"e":"Nerf obturateur : L2-L4 (passe par le foramen obturateur).","s":8},{"q":"Le plexus sacré provient des racines :","o":["L1-L4","L4-S3","S2-S4","S4-Co1"],"r":1,"e":"Plexus sacré : L4-S3.","s":8},{"q":"Le nerf sciatique se divise au creux poplité en :","o":["Le nerf tibial et le nerf fibulaire commun","Le nerf fémoral et le nerf obturateur","Le nerf médian et le nerf ulnaire","Le nerf saphène et le nerf sural, en arrière"],"r":0,"e":"Au creux poplité, le sciatique se divise en nerf tibial et nerf péronier (fibulaire commun).","s":8},{"q":"Le nerf tibial postérieur passe :","o":["Devant la malléole externe","Derrière la malléole interne","Devant le tendon d'Achille","Sur le talon"],"r":1,"e":"Le nerf tibial passe derrière la malléole interne (médial).","s":8},{"q":"Combien de paires de nerfs crâniens ?","o":["10","11","12","13"],"r":2,"e":"12 paires de nerfs crâniens.","s":8},{"q":"Combien de nerfs crâniens sont sensitifs purs ?","o":["Trois, les nerfs I, II et VIII","Quatre, les nerfs I, II, V et VIII","Cinq, les nerfs I à V","Six, les nerfs I à VI"],"r":0,"e":"3 sensitifs : I (olfactif), II (optique), VIII (vestibulo-cochléaire).","s":8},{"q":"Combien de nerfs crâniens sont moteurs purs ?","o":["Trois, les nerfs III, IV et VI","Quatre, les nerfs III, IV, VI et XII seuls","Cinq, les nerfs III, IV, VI, XI et XII","Six, les nerfs III, IV, V, VI, XI et XII"],"r":2,"e":"5 moteurs : III, IV, VI, XI, XII.","s":8},{"q":"Combien de nerfs crâniens sont mixtes ?","o":["Trois, les nerfs V, VII et X, sans le IX","Quatre, les nerfs V, VII, IX et X","Cinq, les nerfs V, VII, VIII, IX et X","Six, les nerfs V à X"],"r":1,"e":"4 mixtes : V (trijumeau), VII (facial), IX (glossopharyngien), X (vague).","s":8},{"q":"Le nerf I est :","o":["Olfactif","Optique","Vestibulo-cochléaire","Trijumeau"],"r":0,"e":"Nerf I = olfactif (odorat).","s":8},{"q":"Le nerf II est :","o":["Olfactif","Optique","Vestibulo-cochléaire","Trijumeau"],"r":1,"e":"Nerf II = optique (vision).","s":8},{"q":"Le nerf VIII est :","o":["Le nerf olfactif, de l'odorat seul","Le nerf optique, de la vision","Le nerf vestibulo-cochléaire","Le nerf trijumeau, de la face"],"r":2,"e":"Nerf VIII = vestibulo-cochléaire (audition + équilibre).","s":8},{"q":"Le nerf qui innerve les muscles masticateurs est :","o":["Le V3, ou nerf mandibulaire","Le VII, ou nerf facial et intermédiaire","Le V1, ou nerf ophtalmique","Le XII, ou nerf hypoglosse"],"r":0,"e":"V3 (branche mandibulaire du trijumeau) = muscles masticateurs.","s":8},{"q":"Le nerf qui innerve les muscles de la mimique est :","o":["Le V, ou nerf trijumeau","Le VII, ou nerf facial","Le IX, ou glossopharyngien","Le X, ou nerf vague pneumogastrique"],"r":1,"e":"VII (facial) = muscles de la mimique (expression du visage).","s":8},{"q":"Le nerf XI innerve :","o":["La langue et les muscles sous-hyoïdiens du cou","Le sterno-cléido-mastoïdien, le trapèze et le larynx","Les muscles oculomoteurs, sauf le droit latéral","Le diaphragme, avec une partie des muscles intercostaux"],"r":1,"e":"XI (spinal/accessoire) : SCM, trapèze supérieur, muscles du larynx et pharynx. Il innerve aussi le pharynx ; seul le trapèze supérieur est concerné.","s":8},{"q":"Le nerf XII innerve :","o":["Les muscles de la langue et les infra-hyoïdiens","Le diaphragme, par ses racines cervicales","Les muscles de la mimique, autour de la bouche","Les muscles des yeux, sauf l'oblique supérieur seul"],"r":0,"e":"XII (hypoglosse) : muscles de la langue + infra-hyoïdiens.","s":8},{"q":"Le nerf vague (X) est :","o":["Sensitif pur, sans fibre motrice","Moteur pur, sans fibre sensitive","Mixte, avec un rôle parasympathique majeur","Sans fonction connue chez l'adulte, vestigial"],"r":2,"e":"Le nerf vague (X) est mixte et constitue la principale voie du parasympathique.","s":8},{"q":"Les nerfs intercostaux proviennent :","o":["Du plexus brachial, par ses branches basses","Des branches antérieures thoraciques, sans plexus","Du plexus lombaire, par ses branches hautes","Du plexus cervical, par ses branches basses"],"r":1,"e":"Les nerfs intercostaux = branches antérieures des nerfs thoraciques (T1-T12), ne forment pas de plexus.","s":8},{"q":"L'endonèvre est :","o":["L'enveloppe externe de tout le nerf","La membrane autour de chaque axone","L'enveloppe d'un faisceau d'axones","Le tissu du tronc nerveux entier"],"r":1,"e":"Endonèvre = membrane autour de CHAQUE axone (la plus interne).","s":8},{"q":"Quelle couche conjonctive entoure chaque axone ?","o":["L'endonèvre","Le périnèvre","L'épinèvre","Le mésonèvre"],"r":0,"e":"L'endonèvre entoure l'axone ; le périnèvre enveloppe un faisceau et l'épinèvre le nerf entier.","s":8},{"q":"Quelle couche conjonctive enveloppe un faisceau d'axones ?","o":["Le périnèvre","L'endonèvre","L'épinèvre","Le mésonèvre"],"r":0,"e":"Le périnèvre entoure les faisceaux ; l'endonèvre est plus interne, autour de chaque axone.","s":8},{"q":"Qu'est-ce que le mésonèvre ?","o":["Le tissu lâche entourant le tronc nerveux","La gaine fine autour de chaque axone","L'enveloppe d'un faisceau d'axones","La gaine de myéline des axones"],"r":0,"e":"Le mésonèvre est le tissu lâche périphérique permettant le glissement du tronc nerveux.","s":8},{"q":"Dans un nerf mixte, quelles fibres sont les plus nombreuses ?","o":["Les fibres sensitives","Les fibres motrices","Les fibres végétatives","Elles sont en nombre égal"],"r":0,"e":"La fiche précise que dans les nerfs mixtes les fibres sensitives sont en plus grande quantité.","s":8},{"q":"Par où les nerfs spinaux sortent-ils du canal vertébral ?","o":["Par le foramen de conjugaison","Par le foramen magnum","Par le canal épendymaire","Par le foramen obturateur"],"r":0,"e":"Les nerfs spinaux émergent par les foramens de conjugaison (intervertébraux).","s":8},{"q":"Combien de nerfs sacrés compte-t-on ?","o":["5","4","6","3"],"r":0,"e":"Cinq nerfs sacrés (S1-S5), auxquels s'ajoute un nerf coccygien.","s":8},{"q":"Quelle règle régit l'émergence des nerfs cervicaux C1 à C7 ?","o":["Ils émergent au-dessus de leur vertèbre","Ils émergent sous leur vertèbre","Ils émergent en regard du disque","Leur émergence varie selon le niveau et le côté"],"r":0,"e":"C1-C7 émergent au-dessus de leur vertèbre, C8 entre C7 et T1, puis à partir de T1 les nerfs sortent sous leur vertèbre.","s":8},{"q":"Où émerge le nerf C8 ?","o":["Entre C7 et T1","Au-dessus de C7","Sous T1","Entre C6 et C7"],"r":0,"e":"Il n'existe pas de vertèbre C8 : le nerf C8 sort entre C7 et T1, faisant la transition entre les deux règles.","s":8},{"q":"Qu'innerve la branche postérieure d'un nerf spinal ?","o":["Le dos du tronc, en sensitif comme en moteur","La seule peau du dos, sans les muscles","Les seuls muscles des membres, sans la peau","Les viscères, par des fibres végétatives"],"r":0,"e":"La branche dorsale assure une innervation sensorielle et motrice de la région postérieure du tronc.","s":8},{"q":"Quelles branches antérieures ne forment pas de plexus ?","o":["Les branches thoraciques, ou nerfs intercostaux","Les branches cervicales, ou plexus cervical","Les branches lombaires, ou plexus lombaire","Les branches sacrées, ou plexus sacré"],"r":0,"e":"Les branches thoraciques restent métamériques et deviennent les nerfs intercostaux.","s":8},{"q":"De quelles racines provient le plexus cervical ?","o":["C1-C4","C5-T1","C1-C8","C3-C5"],"r":0,"e":"Le plexus cervical naît de C1 à C4 ; C5-T1 forment le plexus brachial.","s":8},{"q":"De quelles racines provient le plexus pudendal ?","o":["S2-S4","L4-S3","S4-S5","L1-L4"],"r":0,"e":"Le plexus pudendal correspond à S2-S4, alors que S4-S5 et le coccygien forment le plexus sacro-coccygien.","s":8},{"q":"Quelle partie du plexus cervical innerve le diaphragme ?","o":["Le plexus cervical profond (musculaire)","Le plexus cervical superficiel (cutané)","Le plexus brachial","Le plexus lombaire"],"r":0,"e":"Le plexus cervical profond donne le nerf phrénique (C3-C5) destiné au diaphragme.","s":8},{"q":"Où passe la partie supraclaviculaire du plexus brachial ?","o":["Entre le scalène antérieur et le scalène moyen","Entre le scalène moyen et le scalène postérieur","En arrière du sterno-cléido-mastoïdien, seul","Sous le petit pectoral, en avant de la 1ʳᵉ côte"],"r":0,"e":"Le défilé interscalénique antérieur/moyen est le passage classique du plexus brachial.","s":8},{"q":"Quel est le rapport du nerf médian avec le ligament annulaire du carpe ?","o":["Il passe derrière lui","Il passe devant lui","Il passe à l'extérieur de lui","Il ne le croise pas"],"r":0,"e":"Le médian passe derrière le ligament annulaire (canal carpien), alors que le nerf ulnaire passe à l'extérieur.","s":8},{"q":"Quel est le rapport du nerf ulnaire avec l'épitrochlée ?","o":["Il passe derrière elle","Il passe devant elle","Il la traverse","Il passe au-dessus du condyle latéral"],"r":0,"e":"Le nerf ulnaire chemine dans la gouttière rétro-épitrochléenne, d'où sa vulnérabilité au coude.","s":8},{"q":"En quelles deux branches le nerf radial se divise-t-il ?","o":["Une branche antérieure cutanée et une postérieure musculaire","Une branche superficielle et une branche profonde du carpe","Une branche médiane et une branche latérale de l'avant-bras","Une branche sensitive et une branche autonome, purement végétative"],"r":0,"e":"La fiche décrit une branche antérieure cutanée et une branche postérieure musculaire.","s":8},{"q":"Quel muscle recouvre le plexus lombaire ?","o":["Le psoas","Le carré des lombes","L'iliaque","Le grand fessier"],"r":0,"e":"Le plexus lombaire chemine derrière les corps vertébraux, recouvert par le psoas.","s":8},{"q":"Quelles sont les quatre branches du nerf fémoral ?","o":["Musculo-cutanés externe et interne, nerf du quadriceps, saphène","Fibulaire superficiel, fibulaire profond, tibial et saphène","Obturateur, saphène, cutané latéral et génito-fémoral","Plantaire médial, plantaire latéral, sural et saphène"],"r":0,"e":"La fiche énumère ces quatre branches ; les nerfs fibulaires viennent du sciatique.","s":8},{"q":"Par quel orifice passe le nerf obturateur ?","o":["Le foramen obturateur","Le grand canal sciatique","Le foramen magnum","Le canal inguinal"],"r":0,"e":"Le nerf obturateur traverse l'articulation sacro-iliaque puis le foramen obturateur.","s":8},{"q":"La moelle épinière se termine au niveau de :","o":["En L1, juste au-dessus du cône terminal","En L2, au niveau du cône terminal","En L3, au niveau de la queue de cheval","En S1, au niveau du sacrum"],"r":1,"e":"Cône terminal = L2. En dessous : queue de cheval.","s":9},{"q":"La queue de cheval est constituée de :","o":["Des axones de la moelle, sans racine","Des racines lombaires basses et sacrées","Des motoneurones regroupés en noyaux","Des cellules gliales et des méninges"],"r":1,"e":"Queue de cheval : racines nerveuses qui descendent dans le canal vertébral pour sortir à leur niveau. Les racines coccygiennes en font aussi partie.","s":9},{"q":"La corne antérieure de la substance grise est :","o":["Sensitive","Motrice","Végétative","Mixte"],"r":1,"e":"Corne antérieure = MOTRICE (contient les motoneurones).","s":9},{"q":"La corne postérieure est :","o":["Sensitive","Motrice","Végétative pure","Mixte"],"r":0,"e":"Corne postérieure = SENSITIVE (neurones sensitifs de 2e ordre).","s":9},{"q":"La corne latérale contient des neurones :","o":["Moteurs squelettiques, de T1 à L2","Sensitifs purs, de T1 à L2","Végétatifs, sympathiques de T1 à L2","Aucun neurone, seulement des axones de T1 à L2"],"r":2,"e":"Corne latérale = neurones VÉGÉTATIFS (sympathiques T1-L2 et parasympathiques sacrés S2-S4). Elle contient aussi des neurones parasympathiques sacrés, de S2 à S4.","s":9},{"q":"Le canal de l'épendyme se trouve :","o":["Dans la commissure grise","Dans la commissure blanche","Sur le bord externe","Dans la corne antérieure"],"r":0,"e":"Canal de l'épendyme (canal central) traverse la commissure grise (au milieu du H).","s":9},{"q":"La voie dorsale (lemniscale) transmet :","o":["La douleur, la température et le tact grossier","Le tact fin, la vibration, la proprioception consciente","Les réflexes médullaires, sans relais thalamique","Les ordres moteurs volontaires, du cortex vers la moelle"],"r":1,"e":"Voie dorsale = sensibilité épicritique : tact fin, discrimination, vibration, proprioception consciente.","s":9},{"q":"La voie antéro-latérale (spino-thalamique) transmet :","o":["Le tact fin et la vibration","La douleur, la température et le tact grossier","La proprioception consciente, la vibration et le tact fin","La vision et l'audition, vers le thalamus"],"r":1,"e":"Voie spino-thalamique = sensibilité protopathique : douleur, T°, tact grossier.","s":9},{"q":"La voie dorsale décusse :","o":["Dans la moelle, dès son entrée","Dans le bulbe, en décussation sensitive","Dans le thalamus, avant le relais vers le cortex","Dans le cortex, au niveau du gyrus post-central"],"r":1,"e":"Voie dorsale : décussation DANS LE BULBE (au niveau des noyaux gracile et cunéiforme).","s":9},{"q":"La voie spino-thalamique décusse :","o":["Dès l'entrée dans la moelle, par la commissure","Dans le bulbe, au niveau des noyaux gracile","Dans le thalamus, avant le relais cortical","Dans le cortex, au gyrus post-central"],"r":0,"e":"La voie antéro-latérale décusse IMMÉDIATEMENT dans la moelle (commissure blanche antérieure). Il s'agit de la commissure blanche antérieure.","s":9},{"q":"Toutes les voies sensitives passent par le thalamus, sauf :","o":["L'olfaction","La vision","L'audition","Le toucher"],"r":0,"e":"L'olfaction (nerf I) est la seule voie sensorielle qui n'a pas de relais thalamique avant le cortex.","s":9},{"q":"Le faisceau gracile (Goll) transmet :","o":["Membre supérieur","Membre inférieur","Face","Viscères"],"r":1,"e":"Faisceau gracile (de Goll) = membres inférieurs. Faisceau cunéiforme (de Burdach) = membres supérieurs.","s":9},{"q":"Le faisceau cunéiforme (Burdach) transmet :","o":["Membre supérieur","Membre inférieur","Face","Viscères"],"r":0,"e":"Cunéiforme de Burdach : informations du membre supérieur.","s":9},{"q":"Le lemnisque médial est formé par :","o":["Les axones du 1ᵉʳ neurone, avant tout relais","Les axones croisés du 2ᵉ neurone de la voie dorsale","Les axones moteurs, issus du cortex précentral","Les axones du faisceau spino-thalamique, déjà croisés"],"r":1,"e":"Lemnisque médial : axones du 2e neurone de la voie dorsale après décussation dans le bulbe.","s":9},{"q":"Combien de neurones successifs dans une voie sensitive classique ?","o":["Deux, un périphérique et un central","Trois, du premier au troisième ordre","Quatre, dont deux dans la moelle","Cinq, dont trois dans le thalamus"],"r":1,"e":"Une voie sensitive a en général 3 neurones successifs : 1er ordre (ganglion), 2e ordre (moelle/bulbe → thalamus), 3e ordre (thalamus → cortex).","s":9},{"q":"Le 1er neurone d'une voie sensitive a son corps dans :","o":["La corne postérieure de la moelle","Le ganglion spinal de la racine postérieure","Les noyaux gracile et cunéiforme, dans le bulbe","Le noyau ventral postéro-latéral du thalamus"],"r":1,"e":"Le 1er neurone (protoneurone) a son corps dans le ganglion spinal (racine postérieure).","s":9},{"q":"Le syndrome de Brown-Séquard est dû à :","o":["Une lésion bilatérale et complète de la moelle","Une lésion unilatérale, ou hémisection, de la moelle","Une atteinte du thalamus, d'un seul côté de l'encéphale","Une atteinte du cortex pariétal controlatéral"],"r":1,"e":"Brown-Séquard = hémisection médullaire : épicritique perdu homolatéral, protopathique perdu controlatéral.","s":9},{"q":"Les motoneurones sont situés dans :","o":["La corne postérieure","La corne antérieure","Le thalamus","Le cortex pariétal"],"r":1,"e":"Motoneurones (alpha et gamma) = corne antérieure de la moelle.","s":9},{"q":"Les interneurones de la moelle :","o":["Sont rares, environ 1 pour 10 motoneurones","Sont environ 30 fois plus nombreux que les motoneurones","N'existent qu'au niveau du cerveau, pas dans la moelle","Sont uniquement moteurs, au même titre que les motoneurones"],"r":1,"e":"Les interneurones sont très nombreux (30× plus que les motoneurones) et régulent l'activité de la moelle.","s":9},{"q":"Les voies spino-cérébelleuses véhiculent :","o":["La proprioception consciente, vers le cortex","La proprioception inconsciente, vers le cervelet","La douleur et la température, vers le thalamus latéral","Le tact fin et la vibration, vers le bulbe"],"r":1,"e":"Spino-cérébelleuses : proprioception INCONSCIENTE vers le cervelet (coordination).","s":9},{"q":"Le récepteur de la douleur est :","o":["Le corpuscule de Pacini","Le corpuscule de Meissner, dans le derme","Les terminaisons nerveuses libres","Le corpuscule de Krause"],"r":2,"e":"Nocicepteur = terminaisons nerveuses libres.","s":9},{"q":"Le récepteur des vibrations est principalement :","o":["Pacini","Meissner","Merkel","Ruffini"],"r":0,"e":"Corpuscule de Pacini = vibrations rapides + pression profonde.","s":9},{"q":"Le fuseau neuromusculaire détecte :","o":["La douleur","L'étirement du muscle","La pression cutanée","La température"],"r":1,"e":"Fuseau neuromusculaire = récepteur de l'étirement musculaire (proprioception).","s":9},{"q":"L'organe tendineux de Golgi détecte :","o":["L'étirement musculaire","La tension du tendon","La température","La pression cutanée"],"r":1,"e":"Golgi = détecte la tension dans le tendon (protection muscle contre surcharge).","s":9},{"q":"Le noyau de relais thalamique pour la sensibilité du corps est :","o":["VPM","VPL","CGL","CGM"],"r":1,"e":"VPL (ventral postéro-latéral) = relais sensitif du corps. VPM = sensibilité de la face.","s":9},{"q":"Le cortex somesthésique primaire est dans :","o":["Le lobe frontal","Le lobe pariétal","Le lobe occipital","Le lobe temporal"],"r":1,"e":"Cortex somesthésique = aires 3, 1, 2 du lobe pariétal (gyrus post-central).","s":9},{"q":"Le faisceau spino-cérébelleux antérieur de Gowers :","o":["Il décusse une seule fois","Il décusse deux fois de suite","Il ne décusse jamais","Il reste dans la moelle"],"r":1,"e":"Spino-cérébelleux antérieur (Gowers) : 2 décussations → information homolatérale au final.","s":9},{"q":"Le faisceau spino-cérébelleux postérieur de Flechsig :","o":["Il reste homolatéral, sans croiser","Il décusse une fois, dans la moelle","Il décusse deux fois, moelle puis cervelet","Il est moteur, descendant vers la moelle"],"r":0,"e":"Spino-cérébelleux postérieur (Flechsig) : direct, homolatéral.","s":9},{"q":"La substance gélatineuse de Rolando se trouve dans :","o":["La corne antérieure","La corne postérieure","La corne latérale","Le bulbe"],"r":1,"e":"Substance gélatineuse de Rolando = couche II de Rexed, corne postérieure (intervient dans la nociception).","s":9},{"q":"Au niveau de la moelle, la voie dorsale est :","o":["Homolatérale","Controlatérale","Bilatérale","Variable"],"r":0,"e":"Dans la moelle, la voie dorsale (cordon postérieur) est HOMOlatérale (elle ne décusse qu'au bulbe).","s":9},{"q":"Quelles sont les deux fonctions fondamentales de la moelle épinière ?","o":["Transmettre les informations et les traiter par réflexe","Produire le LCR et protéger l'encéphale","Myéliniser les axones et nourrir tous les neurones voisins","Filtrer les informations et sécréter des hormones"],"r":0,"e":"La fiche retient la transmission entre périphérie et cerveau ainsi que le traitement réflexe segmentaire.","s":9},{"q":"Combien de parties la fiche distingue-t-elle dans la moelle épinière ?","o":["6","4","5","3"],"r":0,"e":"Cervicale supérieure, dilatation cervicale, dorsale, dilatation lombo-crurale, cône terminal et filament terminal : six parties.","s":9},{"q":"À quel plexus correspond la dilatation cervicale (brachiale) de la moelle ?","o":["Au plexus brachial","Au plexus cervical","Au plexus lombo-sacré","Au plexus pudendal"],"r":0,"e":"Le renflement cervical alimente le plexus brachial ; la dilatation lombo-crurale correspond au plexus lombo-sacré.","s":9},{"q":"Jusqu'où descend le filament terminal ?","o":["Jusqu'au coccyx","Jusqu'à L2","Jusqu'à S1","Jusqu'à L5"],"r":0,"e":"Ce cordon fin prolonge le cône terminal (L2) jusqu'au coccyx.","s":9},{"q":"Pourquoi la ponction lombaire se pratique-t-elle en L3-L4 ou L4-L5 ?","o":["La moelle s'arrête en L2, seules des racines mobiles restent","L'espace entre les lames y est le plus large du rachis","La dure-mère y est absente, d'où un accès direct","Le LCR n'y circule pas sous L3, d'où moins de fuite"],"r":0,"e":"Sous L2, l'aiguille ne rencontre que des racines mobiles, d'où la sécurité du geste.","s":9},{"q":"Qu'est-ce qui enveloppe la queue de cheval ?","o":["La dure-mère, en cul-de-sac dural","Le périnèvre de chaque racine","Le filament terminal, en bas","La substance blanche, en couronne autour"],"r":0,"e":"Le cul-de-sac dural entoure les racines de la queue de cheval sous le cône terminal.","s":9},{"q":"Que contient la commissure grise de la moelle ?","o":["Le canal de l'épendyme","Les motoneurones alpha","Les corps des neurones sensitifs de 2e ordre","Le lemnisque médial"],"r":0,"e":"Le canal central occupe la barre du H, entre commissures grises antérieure et postérieure.","s":9},{"q":"À quels niveaux médullaires la corne latérale est-elle présente ?","o":["Aux niveaux thoracique et lombaire haut","Sur toute la hauteur de la moelle","Au niveau cervical uniquement","Au niveau sacré uniquement"],"r":0,"e":"La corne latérale existe en thoracique et lombaire haut, correspondant aux neurones préganglionnaires sympathiques T1-L2.","s":9},{"q":"Que contient la région antérieure de la corne latérale ?","o":["Les neurones préganglionnaires viscéro-moteurs","Les neurones viscéro-sensitifs, du côté postérieur","Les motoneurones gamma, des fuseaux musculaires","Les interneurones inhibiteurs de Renshaw"],"r":0,"e":"La région antérieure est viscéro-motrice (sympathiques T1-L2, parasympathiques sacrés S2-S4) ; la région postérieure est viscéro-sensitive.","s":9},{"q":"Quels types de motoneurones la corne antérieure contient-elle ?","o":["Alpha et gamma","Alpha uniquement","Gamma uniquement","Alpha, bêta et gamma"],"r":0,"e":"Les motoneurones alpha et gamma quittent la moelle par la racine antérieure.","s":9},{"q":"Combien de fois les interneurones sont-ils plus nombreux que les motoneurones ?","o":["Environ 30 fois","Environ 10 fois","Environ 3 fois","Environ 100 fois"],"r":0,"e":"La fiche indique environ 30 fois plus d'interneurones que de motoneurones.","s":9},{"q":"Quels sillons médullaires correspondent à l'entrée des racines postérieures ?","o":["Les sillons collatéraux postérieurs","Les sillons collatéraux antérieurs","Le sillon médian postérieur","Le sillon médian antérieur"],"r":0,"e":"Les racines postérieures entrent par les sillons collatéraux postérieurs, les antérieures sortent par les collatéraux antérieurs.","s":9},{"q":"Lequel des sillons médians médullaires est le plus profond ?","o":["Le sillon médian antérieur","Le sillon médian postérieur","Ils sont d'égale profondeur","Le sillon collatéral antérieur"],"r":0,"e":"Le sillon médian antérieur est profond, le postérieur est peu marqué.","s":9},{"q":"Où se situe le corps du neurone de 2e ordre de la voie dorsale ?","o":["Dans les noyaux gracile et cunéiforme du bulbe","Dans la corne postérieure, au niveau d'entrée","Dans le ganglion spinal de la racine","Dans le thalamus, noyau ventral"],"r":0,"e":"La voie dorsale fait sa première synapse centrale dans le bulbe, contrairement à la spino-thalamique qui relaie dans la corne postérieure.","s":9},{"q":"Où se situe le corps du neurone de 3e ordre d'une voie sensitive ?","o":["Dans le thalamus","Dans le bulbe","Dans le ganglion spinal","Dans le cortex pariétal"],"r":0,"e":"Le 3e neurone est thalamique et projette vers le cortex somesthésique pariétal.","s":9},{"q":"Où décusse le 2e neurone de la voie spino-thalamique ?","o":["Dans la commissure blanche antérieure de la moelle","Dans le bulbe, au niveau du lemnisque médial","Dans le pont, au niveau des noyaux pontiques du tronc","Dans le thalamus, avant le relais cortical"],"r":0,"e":"La décussation est immédiate, par la commissure blanche antérieure, dès le niveau d'entrée.","s":9},{"q":"Quel faisceau spino-thalamique conduit le tact grossier ?","o":["Le faisceau spino-thalamique antérieur","Le faisceau spino-thalamique latéral","Le faisceau gracile","Le faisceau cunéiforme"],"r":0,"e":"Le latéral porte douleur et température, l'antérieur le tact non discriminatif.","s":9},{"q":"Pourquoi le faisceau spino-cérébelleux antérieur de Gowers véhicule-t-il une information homolatérale ?","o":["Parce qu'il décusse deux fois","Parce qu'il ne décusse jamais","Parce qu'il décusse dans le bulbe","Parce qu'il passe par le thalamus"],"r":0,"e":"La double décussation ramène l'information du côté d'origine ; le faisceau de Flechsig, lui, reste directement homolatéral.","s":9},{"q":"Quel récepteur détecte le froid ?","o":["Le corpuscule de Krause","Le corpuscule de Ruffini","Le corpuscule de Pacini","Le disque de Merkel"],"r":0,"e":"Krause code le froid et Ruffini le chaud ; Pacini et Merkel sont des mécanorécepteurs.","s":9},{"q":"Quel est l'aboutissement cortical de la voie dorsale ?","o":["Le cortex somesthésique pariétal, aires 3, 1 et 2","Le gyrus précentral, au niveau de l'aire 4","Le cortex occipital, au niveau de l'aire 17","Le cortex temporal, au niveau des aires auditives 41 et 42"],"r":0,"e":"Les aires 3, 1 et 2 du lobe pariétal constituent le cortex somesthésique primaire ; l'aire 4 est motrice.","s":9},{"q":"Le tronc cérébral est situé :","o":["Au-dessus du cerveau, sous la voûte du crâne","Entre la moelle et le cerveau, devant le cervelet","Sous la moelle, au niveau du canal sacré, en bas du rachis","Dans le cervelet, entre ses deux hémisphères"],"r":1,"e":"Tronc cérébral : entre moelle (en bas) et cerveau (en haut), juste devant le cervelet.","s":10},{"q":"Les 3 étages du tronc cérébral, de bas en haut, sont :","o":["Mésencéphale, pont, bulbe","Bulbe, pont, mésencéphale","Bulbe, mésencéphale, pont","Pont, bulbe, mésencéphale"],"r":1,"e":"De bas en haut : bulbe → pont (protubérance) → mésencéphale.","s":10},{"q":"Les pyramides bulbaires contiennent :","o":["Les voies motrices descendantes, corticospinales","Les voies sensitives ascendantes, lemniscales et spinales","Les noyaux des nerfs crâniens moteurs","Les artères vertébrales et le tronc basilaire"],"r":0,"e":"Pyramides bulbaires = faisceau corticospinal (pyramidal) — motricité volontaire descendante.","s":10},{"q":"La décussation pyramidale se fait au niveau :","o":["Du mésencéphale, au niveau des pédoncules","Du pont, au niveau des noyaux pontiques","De la jonction entre le bulbe et la moelle","Du cortex moteur, dès la sortie de l'aire 4 précentrale"],"r":2,"e":"80% des fibres corticospinales décussent à la jonction bulbe-moelle (décussation pyramidale).","s":10},{"q":"L'olive bulbaire est impliquée dans :","o":["La respiration automatique et le rythme de la toux","La coordination et l'équilibre","La conscience et l'éveil","La vision et les réflexes pupillaires"],"r":1,"e":"Olives bulbaires = équilibre et coordination motrice (liens avec le cervelet).","s":10},{"q":"Le centre respiratoire principal se trouve dans :","o":["Le mésencéphale","Le pont","Le bulbe","Le cervelet"],"r":2,"e":"Centre respiratoire et cardio-vasculaire = bulbe rachidien (fonctions vitales).","s":10},{"q":"Les noyaux pontiques relayent :","o":["Cortex → cervelet","Moelle → cortex","Cervelet → cortex","Bulbe → moelle"],"r":0,"e":"Noyaux pontiques = relais entre cortex cérébral et cervelet (voie corticopontocérébelleuse).","s":10},{"q":"Le mésencéphale contient la substance noire qui sécrète :","o":["Acétylcholine","Dopamine","Sérotonine","Adrénaline"],"r":1,"e":"Substance noire (locus niger) = neurones dopaminergiques. Atteinte = Parkinson.","s":10},{"q":"Les tubercules quadrijumeaux supérieurs (colliculus sup.) sont impliqués dans :","o":["Réflexes auditifs","Réflexes visuels","La motricité fine","La sensibilité"],"r":1,"e":"Colliculus supérieurs = réflexes visuels. Colliculus inférieurs = réflexes auditifs.","s":10},{"q":"Les tubercules quadrijumeaux inférieurs sont impliqués dans :","o":["Réflexes visuels","Réflexes auditifs","Tonus","Vision"],"r":1,"e":"Colliculus inférieurs = relais auditif.","s":10},{"q":"Les noyaux des nerfs III et IV sont dans :","o":["Le bulbe","Le pont","Le mésencéphale","Le cortex"],"r":2,"e":"Noyaux du III (oculomoteur commun) et du IV (trochléaire) = mésencéphale.","s":10},{"q":"Les noyaux du VII (facial) et VI (abducens) sont dans :","o":["Le bulbe","Le pont","Le mésencéphale","La moelle"],"r":1,"e":"Noyaux du VI et VII = pont.","s":10},{"q":"Les noyaux du IX, X, XI, XII sont dans :","o":["Le pont","Le mésencéphale","Le bulbe","La moelle"],"r":2,"e":"Noyaux des nerfs crâniens IX, X, XI, XII = bulbe rachidien.","s":10},{"q":"La substance réticulée est :","o":["Concentrée en un seul noyau du bulbe","Diffuse, en réseau, dans le tronc cérébral","Située dans le cervelet, sous le vermis","Limitée à la moelle cervicale haute"],"r":1,"e":"Substance réticulée = réseau diffus tout le long du tronc cérébral.","s":10},{"q":"Le SARA (système activateur réticulé ascendant) contrôle :","o":["La douleur, la température et le tact","Le sommeil, la veille, l'attention et la conscience","Les réflexes, la posture et le tonus","Les mouvements oculaires, la vision et l'audition"],"r":1,"e":"SARA = niveau d'éveil, conscience, attention (substance réticulée ascendante).","s":10},{"q":"La voie pyramidale (corticospinale) provient de :","o":["Du cervelet, par les noyaux dentés et interposés","Du cortex moteur primaire, gyrus précentral","Des noyaux gris centraux, putamen et caudé","Du thalamus, par le noyau ventral latéral"],"r":1,"e":"Voie corticospinale : origine = cortex moteur primaire (aire 4, gyrus précentral, neurones de Betz). C'est l'aire 4, avec les neurones de Betz.","s":10},{"q":"Le faisceau corticospinal latéral est :","o":["Homolatéral, car il ne croise jamais","Controlatéral, après la décussation pyramidale","Bilatéral, avec la moitié des fibres de chaque côté","Sans latéralité, car il reste médian"],"r":1,"e":"Le faisceau corticospinal latéral est controlatéral à son origine corticale (décussation bulbaire).","s":10},{"q":"La voie rubro-spinale provient de :","o":["Du cortex moteur, par le gyrus précentral","Du noyau rouge, dans le mésencéphale","Du bulbe, par les olives bulbaires","Du cervelet, par le noyau fastigial"],"r":1,"e":"Voie rubro-spinale : origine = noyau rouge du mésencéphale.","s":10},{"q":"La voie rubro-spinale facilite :","o":["Les extenseurs des membres","Les fléchisseurs des membres","Les muscles de la gorge","Les muscles respiratoires"],"r":1,"e":"Rubro-spinale : facilite la flexion des membres (rôle antagoniste des vestibulo-spinales).","s":10},{"q":"La voie tecto-spinale provient de :","o":["Colliculus supérieur","Noyau rouge","Substance noire","Pont"],"r":0,"e":"Tecto-spinale : origine = colliculus supérieur (tectum mésencéphalique).","s":10},{"q":"La voie tecto-spinale a pour fonction :","o":["Les mouvements volontaires fins des doigts et de la main","L'orientation de la tête vers un son ou une image","Le maintien de la posture antigravitaire","Le rythme de la marche automatique"],"r":1,"e":"Tecto-spinale : orientation réflexe de la tête et du cou.","s":10},{"q":"Les voies vestibulo-spinales contrôlent :","o":["La motricité volontaire fine des extrémités","L'équilibre et la posture, par les extenseurs","Les fléchisseurs des membres supérieurs","La douleur et la température, par voie descendante"],"r":1,"e":"Vestibulo-spinales : équilibre et posture, facilitent les extenseurs antigravitaires.","s":10},{"q":"La voie vestibulo-spinale latérale provient du noyau :","o":["Du noyau de Deiters, vestibulaire latéral","Du noyau vestibulaire médial, ou de Schwalbe","Du noyau rouge du mésencéphale","Du noyau d'Edinger-Westphal"],"r":0,"e":"Vestibulo-spinale latérale : noyau de Deiters (vestibulaire latéral). Reste homolatérale.","s":10},{"q":"Les voies réticulo-spinales proviennent de :","o":["Du cortex moteur primaire, par la capsule interne","De la substance réticulée du tronc cérébral","Du cervelet, par les noyaux profonds","Des noyaux gris centraux, par le pallidum"],"r":1,"e":"Réticulo-spinales : origine = substance réticulée du tronc cérébral.","s":10},{"q":"La maladie de Parkinson est liée à une atteinte de :","o":["Du cortex frontal, par perte neuronale","De la substance noire, par perte de la dopamine","Du cervelet, par perte des Purkinje","De la moelle, par perte des motoneurones alpha"],"r":1,"e":"Parkinson : dégénérescence des neurones dopaminergiques de la substance noire.","s":10},{"q":"Les pédoncules cérébelleux moyens relient le cervelet au :","o":["Bulbe","Pont","Mésencéphale","Cortex"],"r":1,"e":"Pédoncules cérébelleux moyens = vers le pont. Inf = bulbe. Sup = mésencéphale.","s":10},{"q":"Combien de paires de pédoncules cérébelleux ?","o":["1","2","3","4"],"r":2,"e":"3 paires de pédoncules cérébelleux : inférieurs, moyens, supérieurs.","s":10},{"q":"La voie cortico-nucléaire innerve :","o":["Les motoneurones spinaux, dans la corne antérieure","Les noyaux moteurs des nerfs crâniens","Le cervelet, par les pédoncules moyens","Les noyaux sensitifs du tronc cérébral"],"r":1,"e":"Voie cortico-nucléaire (cortico-bulbaire) : cortex → noyaux moteurs des nerfs crâniens (V, VII, IX, X, XI, XII).","s":10},{"q":"Le tectum est :","o":["La partie antérieure, motrice","La partie postérieure, sensorielle","La partie supérieure, quadrigéminale","La partie inférieure, en regard du bulbe"],"r":2,"e":"Tectum = partie supérieure du tronc cérébral = lame quadrigéminale (colliculus).","s":10},{"q":"Le tegmentum est :","o":["La partie antérieure, motrice","La partie postérieure, sensorielle et réticulée","La partie supérieure, quadrigéminale","La partie inférieure, en regard du bulbe et du pont"],"r":1,"e":"Tegmentum = partie postérieure, contient les systèmes sensoriels et la substance réticulée.","s":10},{"q":"Quelles sont les trois divisions longitudinales du tronc cérébral ?","o":["Section basilaire, tegmentum, tectum","Bulbe, pont, mésencéphale","Cortex, noyaux, substance réticulée","Pédoncules inférieurs, moyens, supérieurs"],"r":0,"e":"Bulbe, pont et mésencéphale sont la division transversale ; la division longitudinale oppose section basilaire, tegmentum et tectum.","s":10},{"q":"Quels systèmes occupent la section basilaire du tronc cérébral ?","o":["Les systèmes moteurs","Les systèmes sensoriels","Les tubercules quadrijumeaux","Les noyaux vestibulaires uniquement"],"r":0,"e":"La section basilaire antérieure est motrice ; le tegmentum postérieur est sensoriel et contient la substance réticulée.","s":10},{"q":"Quels noyaux de nerfs crâniens le tronc cérébral contient-il ?","o":["Ceux des nerfs III à XII","Ceux des nerfs I à XII","Ceux des nerfs V à XII","Ceux des nerfs I et II"],"r":0,"e":"Les noyaux des nerfs III à XII sont dans le tronc ; les nerfs I et II ne naissent pas du tronc cérébral.","s":10},{"q":"Quels pédoncules cérébelleux relient le cervelet au bulbe ?","o":["Les pédoncules cérébelleux inférieurs","Les pédoncules cérébelleux moyens","Les pédoncules cérébelleux supérieurs","Les pédoncules cérébraux"],"r":0,"e":"Inférieurs pour le bulbe, moyens pour le pont, supérieurs pour le mésencéphale.","s":10},{"q":"Quels pédoncules cérébelleux relient le cervelet au mésencéphale ?","o":["Les pédoncules cérébelleux supérieurs","Les pédoncules cérébelleux moyens","Les pédoncules cérébelleux inférieurs","La lame quadrigéminale"],"r":0,"e":"Les pédoncules supérieurs rejoignent le mésencéphale.","s":10},{"q":"Quelle proportion des fibres pyramidales décusse à la jonction bulbo-médullaire ?","o":["Environ 80 %","Environ 50 %","Environ 100 %","Environ 20 %"],"r":0,"e":"80 % forment le faisceau corticospinal latéral controlatéral ; les 20 % restants forment le faisceau antérieur, qui décusse au niveau segmentaire.","s":10},{"q":"Où les olives bulbaires sont-elles situées ?","o":["Latéralement, sur la face antérieure du bulbe","Médialement, sur la face postérieure du pont","En haut, dans le tectum du mésencéphale","En bas, dans le plancher du 4ᵉ ventricule, en arrière"],"r":0,"e":"Les olives sont latérales aux pyramides sur la face antérieure du bulbe.","s":10},{"q":"Quels centres vitaux, outre les centres respiratoire et cardio-vasculaire, le bulbe abrite-t-il ?","o":["Les centres du vomissement, de la déglutition et de la toux","Les centres du sommeil, de la veille et de l'attention","Les centres de la vision, de l'audition et de l'odorat","Les centres de la faim, de la soif et de la température"],"r":0,"e":"La fiche liste vomissement, déglutition et toux ; le SARA (veille) est diffus dans toute la substance réticulée.","s":10},{"q":"Quelle voie les noyaux pontiques relaient-ils ?","o":["La voie cortico-ponto-cérébelleuse","La voie spino-thalamique latérale","La voie rubro-spinale du mésencéphale","La voie lemniscale médiale"],"r":0,"e":"Les noyaux du pont relaient l'information du cortex vers le cervelet.","s":10},{"q":"Quel noyau de nerf crânien est situé dans le pont avec le VI et le VII ?","o":["La partie principale du V","Le noyau du XII","Le noyau du IX","Le noyau du III, en haut du pont"],"r":0,"e":"Le pont contient la partie principale du trijumeau, le VI, le VII et une partie du VIII ; le IX et le XII sont bulbaires.","s":10},{"q":"Que sont les pédoncules cérébraux ?","o":["Deux cordons blancs du mésencéphale, à motricité descendante","Les connexions du cervelet avec le pont et le bulbe","Les tubercules quadrijumeaux, sur la face postérieure du tronc","Les noyaux dopaminergiques du mésencéphale"],"r":0,"e":"Les pédoncules cérébraux sont antérieurs dans le mésencéphale ; ne pas les confondre avec les pédoncules cérébelleux.","s":10},{"q":"Qu'est-ce qui pigmente la substance noire ?","o":["La mélanine","L'hémoglobine","La bilirubine","La lipofuscine"],"r":0,"e":"Le locus niger doit sa couleur à la mélanine ; ses neurones sont dopaminergiques.","s":10},{"q":"Comment s'appelle aussi la lame quadrigéminale ?","o":["Le tectum","Le tegmentum","La section basilaire","La substance réticulée"],"r":0,"e":"Le tectum, supérieur, porte les colliculus supérieurs et inférieurs.","s":10},{"q":"Quels noyaux de nerfs crâniens siègent dans le mésencéphale ?","o":["Le III, le IV et une partie du V","Le VI, le VII et une partie du VIII","Le IX, le X et une partie du XI","Le XI, le XII et une partie du X"],"r":0,"e":"Le mésencéphale contient les noyaux du III, du IV et une partie du trijumeau.","s":10},{"q":"Quelle fonction de modulation la substance réticulée exerce-t-elle sur la douleur ?","o":["Un contrôle descendant de type « portillon »","Une amplification systématique","Aucune, elle n'intervient pas sur la douleur","Un blocage des récepteurs périphériques"],"r":0,"e":"La substance réticulée module la nociception par un contrôle descendant inhibiteur.","s":10},{"q":"Quels neurones sont à l'origine de la voie pyramidale ?","o":["Les cellules de Betz de l'aire 4 précentrale","Les neurones du noyau rouge du mésencéphale","Les cellules de Purkinje du cervelet","Les motoneurones alpha des cornes antérieures de C1 à S2"],"r":0,"e":"Les cellules géantes de Betz du cortex moteur primaire donnent naissance au faisceau corticospinal.","s":10},{"q":"Quel est le trajet de la voie pyramidale entre cortex et bulbe ?","o":["Capsule interne, pédoncules cérébraux, pont, pyramides","Thalamus, tectum, olives et lemnisque médial","Noyau rouge, pont, olives et pyramides","Cervelet, pédoncules cérébelleux moyens, pont et pyramides"],"r":0,"e":"La fiche décrit ce trajet ; le noyau rouge appartient à la voie rubro-spinale. Les pyramides sont bulbaires.","s":10},{"q":"Où décussent les 20 % de fibres du faisceau corticospinal antérieur ?","o":["Au niveau segmentaire, dans la moelle","À la jonction bulbo-médullaire, avec les autres","Dans le pont, au niveau des noyaux pontiques","Jamais, elles restent toujours homolatérales"],"r":0,"e":"Ces fibres restent homolatérales dans le tronc puis décussent à leur niveau d'arrivée médullaire.","s":10},{"q":"Quels noyaux de nerfs crâniens la voie cortico-nucléaire commande-t-elle ?","o":["V, VII, IX, X, XI, XII","I, II, VIII","III, IV, VI","Tous les nerfs crâniens"],"r":0,"e":"La voie cortico-bulbaire s'adresse aux noyaux moteurs des nerfs mixtes et moteurs somatiques cités.","s":10},{"q":"Quelle est la cible de la voie tecto-spinale ?","o":["Les motoneurones cervicaux","Les motoneurones lombaires","Les noyaux vestibulaires","Le cervelet"],"r":0,"e":"Née du colliculus supérieur, elle oriente réflexivement la tête et le cou, d'où sa cible cervicale.","s":10},{"q":"Le cervelet est situé :","o":["Au-dessus du cerveau, sous la voûte du crâne","Derrière le tronc cérébral, sous le cerveau","Devant le bulbe, dans la fosse antérieure","Dans la moelle, au niveau cervical haut"],"r":1,"e":"Cervelet : derrière le tronc cérébral, sous le cerveau, dans les fosses cérébelleuses de l'occipital.","s":11},{"q":"La fonction principale du cervelet est :","o":["Génération du mouvement","Coordination des mouvements","Sensibilité","Mémoire"],"r":1,"e":"Le cervelet COORDONNE le mouvement (il ne le génère pas).","s":11},{"q":"Combien de paires de pédoncules cérébelleux ?","o":["Une paire, reliée au bulbe seul","Deux paires, reliées au bulbe et au pont seulement","Trois paires, vers bulbe, pont et mésencéphale","Quatre paires, dont une vers le thalamus"],"r":2,"e":"3 paires : inférieurs (→ bulbe), moyens (→ pont), supérieurs (→ mésencéphale).","s":11},{"q":"Le lobe le plus grand du cervelet est :","o":["Antérieur","Postérieur","Flocculo-nodulaire","Vermis"],"r":1,"e":"Lobe postérieur = le plus grand. Flocculo-nodulaire = le plus petit (équilibre).","s":11},{"q":"Les cellules efférentes principales du cortex cérébelleux sont :","o":["Cellules granulaires","Cellules de Purkinje","Cellules en panier","Cellules étoilées"],"r":1,"e":"Cellules de Purkinje = unique sortie du cortex cérébelleux vers les noyaux profonds.","s":11},{"q":"Les fibres grimpantes proviennent de :","o":["La moelle","L'olive bulbaire","Le cortex","Les noyaux vestibulaires"],"r":1,"e":"Fibres grimpantes : olive bulbaire → cervelet (signaux d'erreur).","s":11},{"q":"Le noyau cérébelleux le plus médial est :","o":["Le fastigial, ou noyau du toit","Le denté, ou noyau latéral","L'emboliforme, ou interposé","Le globulaire, ou interposé postérieur"],"r":0,"e":"Du médial au latéral : fastigial (toit), globulaire, emboliforme, denté.","s":11},{"q":"Le plus gros noyau cérébelleux est :","o":["Fastigial","Globulaire","Emboliforme","Denté"],"r":3,"e":"Noyau denté = le plus gros, le plus latéral (néocervelet).","s":11},{"q":"Le diencéphale comprend :","o":["Cortex, noyaux gris centraux, capsule interne et corps calleux","Thalamus, hypothalamus, épithalamus et subthalamus","Cervelet, pont, bulbe et mésencéphale","Hippocampe, amygdale et cortex limbique"],"r":1,"e":"Diencéphale : thalamus + hypothalamus + épithalamus + subthalamus + métathalamus. Le métathalamus s'y ajoute.","s":11},{"q":"Le thalamus est le relais de :","o":["De toutes les voies sensitives, sauf l'olfaction","De la vision seule, par le corps genouillé latéral","De l'audition seule, par le genouillé médial","D'aucune voie, il ne sert que la motricité"],"r":0,"e":"Le thalamus est le relais de TOUTES les voies sensitives sauf l'olfaction.","s":11},{"q":"Le VPL (ventral postéro-latéral) thalamique reçoit :","o":["Sensibilité du corps","Sensibilité de la face","Vision","Audition"],"r":0,"e":"VPL = sensibilité du corps. VPM = sensibilité de la face.","s":11},{"q":"Le corps géniculé latéral (CGL) reçoit :","o":["Audition","Vision","Sensibilité","Olfaction"],"r":1,"e":"CGL = relais visuel. CGM = relais auditif.","s":11},{"q":"Le corps géniculé médial (CGM) reçoit :","o":["Vision","Audition","Tact","Goût"],"r":1,"e":"CGM = relais auditif vers le cortex auditif primaire.","s":11},{"q":"L'hypothalamus régule :","o":["La seule température, par le centre thermique du bulbe","Température, faim, soif, hormones et système autonome","La vision, par le chiasma et les bandelettes","La mémoire, par l'hippocampe et le fornix"],"r":1,"e":"Hypothalamus = régulation neuro-végétative + endocrinienne (faim, soif, T°, sommeil, axe hypothalamo-hypophysaire).","s":11},{"q":"L'hypothalamus contrôle :","o":["Le système nerveux somatique","L'hypophyse et le système autonome","Le cervelet","Le cortex"],"r":1,"e":"L'hypothalamus contrôle l'hypophyse (axe endocrinien) et le système autonome.","s":11},{"q":"L'aire 4 du cortex est :","o":["Sensitive primaire","Motrice primaire","Visuelle","Auditive"],"r":1,"e":"Aire 4 (gyrus précentral) = aire motrice primaire (neurones de Betz, origine de la voie pyramidale).","s":11},{"q":"Le gyrus post-central abrite :","o":["L'aire motrice primaire, aire 4","L'aire somesthésique primaire, aires 3, 1 et 2","L'aire visuelle primaire, aire 17, autour de la calcarine","L'aire de Wernicke, aire 22"],"r":1,"e":"Gyrus post-central (lobe pariétal) = aires 3-1-2 (somesthésique primaire).","s":11},{"q":"L'aire de Broca est dans :","o":["Le lobe frontal inférieur gauche","Le lobe temporal supérieur gauche","Le lobe pariétal inférieur gauche","Le lobe frontal inférieur droit, en miroir"],"r":0,"e":"Broca = frontal inférieur gauche → production du langage. Wernicke = temporal sup. gauche → compréhension. Elle commande la production du langage.","s":11},{"q":"L'aire de Wernicke est responsable de :","o":["La production du langage","La compréhension du langage","La vision","La motricité"],"r":1,"e":"Wernicke = compréhension du langage.","s":11},{"q":"Le corps calleux est :","o":["Un noyau gris central, situé sous le thalamus","La principale commissure inter-hémisphérique","Une voie sensitive ascendante vers le cortex","Un nerf crânien, situé à la base du cerveau"],"r":1,"e":"Corps calleux = principale commissure inter-hémisphérique (fibres reliant les 2 hémisphères).","s":11},{"q":"La capsule interne contient :","o":["Le liquide cérébro-spinal des ventricules latéraux","Les voies motrices et sensitives de projection","Les ventricules latéraux et le 3ᵉ ventricule","La substance noire et le noyau rouge"],"r":1,"e":"Capsule interne = passage des voies de projection (corticospinale, cortico-nucléaire, sensitives ascendantes).","s":11},{"q":"Le striatum est composé de :","o":["Caudé + putamen","Putamen + pallidum","Pallidum + sous-thalamique","Substance noire seule"],"r":0,"e":"Striatum = noyau caudé + putamen (porte d'entrée des ganglions de la base).","s":11},{"q":"Le noyau lenticulaire est composé de :","o":["Caudé + putamen","Putamen + globus pallidus","Caudé + pallidum","Sous-thalamique + substance noire"],"r":1,"e":"Noyau lenticulaire = putamen + globus pallidus (sortie principale des ganglions de la base).","s":11},{"q":"La maladie de Parkinson est due à la dégénérescence de :","o":["Le cortex moteur, dans le gyrus précentral","La substance noire, dans le mésencéphale","Le cervelet, dans le vermis","La moelle, dans la corne antérieure"],"r":1,"e":"Parkinson : dégénérescence dopaminergique de la substance noire.","s":11},{"q":"L'hémiballisme est causé par une lésion du :","o":["Du cervelet, au niveau du vermis","Du noyau caudé, dans la tête du striatum","Du noyau sous-thalamique de Luys","Du noyau rouge, dans le mésencéphale"],"r":2,"e":"Hémiballisme : lésion du noyau sous-thalamique de Luys → mouvements amples controlatéraux.","s":11},{"q":"La chorée de Huntington touche :","o":["Le noyau caudé","Le cervelet","La substance noire","Le cortex moteur"],"r":0,"e":"Huntington : atrophie du noyau caudé + putamen.","s":11},{"q":"Le vestibulocervelet (archicervelet) correspond au lobe :","o":["Le lobe antérieur, en avant","Le lobe postérieur, en arrière","Le lobe flocculo-nodulaire, en bas","Le vermis, sur la ligne médiane"],"r":2,"e":"Vestibulocervelet = lobe flocculo-nodulaire → équilibre, mouvements oculaires.","s":11},{"q":"Le spinocervelet correspond à :","o":["Vermis + paravermis","Hémisphère latéral","Flocculo-nodulaire","Cortex"],"r":0,"e":"Spinocervelet (paléocervelet) = vermis + paravermis → posture, tonus, locomotion.","s":11},{"q":"Le néocervelet correspond à :","o":["Vermis","Hémisphères latéraux","Flocculo-nodulaire","Tronc cérébral"],"r":1,"e":"Néocervelet (cérébrocervelet) = hémisphères latéraux → motricité fine, coordination, planification.","s":11},{"q":"Une atteinte du cervelet provoque :","o":["Une paralysie complète du côté opposé","Une ataxie, avec incoordination des mouvements","Une perte sensitive pure, sans trouble moteur associé","Une cécité corticale bilatérale"],"r":1,"e":"Lésion cérébelleuse → ataxie cérébelleuse (perte de coordination, dysmétrie, troubles équilibre).","s":11},{"q":"Dans quelles cavités osseuses le cervelet est-il logé ?","o":["Les fosses cérébelleuses de l'occipital","La selle turcique du sphénoïde, au centre","Les fosses temporales, de chaque côté","La lame criblée de l'ethmoïde"],"r":0,"e":"Le cervelet occupe les fosses cérébelleuses de l'os occipital, derrière le tronc cérébral.","s":11},{"q":"Quel lobe cérébelleux est le plus petit ?","o":["Le lobe flocculo-nodulaire","Le lobe antérieur, en haut","Le lobe postérieur, en bas","Le vermis, sur la ligne médiane"],"r":0,"e":"Le flocculo-nodulaire, dédié à l'équilibre, est le plus petit ; le vermis n'est pas un lobe mais une partie verticale.","s":11},{"q":"Quelles sont les trois parties verticales du cervelet ?","o":["Vermis, paravermis, hémisphère latéral","Lobe antérieur, postérieur, flocculo-nodulaire","Cortex, noyaux, pédoncules","Archicervelet, paléocervelet, néocervelet"],"r":0,"e":"La division verticale distingue vermis médian, paravermis intermédiaire et hémisphères latéraux.","s":11},{"q":"À quoi correspond anatomiquement le paléocervelet ?","o":["Au vermis et au paravermis","Aux hémisphères latéraux","Au lobe flocculo-nodulaire","Au noyau denté"],"r":0,"e":"Le paléocervelet (spinocervelet) recouvre vermis et paravermis, et gère posture, tonus et locomotion.","s":11},{"q":"Quelle est la fonction du vestibulocervelet ?","o":["L'équilibre et les mouvements oculaires","La motricité fine des mains","La planification motrice des gestes","Le tonus des muscles du tronc et de la nuque"],"r":0,"e":"L'archicervelet, qui correspond au lobe flocculo-nodulaire, gère équilibre et oculomotricité.","s":11},{"q":"Quelles sont les trois couches du cortex cérébelleux ?","o":["Moléculaire, des cellules de Purkinje et granulaire","Moléculaire, des grandes cellules pyramidales et granulaire","Externe, moyenne et interne, sans autre nom","Fastigiale, interposée et dentée, de dedans en dehors"],"r":0,"e":"Le cortex cérébelleux comporte ces trois couches ; fastigial, interposé et denté sont des noyaux profonds.","s":11},{"q":"Quels noyaux forment le noyau interposé ?","o":["Le globulaire et l'emboliforme","Le fastigial et le denté","Le denté et le globulaire","Le fastigial et l'emboliforme"],"r":0,"e":"Globulaire + emboliforme = noyau interposé, relais du spinocervelet.","s":11},{"q":"À quelle subdivision fonctionnelle le noyau du toit (fastigial) est-il rattaché ?","o":["Au vestibulocervelet","Au spinocervelet","Au néocervelet","Au cérébrocervelet"],"r":0,"e":"Le noyau fastigial, le plus médial, dessert le vestibulocervelet.","s":11},{"q":"De quelles sources proviennent les fibres moussues du cervelet ?","o":["Moelle, vestibule, réticulée et cortex via le pont","L'olive bulbaire seule, par les fibres grimpantes","Le thalamus seul, par le noyau ventral latéral","Les cellules de Purkinje, par leurs collatérales récurrentes"],"r":0,"e":"Les fibres moussues ont ces quatre origines ; les fibres grimpantes viennent de l'olive bulbaire. Le cortex passe par les noyaux pontiques ; la réticulée est la substance réticulée.","s":11},{"q":"Quelle information les fibres grimpantes apportent-elles ?","o":["Des informations sur les erreurs motrices","Des informations sur l'équilibre uniquement","Des informations visuelles","Des informations nociceptives"],"r":0,"e":"Issues de l'olive bulbaire, les fibres grimpantes signalent les erreurs motrices, support de l'apprentissage.","s":11},{"q":"Vers quoi projettent directement les cellules de Purkinje ?","o":["Vers les noyaux cérébelleux profonds","Vers le cortex cérébral moteur","Vers la moelle épinière cervicale","Vers le thalamus ventral latéral"],"r":0,"e":"Les Purkinje, seules efférences du cortex cérébelleux, se terminent sur les noyaux profonds, qui relaient ensuite.","s":11},{"q":"Quels sont les quatre composants du diencéphale ?","o":["Épithalamus, thalamus, subthalamus, hypothalamus","Cortex, noyaux gris et capsule interne","Bulbe, pont, mésencéphale et cervelet","Thalamus, hypophyse, hypothalamus, épiphyse"],"r":0,"e":"La fiche énumère ces quatre étages diencéphaliques ; cortex et ganglions de la base relèvent du télencéphale. Le thalamus est associé au métathalamus.","s":11},{"q":"Quel noyau thalamique relaie la sensibilité de la face ?","o":["Le VPM","Le VPL","Le CGL","Le VL"],"r":0,"e":"Le VPM (ventral postéro-médial) porte la face, le VPL le reste du corps.","s":11},{"q":"Quel noyau thalamique sert de relais moteur ?","o":["Le noyau ventral latéral, ou VL","Le noyau ventral postéro-latéral, ou VPL","Le corps genouillé médial, ou CGM","Les noyaux antérieurs, ou NA"],"r":0,"e":"Le VL relaie cervelet et ganglions de la base vers le cortex moteur.","s":11},{"q":"Quel noyau hypothalamique régule le cycle veille-sommeil ?","o":["Le noyau suprachiasmatique","Le noyau paraventriculaire","Le noyau de Deiters","Le noyau fastigial"],"r":0,"e":"Le suprachiasmatique est l'horloge circadienne hypothalamique.","s":11},{"q":"Quelles hormones la posthypophyse libère-t-elle ?","o":["L'ADH et l'ocytocine, d'origine hypothalamique","La GH et la TSH, d'origine antéhypophysaire","L'ACTH et la PRL, d'origine antéhypophysaire","La FSH et la LH, d'origine antéhypophysaire"],"r":0,"e":"La posthypophyse stocke et libère deux hormones d'origine hypothalamique ; les autres sont antéhypophysaires.","s":11},{"q":"Quelles fonctions le lobe de l'insula prend-il en charge ?","o":["Le viscéral, le goût et la douleur","La vision, la lecture et l'écriture","L'audition primaire et la musique","La motricité volontaire des mains"],"r":0,"e":"L'insula traite l'interoception, le goût et la douleur ; le lobe limbique gère les émotions.","s":11},{"q":"Où se situe l'aire auditive primaire 41-42 ?","o":["Dans le lobe temporal, au gyrus de Heschl","Dans le lobe occipital, au pôle","Dans le gyrus post-central, en haut","Dans le lobe frontal inférieur, à l'aire de Broca"],"r":0,"e":"Les aires 41-42 occupent le gyrus temporal transverse de Heschl.","s":11},{"q":"Où se situe l'aire visuelle primaire 17 ?","o":["Dans le lobe occipital, autour de la calcarine","Dans le lobe temporal supérieur, près de Heschl","Dans le gyrus précentral, en avant de Rolando","Dans le lobe pariétal, autour du sillon intrapariétal"],"r":0,"e":"L'aire 17 borde la scissure calcarine, sur la face médiale du lobe occipital.","s":11},{"q":"Quelle est la fonction de l'aire 6 (prémotrice et aire motrice supplémentaire) ?","o":["La planification du mouvement","L'exécution du mouvement volontaire","La compréhension du langage","La sensibilité du corps"],"r":0,"e":"L'aire 6 planifie ; l'aire 4 exécute.","s":11},{"q":"Le système nerveux autonome contrôle :","o":["Les muscles squelettiques, les tendons et les os","Les muscles lisses, le muscle cardiaque et les glandes","Le cerveau, la moelle et les nerfs crâniens","La conscience, la mémoire et le langage"],"r":1,"e":"SNA = effecteurs : muscles lisses, muscle cardiaque, glandes.","s":12},{"q":"Le SNA est :","o":["Volontaire, sous contrôle cortical","Involontaire, donc inconscient","Conscient, mais non volontaire, en grande partie","Sous contrôle direct de la volonté"],"r":1,"e":"SNA = autonome, inconscient, indépendant de la volonté.","s":12},{"q":"Une voie efférente du SNA comporte :","o":["Un seul neurone, de la moelle à l'organe","Deux neurones, pré et post-ganglionnaire","Trois neurones, avec deux ganglions relais","Aucun neurone, l'action étant hormonale seulement"],"r":1,"e":"Le SNA a TOUJOURS 2 neurones successifs avec une synapse dans un ganglion.","s":12},{"q":"Le système sympathique est aussi appelé :","o":["Crânio-sacré","Thoraco-lombaire","Vagal","Entérique"],"r":1,"e":"Sympathique = système thoraco-lombaire (T1-L2).","s":12},{"q":"Le système parasympathique est aussi appelé :","o":["Crânio-sacré","Thoraco-lombaire","Splanchnique","Mésentérique"],"r":0,"e":"Parasympathique = système crânio-sacré (III, VII, IX, X + S2-S4).","s":12},{"q":"L'origine du sympathique est :","o":["Corne latérale T1-L2","Corne latérale S2-S4","Tronc cérébral seul","Hypothalamus seul"],"r":0,"e":"Sympathique : neurones préganglionnaires dans la corne latérale T1-L2.","s":12},{"q":"L'origine du parasympathique est :","o":["La moelle thoraco-lombaire, de T1 à L2","Le tronc cérébral, par III, VII, IX et X, et S2 à S4","L'hypothalamus seul, sans aucun relais dans le tronc cérébral","La chaîne sympathique latéro-vertébrale"],"r":1,"e":"Parasympathique : noyaux des nerfs III, VII, IX, X (tronc cérébral) + S2-S4 (moelle sacrée).","s":12},{"q":"Le sympathique est responsable de la réponse :","o":["Rest and digest","Fight or flight","Aucune","Repos seul"],"r":1,"e":"Sympathique = « fight or flight » : alerte, fuite, combat.","s":12},{"q":"Le parasympathique est responsable de :","o":["Fight or flight","Rest and digest","Sudation","Vasoconstriction"],"r":1,"e":"Parasympathique = « rest and digest » : repos, digestion.","s":12},{"q":"Sur le cœur, le sympathique :","o":["Ralentit la fréquence et la contraction","Augmente la fréquence et la contractilité","N'a aucune action directe sur le cœur","Provoque un arrêt cardiaque transitoire"],"r":1,"e":"Sympathique : ↑ FC, ↑ contractilité.","s":12},{"q":"Sur le cœur, le parasympathique (nerf X) :","o":["Augmente la FC","Diminue la FC","Aucune action","Stimule la contractilité"],"r":1,"e":"Parasympathique (vague) : ↓ FC (bradycardisant).","s":12},{"q":"Sur les pupilles, le sympathique provoque :","o":["Un myosis, par contraction du sphincter","Une mydriase, ou dilatation","Aucun effet sur la pupille","Une cécité transitoire"],"r":1,"e":"Sympathique = mydriase (dilatation pupillaire).","s":12},{"q":"Sur les pupilles, le parasympathique (nerf III) provoque :","o":["Une mydriase, ou dilatation pupillaire","Un myosis, ou constriction pupillaire","Une anesthésie de la cornée","Un larmoiement réflexe abondant"],"r":1,"e":"Parasympathique (III) = myosis (constriction).","s":12},{"q":"Sur les bronches, le sympathique :","o":["Bronchoconstriction","Bronchodilatation","Aucune action","Inflammation"],"r":1,"e":"Sympathique = bronchodilatation (utilisée dans le ttt de l'asthme : β2-mimétiques).","s":12},{"q":"Sur les bronches, le parasympathique :","o":["Bronchoconstriction","Bronchodilatation","Aucune action","Apnée"],"r":0,"e":"Parasympathique = bronchoconstriction.","s":12},{"q":"Sur la digestion, le sympathique :","o":["Augmente le péristaltisme et les sécrétions","Diminue le péristaltisme et les sécrétions","Stimule la défécation et accélère le transit colique","Inverse le sens du péristaltisme"],"r":1,"e":"Sympathique : inhibe la digestion (↓ péristaltisme, ↓ sécrétions).","s":12},{"q":"Sur la digestion, le parasympathique :","o":["Augmente le péristaltisme et les sécrétions","Diminue le péristaltisme et les sécrétions","N'a aucune action sur le tube digestif ni sur ses glandes","Provoque une constipation par spasme"],"r":0,"e":"Parasympathique : stimule la digestion (↑ péristaltisme, ↑ sécrétions).","s":12},{"q":"Le neurotransmetteur post-ganglionnaire sympathique est :","o":["L'acétylcholine, dans tous les organes","La noradrénaline, sauf aux sudoripares","L'adrénaline seule, libérée dans tous les tissus","La sérotonine, surtout au tube digestif"],"r":1,"e":"Post-ganglionnaire sympathique : noradrénaline (exception : glandes sudoripares = acétylcholine).","s":12},{"q":"Le neurotransmetteur post-ganglionnaire parasympathique est :","o":["Noradrénaline","Acétylcholine","Dopamine","Sérotonine"],"r":1,"e":"Post-ganglionnaire parasympathique : acétylcholine (récepteurs muscariniques).","s":12},{"q":"Le neurotransmetteur pré-ganglionnaire des 2 systèmes (sympa et parasympa) est :","o":["La noradrénaline, sur des récepteurs alpha","L'acétylcholine, récepteurs nicotiniques","La dopamine, sur des récepteurs D1","Le GABA, sur des récepteurs A"],"r":1,"e":"Tous les neurones préganglionnaires (sympa ET parasympa) libèrent de l'acétylcholine (récepteurs nicotiniques dans le ganglion).","s":12},{"q":"Dans le sympathique, la fibre préganglionnaire est :","o":["Courte","Longue","Inexistante","Variable"],"r":0,"e":"Sympathique : préganglionnaire COURTE (ganglion proche de la moelle, chaîne paravertébrale).","s":12},{"q":"Dans le parasympathique, la fibre préganglionnaire est :","o":["Courte, avec un ganglion près de la moelle","Longue, avec un ganglion dans l'organe ou près","Inexistante, sans ganglion","Variable, selon l'organe innervé"],"r":1,"e":"Parasympathique : préganglionnaire LONGUE (ganglion dans/près de l'organe cible).","s":12},{"q":"Le ganglion cœliaque est :","o":["Un ganglion parasympathique crânien","Un ganglion sympathique pré-viscéral","Un ganglion parasympathique sacré","Un ganglion sympathique cervical"],"r":1,"e":"Ganglion cœliaque = ganglion sympathique pré-viscéral (splanchnique) abdominal.","s":12},{"q":"Le nerf vague (X) est principalement :","o":["Sympathique","Parasympathique","Somatique pur","Motoneurone"],"r":1,"e":"Le nerf X (vague) = principale voie parasympathique pour les viscères thoraciques et abdominaux.","s":12},{"q":"L'hypothalamus contrôle :","o":["La seule température, sans autre fonction","Le système autonome et le système endocrinien","La seule motricité volontaire des membres","La sensibilité consciente du corps"],"r":1,"e":"L'hypothalamus est le chef d'orchestre central du SNA et du système endocrinien. Il commande l'axe hypothalamo-hypophysaire.","s":12},{"q":"La chaîne sympathique latéro-vertébrale est :","o":["Bilatérale, le long du rachis","Médiane, devant le rachis","Limitée au diaphragme, de chaque côté","Intracrânienne, sous le cerveau"],"r":0,"e":"Chaîne sympathique paravertébrale : bilatérale, de chaque côté du rachis, du cou au sacrum.","s":12},{"q":"Le système nerveux entérique est :","o":["Une simple partie du sympathique","Un réseau autonome propre au tube digestif","Un réseau crânien, issu uniquement du nerf vague","Un réseau cervical, issu du plexus brachial"],"r":1,"e":"Système entérique = réseau autonome du tube digestif (~500 millions de neurones), peut fonctionner indépendamment. On l'appelle parfois le « deuxième cerveau ».","s":12},{"q":"Le plexus myentérique (Auerbach) contrôle :","o":["Les sécrétions des glandes digestives","La motricité du tube digestif","Le débit sanguin de la muqueuse","La douleur viscérale et la sensibilité"],"r":1,"e":"Plexus d'Auerbach (myentérique) : entre les muscles longitudinaux et circulaires → motricité.","s":12},{"q":"Le plexus sous-muqueux (Meissner) contrôle :","o":["La motricité du tube digestif","Les sécrétions et le débit sanguin local","Les muscles longitudinaux de la paroi","La douleur viscérale et la sensibilité au froid"],"r":1,"e":"Plexus de Meissner (sous-muqueux) : sécrétions + débit sanguin local.","s":12},{"q":"Dans la médullosurrénale, l'innervation est :","o":["Postganglionnaire sympathique, comme les organes","Préganglionnaire sympathique directe, sans relais","Parasympathique, par le nerf vague","Somatique, par les nerfs splanchniques"],"r":1,"e":"La médullosurrénale est innervée directement par des fibres préganglionnaires sympathiques (acétylcholine) — elle est l'équivalent d'un « ganglion modifié » et libère adrénaline + noradrénaline dans le sang. Elle libère adrénaline et noradrénaline dans le sang.","s":12},{"q":"Quelles sont les trois grandes fonctions régulées par le SNA selon la fiche ?","o":["Motricité lisse, sécrétions, sensibilité viscérale","Motricité squelettique, sensibilité cutanée, réflexes","Respiration, digestion et locomotion","Mémoire, langage, émotion et régulation de la conscience"],"r":0,"e":"La fiche cite la motricité lisse, la sécrétion des glandes et la sensibilité intéroceptive, au service de l'homéostasie.","s":12},{"q":"Quelle différence d'effet oppose le SN somatique au SN autonome ?","o":["Le somatique excite seulement, l'autonome excite ou inhibe","Le somatique excite ou inhibe, l'autonome excite seulement","Les deux sont seulement excitateurs, quel que soit l'organe","Les deux sont seulement inhibiteurs"],"r":0,"e":"L'effet autonome dépend du récepteur de l'organe cible, d'où sa bivalence.","s":12},{"q":"Quelle structure est l'organe d'intégration supérieure du SNA ?","o":["L'hypothalamus","Le thalamus","Le bulbe rachidien","Le cervelet"],"r":0,"e":"L'hypothalamus intègre l'autonome et l'endocrinien, via l'hypophyse.","s":12},{"q":"Où se situent les ganglions et plexus pré-viscéraux (collatéraux) ?","o":["Entre le rachis et les viscères, autour des gros vaisseaux","Sur la paroi même des viscères, au contact de l'organe","Le long de la chaîne latéro-vertébrale, de chaque côté","Dans la corne latérale de la moelle, de T1 à L2"],"r":0,"e":"Les ganglions pré-viscéraux sont intermédiaires ; les ganglions viscéraux sont sur l'organe et la chaîne est paravertébrale.","s":12},{"q":"Quel est l'état de myélinisation des fibres pré et postganglionnaires ?","o":["Préganglionnaire myélinisée, postganglionnaire non myélinisée","Les deux fibres sont myélinisées, dans les deux systèmes","Les deux fibres sont non myélinisées, dans les deux systèmes","Préganglionnaire non myélinisée, postganglionnaire myélinisée"],"r":0,"e":"Dans les deux systèmes, la fibre préganglionnaire est myélinisée et la postganglionnaire ne l'est pas.","s":12},{"q":"Pourquoi la médullosurrénale constitue-t-elle une exception dans le SNA ?","o":["Elle reçoit directement des fibres préganglionnaires","Elle est innervée par le seul parasympathique","Elle n'est pas innervée, sa sécrétion est hormonale","Elle possède trois neurones successifs"],"r":0,"e":"Assimilable à un ganglion modifié, elle reçoit directement les fibres préganglionnaires et déverse ses catécholamines dans le sang. Ces fibres préganglionnaires sont sympathiques.","s":12},{"q":"Quelle est la longueur relative des fibres dans le sympathique ?","o":["Préganglionnaire courte, postganglionnaire longue","Préganglionnaire longue, postganglionnaire courte","Les deux fibres courtes, de longueur égale","Les deux fibres longues, de longueur égale entre elles"],"r":0,"e":"Les ganglions sympathiques étant proches de la moelle, la préganglionnaire est courte ; c'est l'inverse dans le parasympathique.","s":12},{"q":"Quel ganglion pré-viscéral innerve l'estomac, le foie, le pancréas et la rate ?","o":["Le ganglion cœliaque","Le ganglion mésentérique supérieur","Le ganglion mésentérique inférieur","Le ganglion stellaire"],"r":0,"e":"Le ganglion cœliaque couvre l'abdomen supérieur ; le mésentérique supérieur gère grêle et côlon proximal.","s":12},{"q":"Quel ganglion sympathique innerve le côlon distal et les organes pelviens ?","o":["Le ganglion mésentérique inférieur","Le ganglion cœliaque","Le ganglion mésentérique supérieur","Le ganglion cervical supérieur"],"r":0,"e":"Le mésentérique inférieur dessert le côlon distal et le petit bassin.","s":12},{"q":"Quel récepteur reçoit l'acétylcholine préganglionnaire dans les deux systèmes ?","o":["Le récepteur nicotinique","Le récepteur muscarinique","Le récepteur alpha","Le récepteur bêta"],"r":0,"e":"La transmission ganglionnaire est nicotinique ; la transmission post-ganglionnaire parasympathique est muscarinique.","s":12},{"q":"Quelle est l'exception au caractère noradrénergique du sympathique post-ganglionnaire ?","o":["Les glandes sudoripares, qui reçoivent de l'acétylcholine","Le cœur, qui reçoit de la dopamine en continu","Les bronches, qui reçoivent de l'histamine","Les pupilles, qui reçoivent de la sérotonine de façon continue"],"r":0,"e":"Les glandes sudoripares sont innervées par des fibres sympathiques cholinergiques.","s":12},{"q":"Quel effet le sympathique a-t-il sur les vaisseaux des muscles ?","o":["Une vasodilatation","Une vasoconstriction","Aucun effet","Une constriction puis une dilatation"],"r":0,"e":"Le sympathique dilate les vaisseaux musculaires tout en constrictant ceux de la peau et des viscères : redistribution du débit vers l'effort.","s":12},{"q":"Quel effet hépatique le sympathique produit-il ?","o":["Une glycogénolyse qui augmente la glycémie","Une glycogénogenèse qui abaisse la glycémie","Une augmentation de la sécrétion biliaire","Aucun effet hépatique"],"r":0,"e":"La glycogénolyse libère du glucose pour l'effort.","s":12},{"q":"Quel est l'effet du sympathique sur la vessie ?","o":["Détrusor relâché et sphincter contracté, d'où la rétention","Détrusor contracté et sphincter relâché, d'où la vidange complète","Détrusor et sphincter contractés en même temps","Aucun effet sur le détrusor ni sur le sphincter"],"r":0,"e":"Le sympathique favorise la rétention, le parasympathique la miction.","s":12},{"q":"Quels nerfs crâniens portent des fibres parasympathiques ?","o":["III, VII, IX et X","V, VI, VII et VIII","I, II et VIII","XI et XII"],"r":0,"e":"Le parasympathique crânien emprunte les nerfs III, VII, IX et X.","s":12},{"q":"Jusqu'où le nerf vague innerve-t-il le tube digestif ?","o":["Jusqu'au côlon transverse","Jusqu'au rectum","Jusqu'à l'estomac seulement","Jusqu'au duodénum"],"r":0,"e":"Au-delà du côlon transverse, ce sont les nerfs sacrés S2-S4 qui prennent le relais.","s":12},{"q":"Quelle action parasympathique le nerf III produit-il, outre le myosis ?","o":["L'accommodation, par les muscles ciliaires","La sécrétion des larmes","La sécrétion parotidienne, par la glande parotide","La bronchoconstriction réflexe"],"r":0,"e":"Le III commande le sphincter irien et le muscle ciliaire ; les larmes dépendent du VII.","s":12},{"q":"Quelles glandes salivaires le nerf VII innerve-t-il ?","o":["Les glandes sous-mandibulaire et sublinguale","La seule parotide, en avant de l'oreille externe","Les trois glandes salivaires principales","Aucune glande salivaire, seulement les larmes"],"r":0,"e":"Le VII innerve sous-mandibulaire et sublinguale, ainsi que les glandes lacrymales ; la parotide dépend du IX.","s":12},{"q":"Quelle fonction génitale les nerfs sacrés S2-S4 assurent-ils ?","o":["L'érection, par vasodilatation","L'éjaculation, par contraction","La vasoconstriction génitale","Aucune fonction génitale"],"r":0,"e":"Le parasympathique sacré commande l'érection ; le sympathique intervient plutôt sur l'éjaculation.","s":12},{"q":"Autour de quel vaisseau se situe le plexus cardiaque ?","o":["La crosse aortique","La veine cave inférieure","L'artère pulmonaire droite uniquement","Le tronc cœliaque"],"r":0,"e":"Le plexus cardiaque entoure la crosse de l'aorte.","s":12},{"q":"L'étymologie du mot « anatomie » signifie :","o":["Étude du corps","Découper en parties","Corps humain","Forme et structure"],"r":1,"e":"« Ana » (parties) + « Tomein » (couper).","s":13},{"q":"En position anatomique de référence, l'avant-bras est en :","o":["Pronation","Supination","Position neutre","Flexion"],"r":1,"e":"Position anatomique : avant-bras en SUPINATION, paumes vers l'avant.","s":13},{"q":"Combien de systèmes anatomiques sont étudiés en anatomie systémique ?","o":["8","9","10","11"],"r":2,"e":"10 systèmes : squelettique, musculaire, nerveux, tégumentaire, circulatoire, digestif, respiratoire, urinaire, endocrinien, reproducteur.","s":13},{"q":"Le terme « distal » signifie :","o":["Près du tronc","Loin du tronc","Au-dessus","En arrière"],"r":1,"e":"Distal = éloigné du point d'attache (loin du tronc). Proximal = proche.","s":13},{"q":"Le terme « homolatéral » signifie :","o":["Du même côté","Du côté opposé","Devant","Derrière"],"r":0,"e":"Homolatéral = même côté ; controlatéral = côté opposé.","s":13},{"q":"Le squelette axial comprend :","o":["Crâne + bras + jambes","Crâne + colonne + thorax","Colonne + bassin","Tout le squelette"],"r":1,"e":"Squelette axial = crâne + colonne vertébrale + thorax.","s":13},{"q":"Le squelette appendiculaire comprend :","o":["Le crâne, la face et la mandibule","Les membres supérieurs et inférieurs","La colonne vertébrale et le sacrum","Le thorax, le sternum et toutes les côtes"],"r":1,"e":"Le squelette appendiculaire = membres supérieurs + membres inférieurs (avec ceintures). Les ceintures y sont rattachées.","s":13},{"q":"Quel os de la ceinture scapulaire est listé ?","o":["Iliaque","Fémur","Omoplate","Sternum"],"r":2,"e":"Ceinture scapulaire = omoplate + clavicule.","s":13},{"q":"Le corps d'un os long s'appelle :","o":["Épiphyse","Diaphyse","Métaphyse","Apophyse"],"r":1,"e":"La diaphyse est le corps de l'os long.","s":13},{"q":"Les extrémités élargies d'un os long s'appellent :","o":["Diaphyse","Épiphyse","Métaphyse","Apophyse"],"r":1,"e":"Les épiphyses sont les extrémités élargies, sites d'articulation.","s":13},{"q":"La métaphyse est :","o":["Le centre de l'os long, sa partie moyenne","La zone élargie de la diaphyse, près de l'épiphyse","Une extrémité de l'os, couverte de cartilage","Un type particulier d'os court du carpe"],"r":1,"e":"La métaphyse est la zone élargie de la diaphyse proche de l'épiphyse (contient le cartilage de croissance).","s":13},{"q":"L'os cortical est aussi appelé :","o":["Os spongieux","Os compact","Os trabéculaire","Os médullaire"],"r":1,"e":"Os cortical = os compact (couche externe dense).","s":13},{"q":"L'os spongieux est caractérisé par :","o":["Une forte densité","Une porosité élevée","L'absence de cellules","De la moelle osseuse"],"r":1,"e":"L'os spongieux a une porosité élevée qui permet d'absorber les chocs et répartir la pression.","s":13},{"q":"Les os sésamoïdes ont pour fonction :","o":["De former les articulations","De protéger les tendons de l'usure","De fabriquer les globules rouges","De stocker la moelle"],"r":1,"e":"Os sésamoïdes : os courts insérés dans un tendon, protègent les tendons de l'usure excessive.","s":13},{"q":"Un exemple d'os sésamoïde est :","o":["L'humérus","La rotule","Le crâne","Le sacrum"],"r":1,"e":"La rotule est le plus gros os sésamoïde du corps humain.","s":13},{"q":"Combien de paires de vertèbres cervicales existent ?","o":["5","7","12","6"],"r":1,"e":"7 vertèbres cervicales.","s":13},{"q":"Combien de vertèbres thoraciques existent ?","o":["5","7","12","10"],"r":2,"e":"12 vertèbres thoraciques (correspondant aux 12 paires de côtes).","s":13},{"q":"Combien de vertèbres lombaires existent ?","o":["3","5","7","12"],"r":1,"e":"5 vertèbres lombaires.","s":13},{"q":"Une fonction métabolique du squelette est :","o":["La digestion des graisses","Le stockage du calcium","La respiration cellulaire du muscle","La filtration du sang"],"r":1,"e":"Le squelette stocke les sels (notamment le calcium) et a une fonction hématopoïétique.","s":13},{"q":"L'hématopoïèse a lieu dans :","o":["Le périoste, à la surface externe de l'os","La diaphyse compacte, au centre","La moelle rouge de l'os spongieux","Le cartilage de croissance"],"r":2,"e":"L'hématopoïèse (production de cellules sanguines) a lieu dans la moelle osseuse rouge de l'os spongieux.","s":13},{"q":"L'os qui appartient à la face est :","o":["Pariétal","Vomer","Occipital","Sphénoïde"],"r":1,"e":"Le vomer est un os de la face (forme la cloison nasale).","s":13},{"q":"L'os qui appartient au neurocrâne est :","o":["Maxillaire","Ethmoïde","Mandibule","Palatin"],"r":1,"e":"L'ethmoïde fait partie du neurocrâne (mais aussi de la face).","s":13},{"q":"Le terme « ventral » est synonyme de :","o":["Postérieur","Antérieur","Supérieur","Latéral"],"r":1,"e":"Ventral = antérieur ; dorsal = postérieur.","s":13},{"q":"Le terme « caudal » signifie :","o":["Vers la tête","Vers les pieds","Vers le centre","Vers l'extérieur"],"r":1,"e":"Caudal = inférieur, vers les pieds ; céphalique = supérieur, vers la tête.","s":13},{"q":"Le tissu osseux capable d'absorber les chocs grâce à sa porosité est :","o":["L'os cortical","L'os spongieux","Le périoste","Le cartilage"],"r":1,"e":"L'os spongieux, par sa porosité, répartit les pressions et absorbe les chocs.","s":13},{"q":"Le tissu osseux capable de supporter les tensions musculaires longitudinales est :","o":["L'os spongieux","L'os cortical","La moelle","Le cartilage"],"r":1,"e":"L'os cortical supporte les charges et tensions musculaires longitudinales.","s":13},{"q":"Le squelette protège :","o":["Le cœur, les poumons et le cerveau","Le cerveau seul, sans le reste","Les viscères seuls, sans le cerveau ni le cœur","Aucun organe, il ne fait que porter"],"r":0,"e":"Le squelette protège les structures vitales : cœur, poumons, cerveau et autres viscères.","s":13},{"q":"En anatomie, « médial » signifie :","o":["Vers l'extérieur","Vers l'axe médian","Au-dessus","En avant"],"r":1,"e":"Médial = interne, vers l'axe médian du corps ; latéral = externe.","s":13},{"q":"Un os court a pour caractéristique :","o":["Longueur > largeur > épaisseur","Longueur = largeur = épaisseur","Longueur < épaisseur","Longueur et largeur > épaisseur"],"r":1,"e":"Os court : les trois dimensions sont à peu près équivalentes (ex : os du carpe, du tarse).","s":13},{"q":"Un os irrégulier se caractérise par :","o":["Une forme cylindrique et allongée","Une morphologie complexe et non géométrique","Une faible épaisseur et une forme plate","Une petite taille et une forme cubique régulière"],"r":1,"e":"Os irréguliers : morphologie complexe qui ne correspond pas aux formes géométriques classiques (ex : vertèbres).","s":13},{"q":"L'étymologie grecque du mot anatomie associe :","o":["« Ana », les parties, et « tomein », couper","« Ana », au-dessus, et « tomein », voir","« Anatos », le corps, et « mein », étudier en détail","« Ana », sans, et « tomos », la section"],"r":0,"e":"C'est la branche de la médecine qui étudie la forme et la structure des organismes. Anatomie signifie découper en parties, séparer sans détruire.","s":13},{"q":"L'anatomie systémique distingue :","o":["10 systèmes","8 systèmes","12 systèmes","6 systèmes"],"r":0,"e":"Squelettique, musculaire, nerveux, tégumentaire, circulatoire, digestif, respiratoire, urinaire, endocrinien et reproducteur.","s":13},{"q":"Dans la position anatomique de référence, les avant-bras sont :","o":["En supination","En pronation","En position neutre","Fléchis"],"r":0,"e":"Les talons sont joints et les pieds écartés, le regard vers l'horizon.","s":13},{"q":"Les os courts se définissent par :","o":["Trois dimensions à peu près égales","Une longueur supérieure aux autres","Une épaisseur faible, devant la longueur et la largeur","Une morphologie complexe, non géométrique"],"r":0,"e":"Les os irréguliers ont, eux, une morphologie complexe non géométrique. Longueur, largeur et épaisseur sont approximativement égales.","s":13},{"q":"Les os sésamoïdes sont :","o":["Des os courts inclus dans un tendon ou une capsule","Des os longs, avec une diaphyse et deux épiphyses distinctes","Des os plats, formant la voûte du crâne","Des os irréguliers, comme les vertèbres"],"r":0,"e":"La rotule en est l'exemple le plus volumineux. Ils protègent les tendons de l'usure ; la rotule en est l'exemple.","s":13},{"q":"La métaphyse correspond :","o":["À la zone élargie de la diaphyse, près de l'épiphyse","Au corps de l'os, entre ses deux extrémités","Aux extrémités articulaires, recouvertes de cartilage","Au seul cartilage de croissance, chez l'adulte"],"r":0,"e":"La diaphyse est le corps de l'os et l'épiphyse ses extrémités élargies.","s":13},{"q":"L'os cortical, ou compact :","o":["Supporte les fortes charges et absorbe les tractions","Répartit la pression grâce à sa porosité élevée","Absorbe les chocs grâce à ses travées osseuses","Est très poreux, avec de larges cavités médullaires"],"r":0,"e":"L'os spongieux, à porosité élevée, répartit la pression et absorbe les chocs. Il supporte aussi les tensions musculaires longitudinales.","s":13},{"q":"Parmi les fonctions du système squelettique, le cours cite :","o":["Le stockage du calcium et l'hématopoïèse","La seule protection des organes vitaux","Le seul soutien de l'organisme, sans autre rôle","Le seul mouvement, comme base mécanique"],"r":0,"e":"S'y ajoutent la protection des structures vitales, la base mécanique du mouvement et le soutien de l'organisme.","s":13},{"q":"L'épiphyse est constituée :","o":["D'os spongieux sous une fine couche compacte","D'os compact uniquement, sans cartilage","D'os spongieux uniquement, sans cartilage","De cartilage uniquement, sans aucun tissu osseux"],"r":0,"e":"C'est le site d'articulation de l'os long. Elle porte aussi du cartilage articulaire.","s":13},{"q":"La diaphyse est principalement constituée :","o":["De tissu osseux compact, pour la résistance","D'os spongieux, pour amortir les chocs","De cartilage, pour la croissance","De moelle jaune, pour la réserve"],"r":0,"e":"C'est le corps de l'os long.","s":13},{"q":"Les os larges ou plats se définissent par :","o":["Une longueur et une largeur supérieures à l'épaisseur","Une longueur supérieure aux autres dimensions","Des dimensions égales dans les trois directions de l'espace","Une forme complexe, non géométrique"],"r":0,"e":"Les os longs ont, eux, une longueur supérieure à la largeur et à l'épaisseur.","s":13},{"q":"Combien d'os composent le neurocrâne ?","o":["6","7","8","9"],"r":2,"e":"Le neurocrâne contient 8 os : 2 pariétaux, 2 temporaux, frontal, ethmoïde, sphénoïde, occipital.","s":14},{"q":"Quel os du crâne est PAIR ?","o":["Frontal","Sphénoïde","Pariétal","Occipital"],"r":2,"e":"Le pariétal et le temporal sont les seuls os pairs du neurocrâne.","s":14},{"q":"Le seul os mobile du crâne est :","o":["Maxillaire","Mandibule","Vomer","Hyoïde"],"r":1,"e":"La mandibule est le seul os qui présente une mobilité (via l'ATM).","s":14},{"q":"L'os hyoïde s'articule avec :","o":["L'os temporal","Le maxillaire","La mandibule","Aucun autre os"],"r":3,"e":"L'os hyoïde est unique : il est relié au crâne uniquement par des muscles et ligaments.","s":14},{"q":"Le foramen magnum se trouve sur :","o":["L'occipital","Le pariétal","Le sphénoïde","Le frontal"],"r":0,"e":"Le foramen occipital ou magnum est sur l'occipital — passage de la moelle allongée et artères vertébrales.","s":14},{"q":"Quel nerf passe par le foramen olfactif de l'ethmoïde ?","o":["Nerf I (olfactif)","Nerf II (optique)","Nerf V (trijumeau)","Nerf VII (facial)"],"r":0,"e":"Le nerf olfactif (I) pénètre dans le crâne par les foramens olfactifs de la lame criblée.","s":14},{"q":"Quel nerf passe par le canal optique du sphénoïde ?","o":["Le nerf olfactif, ou nerf I","Le nerf optique, ou nerf II","Le nerf moteur oculaire, III","Le nerf trijumeau, ou nerf V, en entier"],"r":1,"e":"Le canal optique livre passage au nerf optique (II) et à l'artère ophtalmique.","s":14},{"q":"Le foramen ovale du sphénoïde livre passage au :","o":["Nerf maxillaire (V2)","Nerf mandibulaire (V3)","Nerf ophtalmique (V1)","Nerf facial (VII)"],"r":1,"e":"Le foramen ovale livre passage au V3 (mandibulaire), branche du trijumeau.","s":14},{"q":"Le grand foramen rond livre passage au :","o":["Le nerf ophtalmique, ou V1","Le nerf maxillaire, ou V2","Le nerf mandibulaire, ou V3","L'artère méningée moyenne, en arrière"],"r":1,"e":"Le grand foramen rond = nerf maxillaire supérieur (V2).","s":14},{"q":"Le petit foramen rond livre passage à :","o":["L'artère méningée moyenne","L'artère vertébrale","La veine jugulaire","Le nerf hypoglosse"],"r":0,"e":"Le petit foramen rond donne passage à l'artère méningée moyenne.","s":14},{"q":"Quel os contient la selle turcique ?","o":["Frontal","Ethmoïde","Sphénoïde","Occipital"],"r":2,"e":"La selle turcique (fosse pituitaire) abrite l'hypophyse, sur le sphénoïde.","s":14},{"q":"Quels nerfs passent par le conduit auditif interne ?","o":["VII et VIII","V et VII","II et III","IX et X"],"r":0,"e":"Le conduit auditif interne livre passage au nerf facial (VII) et au vestibulocochléaire (VIII).","s":14},{"q":"Le canal carotidien se trouve sur :","o":["Le sphénoïde","Le temporal","L'occipital","Le frontal"],"r":1,"e":"Le canal carotidien (artère carotide interne) est sur le temporal.","s":14},{"q":"Le foramen stylomastoïdien livre passage à :","o":["Le nerf trijumeau, ou V","Le nerf facial, ou VII","Le nerf glossopharyngien, ou IX","Le nerf vague, ou X"],"r":1,"e":"Le foramen stylomastoïdien donne sortie au nerf facial (VII) et à l'artère stylomastoïdienne.","s":14},{"q":"La crista galli appartient à quel os ?","o":["Sphénoïde","Ethmoïde","Frontal","Vomer"],"r":1,"e":"L'apophyse crista galli est sur l'ethmoïde, pour l'insertion des méninges.","s":14},{"q":"La lame papyracée (orbitaire) appartient à :","o":["Maxillaire","Frontal","Ethmoïde","Lacrymal"],"r":2,"e":"La lame papyracée de l'ethmoïde forme la paroi interne de l'orbite.","s":14},{"q":"Combien de paires d'os y a-t-il dans le viscérocrâne (face) ?","o":["5 paires + 2 impairs","6 paires + 2 impairs","6 paires + 1 impair","7 paires"],"r":1,"e":"6 paires (maxillaire, zygomatique, lacrymal, nasal, cornet inférieur, palatin) + vomer + mandibule (impairs).","s":14},{"q":"Le vomer participe à :","o":["L'arcade zygomatique","La cloison nasale","Le palais dur","L'orbite"],"r":1,"e":"Le vomer forme la partie postérieure de la cloison nasale.","s":14},{"q":"L'arcade zygomatique est formée par :","o":["Le frontal et le temporal, par leurs processus","Le malaire et le maxillaire","Le malaire et le temporal, par leurs processus","Le maxillaire seul, par son processus"],"r":2,"e":"Le processus temporal de l'os zygomatique + le processus zygomatique du temporal forment l'arcade zygomatique. Le malaire est l'os zygomatique.","s":14},{"q":"Combien de cornets nasaux existe-t-il par côté ?","o":["2","3","4","5"],"r":1,"e":"3 cornets par côté : supérieur (ethmoïde), moyen (ethmoïde), inférieur (os indépendant).","s":14},{"q":"Le condyle mandibulaire s'articule avec :","o":["Le processus zygomatique du temporal","La fosse mandibulaire de l'os temporal","Le processus coronoïde du maxillaire","La grande aile du sphénoïde"],"r":1,"e":"Le condyle mandibulaire s'articule avec la fosse mandibulaire (cavité glénoïde) du temporal — c'est l'ATM.","s":14},{"q":"Le processus coronoïde de la mandibule est le site d'insertion :","o":["Du muscle masséter","Du muscle temporal","Du buccinateur","Du ptérygoïdien"],"r":1,"e":"Le processus coronoïde reçoit l'insertion du muscle temporal (masticateur).","s":14},{"q":"L'artère méningée moyenne marque quel os ?","o":["Le frontal","Le pariétal","L'occipital","Le sphénoïde"],"r":1,"e":"Sur la face interne du pariétal, on retrouve les empreintes de l'artère méningée moyenne (en feuille de vigne).","s":14},{"q":"Combien de fosses occipitales y a-t-il ?","o":["2","3","4","5"],"r":2,"e":"4 fosses occipitales : 2 cérébrales (supérieures) et 2 cérébelleuses (inférieures).","s":14},{"q":"Le foramen condylien antérieur (canal de l'hypoglosse) livre passage au :","o":["Le nerf glossopharyngien, IX","Le nerf vague, X, et sa branche laryngée","Le nerf accessoire, XI","Le nerf hypoglosse, XII"],"r":3,"e":"Le canal de l'hypoglosse livre passage au nerf XII (hypoglosse).","s":14},{"q":"L'os sphénoïde s'articule avec :","o":["Seulement les os pairs","Tous les os du neurocrâne","Uniquement l'occipital","Uniquement le frontal"],"r":1,"e":"Le sphénoïde s'articule avec TOUS les os du neurocrâne + pommettes, palatin et vomer.","s":14},{"q":"Le palais dur est formé par :","o":["Le maxillaire en avant et le palatin en arrière","Le maxillaire seul, sur toute la longueur","Le palatin seul, du bord alvéolaire au voile du palais","Le vomer et le palatin, en arrière seulement"],"r":0,"e":"Processus palatin du maxillaire = 2/3 antérieurs ; lame horizontale du palatin = 1/3 postérieur. Le maxillaire en forme les 2/3 antérieurs, le palatin le 1/3 postérieur.","s":14},{"q":"La fente sphénoïdale livre passage :","o":["Aux nerfs moteurs de l'œil et au V1","Au nerf olfactif, I, et à ses filets","À l'artère carotide interne et au V2","Aux nerfs VII et VIII"],"r":0,"e":"La fente sphénoïdale = nerfs moteurs de l'œil (III, IV, VI), veines ophtalmiques, branches du nerf ophtalmique (V1). Les nerfs moteurs de l'œil sont III, IV et VI ; les veines ophtalmiques y passent aussi.","s":14},{"q":"La fosse pituitaire / selle turcique contient :","o":["L'hypothalamus","L'hypophyse","L'épiphyse","Le bulbe olfactif"],"r":1,"e":"L'hypophyse est logée dans la selle turcique du sphénoïde.","s":14},{"q":"Le foramen mentonnier se trouve sur :","o":["Le maxillaire","La mandibule","Le malaire","Le palatin"],"r":1,"e":"Le foramen mentonnier est sur la mandibule — passage des nerfs et vaisseaux pour la peau du menton.","s":14},{"q":"Le neurocrâne comprend :","o":["Huit os, dont deux pariétaux et deux temporaux","Quatorze os, comme la face","Six os, tous impairs et médians","Douze os, dont six pairs et six impairs du crâne"],"r":0,"e":"Le viscérocrâne, ou face, en compte 14, plus les 3 osselets de chaque oreille. S'y ajoutent le frontal, l'ethmoïde, le sphénoïde et l'occipital.","s":14},{"q":"Le seul os mobile de la face est :","o":["La mandibule","Le maxillaire supérieur","L'os zygomatique","Le vomer"],"r":0,"e":"Le viscérocrâne comprend aussi les os lacrymaux, nasaux, les cornets inférieurs, les palatins et le vomer.","s":14},{"q":"Le foramen supra-orbitaire de l'os frontal livre passage :","o":["À l'artère et au nerf supra-orbitaires","Au nerf olfactif et à ses filets","À l'artère méningée moyenne, vers la dure-mère","Au nerf hypoglosse, vers la langue"],"r":0,"e":"La glabelle, l'arcade supra-orbitaire, le processus zygomatique et l'épine nasale complètent la face antérieure.","s":14},{"q":"Le foramen borgne de l'os frontal livre passage :","o":["À une veine ou à un prolongement de la dure-mère","Au nerf optique et à l'artère ophtalmique","À l'artère carotide interne","Au nerf facial et à l'artère stylomastoïdienne, en bas"],"r":0,"e":"La face postérieure porte aussi la fosse frontale, la bosse orbitaire et la gouttière du sinus longitudinal supérieur.","s":14},{"q":"L'os pariétal est décrit comme :","o":["Pair et quadrilatère, à quatre bords et quatre angles","Impair et médian, à une seule face convexe","Pair et triangulaire, à trois bords et trois angles distincts","Impair et irrégulier, sans bord ni angle défini"],"r":0,"e":"Sa face externe est convexe et il forme la paroi latérale du crâne. Il présente deux faces.","s":14},{"q":"La fosse pariétale, sur la face interne, présente :","o":["Des gouttières en feuille de vigne, de l'artère méningée","La gouttière du sinus longitudinal, sur la ligne médiane","Le foramen pariétal, pour la veine émissaire de Santorin","Les lignes courbes temporales, en dehors"],"r":0,"e":"Le foramen pariétal livre passage à la veine émissaire de Santorin. Il s'agit de l'artère méningée moyenne.","s":14},{"q":"La courbure temporale inférieure du pariétal donne insertion :","o":["Au muscle temporal","À l'aponévrose temporale","Au masséter","Au SCM"],"r":0,"e":"La courbure temporale supérieure reçoit, elle, l'aponévrose temporale.","s":14},{"q":"Le foramen occipital, ou magnum, livre passage :","o":["À la moelle allongée, aux artères vertébrales","Au seul bulbe, sans aucun vaisseau","Aux seules artères vertébrales, sans le bulbe","Au nerf hypoglosse et à la veine jugulaire"],"r":0,"e":"Le canal hypoglosse, ou foramen condylien antérieur, livre passage au nerf XII. Les nerfs spinaux y passent aussi.","s":14},{"q":"La crête occipitale interne sépare :","o":["Les fosses cérébelleuses","Les fosses cérébrales","Les condyles","Les foramens"],"r":0,"e":"Le sillon sinusal longitudinal supérieur sépare, lui, les fosses cérébrales ; l'occipital compte 4 fosses.","s":14},{"q":"Les trois portions de l'os temporal sont :","o":["Squameuse, mastoïdienne et pétrotympanique","Squameuse, zygomatique et mastoïdienne","Pétreuse, tympanique et ptérygoïdienne","Écailleuse, styloïde et condylienne"],"r":0,"e":"Il contient l'oreille moyenne et interne et présente une surface convexe externe.","s":14},{"q":"Le conduit auditif interne livre passage :","o":["Aux nerfs facial et vestibulocochléaire","Au seul nerf facial, sans autre nerf","Au nerf trijumeau et à ses trois branches","À l'artère carotide interne"],"r":0,"e":"Le foramen stylomastoïdien livre passage à l'artère stylomastoïdienne et au nerf facial.","s":14},{"q":"Le foramen lacérum postérieur, ou fosse jugulaire, livre passage :","o":["À la veine jugulaire interne","À l'artère carotide interne","Au nerf facial","Au nerf hypoglosse"],"r":0,"e":"Le canal carotidien livre passage à l'artère carotide interne.","s":14},{"q":"Le processus styloïde du temporal donne insertion :","o":["Aux muscles de la langue, du pharynx et de l'hyoïde","Au masséter, par son faisceau profond","Au muscle temporal, par son tendon terminal le plus profond","Au sterno-cléido-mastoïdien, en arrière"],"r":0,"e":"Le foramen mastoïdien livre passage à la veine émissaire et à l'artère mastoïdienne.","s":14},{"q":"Les trois parties de l'ethmoïde sont :","o":["Lame verticale, lame criblée et masses latérales","Le corps, les petites ailes et les grandes ailes","Les portions squameuse, pétreuse et tympanique","Deux lames seules, verticale et criblée, sans masses"],"r":0,"e":"C'est un os médian, impair et symétrique, formant base du crâne, orbite et fosses nasales. La lame horizontale est la lame criblée.","s":14},{"q":"La crista galli de l'ethmoïde sert :","o":["À l'insertion des méninges","Au passage du nerf olfactif","À l'articulation avec le vomer","Au soutien du cornet supérieur"],"r":0,"e":"Les sillons olfactifs, percés du foramen olfactif, livrent passage au nerf I.","s":14},{"q":"La lame papyracée de l'ethmoïde forme :","o":["La paroi interne de l'orbite","Le toit de l'orbite","Le plancher de l'orbite","La cloison nasale"],"r":0,"e":"Les sinus ethmoïdaux allègent le poids de la tête.","s":14},{"q":"Les cornets supérieur et moyen appartiennent :","o":["À l'ethmoïde, et réchauffent l'air inspiré","Au maxillaire, et filtrent l'air inspiré","Au vomer, et humidifient l'air inspiré","Au sphénoïde, et réchauffent puis humidifient l'air"],"r":0,"e":"Le cornet nasal inférieur est, lui, un os propre du viscérocrâne. Ils humidifient aussi l'air.","s":14},{"q":"Les quatre parties du sphénoïde sont :","o":["Le corps, les petites et grandes ailes, les ptérygoïdes","Deux ailes et deux processus, sans corps","Le corps et deux ailes seules, sans les processus ptérygoïdes","Trois portions, squameuse, pétreuse et tympanique"],"r":0,"e":"Il s'articule avec tous les os du neurocrâne, ainsi qu'avec les pommettes, le palatin et le vomer.","s":14},{"q":"La protubérance occipitale externe donne insertion :","o":["Au ligament cervical commun","Au seul trapèze, par ses fibres supérieures","Au sterno-cléido-mastoïdien","Aux splénius de la tête"],"r":0,"e":"Les condyles occipitaux s'articulent, eux, avec l'atlas.","s":14},{"q":"La lame perpendiculaire de l'ethmoïde forme :","o":["Une partie de la cloison nasale","Le toit de l'orbite","Le plancher du crâne","La paroi latérale du crâne"],"r":0,"e":"L'apophyse crista galli s'articule par son bord antérieur avec le frontal.","s":14},{"q":"Les fontanelles sont présentes chez :","o":["L'adulte","L'enfant","Le nouveau-né","L'adolescent"],"r":2,"e":"Les fontanelles sont des zones membraneuses présentes chez le nouveau-né, elles s'ossifient progressivement.","s":15},{"q":"La grande fontanelle est aussi appelée :","o":["Lambdatique","Bregmatique","Ptérique","Astérique"],"r":1,"e":"La fontanelle bregmatique = grande fontanelle (au point bregma).","s":15},{"q":"La petite fontanelle est aussi appelée :","o":["Bregmatique","Lambdatique","Ptérique","Astérique"],"r":1,"e":"La fontanelle lambdatique = petite fontanelle (au point lambda).","s":15},{"q":"Le ptérion est le point de rencontre de :","o":["Pariétal, temporal, occipital et sphénoïde","Pariétal, frontal, temporal et sphénoïde","Frontal, nasal, maxillaire et lacrymal","Occipital, temporal et pariétal"],"r":1,"e":"Le ptérion = rencontre du pariétal, frontal, temporal et sphénoïde (zone fragile, artère méningée moyenne en dessous).","s":15},{"q":"L'astérion est le point de rencontre de :","o":["Pariétal, temporal et occipital","Frontal, pariétal et sphénoïde","Occipital, sphénoïde et temporal","Frontal, temporal, sphénoïde et pariétal"],"r":0,"e":"Astérion = pariétal + temporal + occipital.","s":15},{"q":"La suture coronale unit :","o":["Les 2 pariétaux","Frontal + pariétaux","Pariétaux + occipital","Pariétal + temporal"],"r":1,"e":"Suture coronale : entre le frontal et les pariétaux.","s":15},{"q":"La suture sagittale unit :","o":["Les deux pariétaux, sur la ligne médiane","Le frontal et les pariétaux, en avant","Les pariétaux et l'occipital, derrière","Le frontal et les os nasaux"],"r":0,"e":"Suture sagittale : entre les 2 pariétaux (médiane).","s":15},{"q":"La suture lambdoïde unit :","o":["Frontal + pariétaux","Pariétaux + occipital","Pariétal + temporal","Frontal + temporal"],"r":1,"e":"Suture lambdoïde : entre les pariétaux et l'occipital.","s":15},{"q":"La suture squameuse unit :","o":["Pariétaux entre eux","Pariétal + temporal","Frontal + pariétal","Sphénoïde + frontal"],"r":1,"e":"Suture squameuse : entre le pariétal et le temporal.","s":15},{"q":"Les sutures sont classifiées comme :","o":["Des diarthroses mobiles","Des synarthroses fibreuses","Des amphiarthroses","Des énarthroses à surfaces sphériques"],"r":1,"e":"Les sutures sont des synarthroses fibreuses (articulations sans mobilité).","s":15},{"q":"Le bregma est :","o":["Le point sagittale + lambdoïde","Le point coronale + sagittale","Le ptérion","L'astérion"],"r":1,"e":"Le bregma est l'intersection des sutures coronale et sagittale.","s":15},{"q":"Le lambda est :","o":["Le point coronale + sagittale","Le point sagittale + lambdoïde","Le ptérion","L'astérion"],"r":1,"e":"Le lambda est l'intersection des sutures sagittale et lambdoïde.","s":15},{"q":"L'ATM se classifie comme :","o":["Une arthrodie à surfaces planes","Une énarthrose à surfaces sphériques","Une bicondyloméniscarthrose conjuguée","Une trochléarthrose à poulie"],"r":2,"e":"L'ATM est une bicondyloméniscarthrose conjuguée (deux condyles + ménisque, conjuguée car les 2 ATM travaillent ensemble).","s":15},{"q":"Le disque articulaire de l'ATM est composé de :","o":["Cartilage hyalin","Cartilage élastique","Fibrocartilage","Os spongieux"],"r":2,"e":"Le disque de l'ATM est en fibrocartilage, qui a une meilleure capacité de charge et de régénération.","s":15},{"q":"Sur l'ATM, le condyle mandibulaire s'articule avec :","o":["Le condyle temporal, en avant","La cavité glénoïde, ou fosse mandibulaire","Le processus zygomatique, en dehors","L'os malaire, au-dessous"],"r":1,"e":"Le condyle mandibulaire s'articule avec la fosse mandibulaire (cavité glénoïde) du temporal.","s":15},{"q":"Quel ligament n'est PAS un ligament accessoire de l'ATM ?","o":["Sphénomandibulaire","Stylomandibulaire","Ptérygomaxillaire","Coraco-acromial"],"r":3,"e":"Le coraco-acromial est un ligament de l'épaule (rien à voir avec l'ATM).","s":15},{"q":"Le ligament temporo-mandibulaire est :","o":["Principal","Accessoire","Croisé","Annulaire"],"r":0,"e":"Le ligament temporo-mandibulaire est le ligament principal de l'ATM (renforce la capsule).","s":15},{"q":"Le mouvement d'ouverture de la bouche est :","o":["Élévation","Abaissement","Propulsion","Diduction"],"r":1,"e":"L'abaissement = ouverture de la bouche.","s":15},{"q":"Le mouvement de fermeture est :","o":["Élévation","Abaissement","Propulsion","Diduction"],"r":0,"e":"L'élévation = fermeture de la bouche.","s":15},{"q":"La propulsion correspond à :","o":["Mandibule vers l'arrière","Mandibule vers l'avant","Mandibule sur le côté","Ouverture"],"r":1,"e":"Propulsion = mandibule projetée vers l'avant.","s":15},{"q":"La diduction correspond à :","o":["Ouverture verticale","Avant/arrière","Mouvement latéral","Rotation"],"r":2,"e":"La diduction (ou latéralité) = mouvement latéral de la mandibule.","s":15},{"q":"Le fibrocartilage de l'ATM a un avantage par rapport au cartilage hyalin :","o":["Il est plus dur et plus rigide que le cartilage hyalin","Il se répare et supporte les charges plus facilement","Il est plus léger que le cartilage hyalin","Il est plus mince que le cartilage hyalin"],"r":1,"e":"Le fibrocartilage offre une meilleure capacité de réparation, régénération et charge.","s":15},{"q":"L'ATM est dite « conjuguée » car :","o":["Elle a deux mouvements combinés, rotation et glissement","Les articulations droite et gauche vont de pair","Elle est double, avec deux disques par côté","Elle a deux surfaces articulaires seulement"],"r":1,"e":"« Conjuguée » signifie que les 2 ATM (D et G) fonctionnent toujours simultanément.","s":15},{"q":"L'articulation entre deux os du visage est dite :","o":["Crânienne","Faciale","Cranio-faciale","Sutura"],"r":1,"e":"Une articulation faciale unit deux os du visage (viscérocrâne).","s":15},{"q":"Une articulation entre le frontal et le nasal est :","o":["Crânienne","Faciale","Cranio-faciale","Sutura sagittale"],"r":2,"e":"Cranio-faciale : entre un os du neurocrâne (frontal) et un os de la face (nasal).","s":15},{"q":"La suture fronto-nasale est :","o":["Crânienne","Faciale","Cranio-faciale","Inexistante"],"r":2,"e":"Suture fronto-nasale = cranio-faciale.","s":15},{"q":"Au niveau du ptérion, on retrouve par-dessous :","o":["L'artère carotide interne, en profondeur","L'artère méningée moyenne","La veine jugulaire interne","Le nerf facial et ses branches"],"r":1,"e":"L'artère méningée moyenne passe sous le ptérion → zone de fragilité (hématome extra-dural possible).","s":15},{"q":"Quelle articulation est mobile dans le crâne ?","o":["Les sutures crâniennes de la voûte du crâne","Les sutures faciales du massif","L'articulation temporo-mandibulaire","Aucune, toutes sont des sutures"],"r":2,"e":"Seule l'ATM permet une réelle mobilité dans le crâne (toutes les autres articulations sont des sutures).","s":15},{"q":"Le disque articulaire de l'ATM est :","o":["Plat","Ovale biconcave","Triangulaire","Convexe"],"r":1,"e":"Le disque articulaire de l'ATM est ovale et biconcave (forme elliptique).","s":15},{"q":"La surface antéro-supérieure du disque de l'ATM s'articule avec :","o":["Le condyle mandibulaire","Le condyle temporal","La cavité glénoïde","Le processus zygomatique"],"r":1,"e":"La face antéro-supérieure du disque s'adapte au condyle temporal.","s":15},{"q":"Les fontanelles sont :","o":["Des zones membraneuses de la voûte, chez le nouveau-né","Des sutures ossifiées de l'adulte, sur la voûte crânienne","Des foramens livrant passage aux veines émissaires","Des sinus veineux creusés dans l'épaisseur de l'os"],"r":0,"e":"Elles permettent la croissance du crâne. Elles siègent à la jonction de plusieurs os.","s":15},{"q":"La fontanelle ptérique se situe :","o":["Au point ptérion","Au point bregma","Au point lambda","Au point astérion"],"r":0,"e":"Les quatre fontanelles sont bregmatique, lambdatique, ptérique et astérique.","s":15},{"q":"Les articulations de la tête se divisent en :","o":["Crâniennes, faciales et cranio-faciales","Mobiles, semi-mobiles et immobiles","Antérieures, moyennes et postérieures","Supérieures, moyennes, inférieures et latérales"],"r":0,"e":"Ce sont toutes des sutures, c'est-à-dire des synarthroses fibreuses sans mobilité.","s":15},{"q":"L'astérion correspond à la rencontre :","o":["Du pariétal, du temporal et de l'occipital","Du pariétal, du temporal, du frontal et du sphénoïde","Des sutures coronale et sagittale","Des sutures sagittale et lambdoïde"],"r":0,"e":"Le ptérion réunit quatre os : pariétal, temporal, frontal et sphénoïde.","s":15},{"q":"Le ptérion constitue une zone fragile car :","o":["L'artère méningée moyenne passe juste en dessous","L'os y est absent, remplacé par une membrane fibreuse","Il correspond à une fontanelle restée ouverte","Il n'y a pas de suture entre les os à ce niveau"],"r":0,"e":"C'est le point de rencontre de quatre os du crâne.","s":15},{"q":"L'articulation temporo-mandibulaire est classée comme :","o":["Une bicondyloméniscarthrose conjuguée","Une trochléarthrose à une poulie","Une arthrodie à surfaces planes","Une énarthrose, à tête et cavité sphériques"],"r":0,"e":"Le terme « conjuguée » signifie que les deux ATM travaillent ensemble.","s":15},{"q":"La surface temporale de l'ATM comprend :","o":["Le condyle temporal et la cavité glénoïde","Le seul condyle temporal, sans cavité","La seule fosse mandibulaire","Le processus zygomatique et l'arcade"],"r":0,"e":"La surface mandibulaire est constituée du condyle mandibulaire. La cavité glénoïde est aussi appelée fosse mandibulaire.","s":15},{"q":"Le disque interarticulaire de l'ATM est :","o":["Ovale, biconcave et fibrocartilagineux","Circulaire et en cartilage hyalin","Plan, biconvexe et en tissu osseux spongieux","Absent, remplacé par du liquide"],"r":0,"e":"Sa surface antéro-supérieure répond au condyle temporal et sa surface postéro-inférieure au condyle mandibulaire.","s":15},{"q":"L'avantage du fibrocartilage du disque de l'ATM est :","o":["Une meilleure réparation et un meilleur support des charges","Une plus grande souplesse que le cartilage hyalin","Une meilleure vascularisation que le cartilage hyalin","Une moindre épaisseur, d'où une meilleure congruence articulaire"],"r":0,"e":"Cela lui permet de supporter les contraintes répétées de la mastication.","s":15},{"q":"La capsule de l'ATM comprend :","o":["Des fibres longues entre les os, courtes vers le ménisque","Des fibres uniformes, toutes de même longueur","Uniquement des fibres longues, du temporal à la mandibule","Uniquement des fibres courtes, vers le ménisque"],"r":0,"e":"Le ligament temporo-mandibulaire et les ligaments collatéraux ou discaux la renforcent. Les fibres longues relient temporal et mandibule ; les courtes les relient au ménisque.","s":15},{"q":"Les ligaments accessoires de l'ATM sont :","o":["Sphénomandibulaire, stylomandibulaire et ptérygomaxillaire","Temporo-mandibulaire latéral, collatéraux et discaux","Stylo-hyoïdien, sphéno-maxillaire et ptérygo-épineux","Capsulaire, collatéral médial et collatéral latéral"],"r":0,"e":"Ils complètent les moyens d'union de l'articulation.","s":15},{"q":"La diduction de l'ATM correspond :","o":["Au mouvement de latéralité","Au mouvement d'ouverture","Au mouvement de fermeture","Au mouvement de propulsion"],"r":0,"e":"Les cinq mouvements sont abaissement, élévation, propulsion, rétropulsion et diduction.","s":15},{"q":"Le bregma correspond à la rencontre :","o":["Des sutures coronale et sagittale","Des sutures sagittale et lambdoïde","De quatre os","De trois os"],"r":0,"e":"Le lambda correspond à la rencontre des sutures sagittale et lambdoïde.","s":15},{"q":"Combien de vertèbres cervicales y a-t-il ?","o":["5","7","10","12"],"r":1,"e":"7 vertèbres cervicales (C1 à C7).","s":16},{"q":"Combien de vertèbres thoraciques (dorsales) ?","o":["7","10","12","15"],"r":2,"e":"12 vertèbres thoraciques (T1-T12).","s":16},{"q":"Combien de vertèbres lombaires ?","o":["3","5","7","12"],"r":1,"e":"5 vertèbres lombaires.","s":16},{"q":"Le sacrum est constitué de la fusion de :","o":["3 vertèbres","4 vertèbres","5 vertèbres","6 vertèbres"],"r":2,"e":"Le sacrum résulte de la fusion de 5 vertèbres sacrées.","s":16},{"q":"Le coccyx est constitué de la fusion de :","o":["2-3 vertèbres","4-5 vertèbres","5-6 vertèbres","7 vertèbres"],"r":1,"e":"Le coccyx = fusion de 4 à 5 vertèbres coccygiennes.","s":16},{"q":"La courbure cervicale est une :","o":["Cyphose","Lordose","Scoliose","Aucune"],"r":1,"e":"Cervicale et lombaire = LORDOSE (concavité postérieure). Thoracique et sacrée = cyphose.","s":16},{"q":"La courbure thoracique est une :","o":["Cyphose","Lordose","Scoliose","Aucune"],"r":0,"e":"Thoracique et sacrée = cyphose (concavité antérieure).","s":16},{"q":"L'atlas est :","o":["C1","C2","C7","T1"],"r":0,"e":"L'atlas = C1, première vertèbre cervicale.","s":16},{"q":"L'axis est :","o":["C1","C2","C7","T1"],"r":1,"e":"L'axis = C2, possède l'apophyse odontoïde.","s":16},{"q":"L'apophyse odontoïde appartient à :","o":["L'atlas","L'axis","C7","Le sacrum"],"r":1,"e":"L'apophyse odontoïde (dent) appartient à l'axis (C2), s'articule avec l'atlas.","s":16},{"q":"L'atlas n'a pas de :","o":["Apophyse épineuse","Corps vertébral","Apophyse transverse","Masse latérale"],"r":1,"e":"L'atlas est unique : il n'a pas de corps vertébral.","s":16},{"q":"Le foramen transverse des cervicales contient :","o":["L'artère carotide","L'artère vertébrale","La veine jugulaire","Le nerf phrénique"],"r":1,"e":"Le foramen transverse cervical livre passage à l'artère vertébrale.","s":16},{"q":"L'apophyse épineuse des cervicales (sauf C7) est :","o":["Unituberculée et longue, palpable sous la peau","Bifurquée, ou bituberculée","Horizontale et très longue","Absente, remplacée par un tubercule"],"r":1,"e":"Les apophyses épineuses cervicales (C3-C6) sont courtes et bifurquées (bituberculées). C7 est unituberculée.","s":16},{"q":"La C7 est aussi appelée :","o":["Vertèbre proéminente","Atlas","Axis","Vertèbre charnière"],"r":0,"e":"C7 = vertèbre proéminente (épineuse longue et palpable).","s":16},{"q":"Les vertèbres thoraciques s'articulent avec :","o":["Les côtes","Le sternum","Les vertèbres lombaires uniquement","Aucun os autre"],"r":0,"e":"Les vertèbres thoraciques s'articulent avec les côtes via hémifacettes du corps et facette de l'apophyse transverse.","s":16},{"q":"L'apophyse épineuse lombaire est :","o":["Bifurquée","Longue et oblique","Horizontalisée","Verticale"],"r":2,"e":"L'apophyse épineuse lombaire est horizontalisée (plate).","s":16},{"q":"Le promontoire est :","o":["L'apex du sacrum, en regard de S5","L'angle sacro-vertébral, avec L5","Le bord du coccyx, en Co1","La crête iliaque, en regard de L4"],"r":1,"e":"Le promontoire = angle sacro-vertébral, formé entre la base du sacrum et L5.","s":16},{"q":"L'articulation entre les corps vertébraux est :","o":["Une diarthrose","Une amphiarthrose","Une synarthrose","Une énarthrose"],"r":1,"e":"Articulation entre corps vertébraux = amphiarthrose (semi-mobile, avec disque intervertébral).","s":16},{"q":"Le centre du disque intervertébral s'appelle :","o":["Annulus fibrosus","Noyau pulpeux","Cartilage hyalin","Ménisque"],"r":1,"e":"Le noyau pulpeux (gélatineux) est au centre du disque ; l'annulus fibrosus à la périphérie.","s":16},{"q":"Le LVCA (ligament vertébral commun antérieur) s'étend de :","o":["L'occipital à S2","C1 au coccyx","C7 à L5","L'atlas au sacrum"],"r":0,"e":"LVCA : de l'apophyse basilaire de l'occipital à S2 (face antérieure des corps).","s":16},{"q":"Le LVCP (ligament vertébral commun postérieur) se trouve dans :","o":["Devant les corps","Le canal rachidien","Entre les épineuses","Entre les transverses"],"r":1,"e":"LVCP : face postérieure des corps, à l'intérieur du canal rachidien.","s":16},{"q":"Le ligament jaune (ligamentum flavum) unit :","o":["Les corps vertébraux","Les lames vertébrales","Les transverses","Les épineuses"],"r":1,"e":"Le ligamentum flavum relie les lames vertébrales adjacentes.","s":16},{"q":"Le ligament cervical postérieur est une expansion du :","o":["LVCA","Ligament jaune","Ligament supra-épineux","Ligament interépineux"],"r":2,"e":"Au niveau cervical, le ligament supra-épineux s'épaissit en ligament cervical postérieur (triangulaire).","s":16},{"q":"L'articulation atloïdo-odontoïdienne est :","o":["Une amphiarthrose","Une trocarthrose","Une énarthrose","Une bicondyloarthrose"],"r":1,"e":"L'articulation atloïdo-odontoïdienne = trocarthrose (rotation).","s":16},{"q":"L'articulation occipito-atloïdienne est :","o":["Trocarthrose","Bicondylarthrose","Arthrodie","Énarthrose"],"r":1,"e":"L'occipito-atloïdienne = bicondylarthrose (2 condyles occipitaux / cavités glénoïdes de l'atlas).","s":16},{"q":"Le ligament transverse a pour rôle de :","o":["Maintenir l'apophyse odontoïde","Relier les épineuses","Maintenir l'arc antérieur","Soutenir le LVCP"],"r":0,"e":"Le ligament transverse maintient l'apophyse odontoïde contre l'arc antérieur de l'atlas (= prévient le déplacement de l'odontoïde).","s":16},{"q":"Le ligament cruciforme est formé par :","o":["Le seul ligament transverse de l'atlas","Le transverse et ses faisceaux axoïdien et occipital","Les ligaments occipito-axoïdiens profonds","Les ligaments alaires, apical et transverse réunis du rachis"],"r":1,"e":"Le cruciforme = ligament transverse + axoïdal transverse + occipital transverse (forme une croix).","s":16},{"q":"Les foramens sacrés antérieurs livrent passage aux :","o":["Branches antérieures des nerfs sacrés","Artères vertébrales","Veines jugulaires","Branches postérieures des nerfs"],"r":0,"e":"Foramens sacrés antérieurs = branches antérieures des nerfs sacrés.","s":16},{"q":"Les foramens sacrés postérieurs livrent passage aux :","o":["Les branches antérieures des nerfs sacrés, en avant","Les branches postérieures des nerfs sacrés","Les artères iliaques internes","Le nerf coccygien et ses branches"],"r":1,"e":"Foramens sacrés postérieurs = branches postérieures des nerfs sacrés.","s":16},{"q":"Les hémifacettes articulaires se trouvent sur :","o":["Les vertèbres cervicales","Les vertèbres thoraciques","Les vertèbres lombaires","Le sacrum"],"r":1,"e":"Les hémifacettes articulaires (sup et inf) sont sur le corps des vertèbres thoraciques pour s'articuler avec les têtes costales.","s":16},{"q":"Parmi les rôles de la colonne vertébrale, le cours cite :","o":["Protéger la moelle, porter les viscères, ancrer les muscles","Protéger la moelle épinière, et seulement cela","Soutenir le tronc, sans rôle de protection","Servir uniquement d'insertion aux muscles du tronc et du dos"],"r":0,"e":"Toutes les vertèbres sont libres et indépendantes, sauf au niveau sacro-coccygien.","s":16},{"q":"La lame vertébrale s'étend :","o":["De l'apophyse transverse à l'apophyse épineuse","Du corps vertébral à l'apophyse transverse, en arrière","Du corps vertébral à l'apophyse épineuse","Entre deux corps vertébraux voisins"],"r":0,"e":"Le pédicule s'étend de l'apophyse transverse au corps vertébral et délimite les foramens de conjugaison.","s":16},{"q":"Les apophyses semi-lunaires des vertèbres cervicales se situent :","o":["Sur la face supérieure du corps, en dehors","Sur la face inférieure du corps","Sur les apophyses transverses, en dehors","Sur les lames, en arrière du canal"],"r":0,"e":"Le corps cervical est allongé transversalement et le canal rachidien triangulaire à base large.","s":16},{"q":"L'apophyse épineuse cervicale type est :","o":["Courte, oblique et bifurquée","Longue, verticale et unique","Courte, horizontale et unique","Longue, horizontale et unituberculée"],"r":0,"e":"C7, la vertèbre proéminente, fait exception avec une épineuse unituberculée, longue et palpable.","s":16},{"q":"L'arc antérieur de l'atlas porte :","o":["Un tubercule en avant, une facette dentaire en arrière","Deux tubercules, l'un en avant et l'autre en arrière","Une apophyse épineuse courte et bifurquée","Un corps vertébral réduit, sans facette"],"r":0,"e":"L'atlas n'a pas de corps vertébral ; l'arc postérieur porte le tubercule postérieur. La facette s'articule avec l'odontoïde.","s":16},{"q":"Les masses latérales de l'atlas présentent :","o":["Des cavités glénoïdes en haut et des facettes pour l'axis en bas","Deux facettes supérieures seulement, sans facette inférieure","Un corps vertébral, avec deux faces articulaires","Une odontoïde, sur chaque masse latérale"],"r":0,"e":"Leurs apophyses transverses portent l'orifice transverse livrant passage à l'artère vertébrale. Les cavités glénoïdes reçoivent les condyles occipitaux.","s":16},{"q":"Les vertèbres thoraciques présentent :","o":["Des hémifacettes supérieures et inférieures pour les côtes","Des facettes complètes, une seule par corps vertébral","Aucune facette costale, ni sur le corps ni ailleurs","Des foramens transverses, pour le passage de l'artère vertébrale"],"r":0,"e":"Leurs apophyses transverses portent une facette articulaire antérieure pour la tubérosité costale.","s":16},{"q":"Le canal médullaire des vertèbres thoraciques est :","o":["Étroit et circulaire","Large et triangulaire","Ovalaire","Absent"],"r":0,"e":"Leurs apophyses épineuses sont longues et fortement obliques, orientées en bas et en arrière.","s":16},{"q":"Le corps des vertèbres lombaires se caractérise par :","o":["Un diamètre transversal supérieur à l'antéropostérieur","Un diamètre antéropostérieur supérieur au transversal","Des diamètres égaux, de forme circulaire","Une petite taille, inférieure aux cervicales"],"r":0,"e":"Leur canal rachidien est triangulaire et leur processus épineux horizontalisé.","s":16},{"q":"Le sacrum est décrit comme :","o":["Une pyramide quadrangulaire, base en haut, apex en bas","Un os plat, triangulaire, à base supérieure et pointe inférieure","Un os long, avec une diaphyse et deux épiphyses","Un os cubique, à six faces de même taille"],"r":0,"e":"Il résulte de la soudure de 5 vertèbres sacrées et comporte 4 faces.","s":16},{"q":"L'angle sacro-vertébral, ou promontoire, se situe :","o":["À la jonction avec la vertèbre L5","À la jonction avec le coccyx","Au milieu du sacrum, en S3","À la facette auriculaire"],"r":0,"e":"La face antérieure du sacrum est concave et porte la facette articulaire avec L5.","s":16},{"q":"Les foramens sacrés antérieurs livrent passage :","o":["Aux branches antérieures des nerfs sacrés","Aux branches postérieures, en arrière","À la moelle sacrée et au cône terminal","Aux artères sacrées latérales seules"],"r":0,"e":"Ils sont au nombre de 4 paires ; les foramens postérieurs livrent passage aux branches postérieures.","s":16},{"q":"Les tubercules sacrés postéro-externes correspondent :","o":["À l'ancien processus transverse","Aux processus articulaires","Aux épineuses fusionnées","Aux lames"],"r":0,"e":"Les tubercules postéro-internes correspondent, eux, aux processus articulaires ; la crête sacrée médiane résulte de la fusion des épineuses.","s":16},{"q":"Les bords latéraux du coccyx donnent insertion :","o":["Aux ligaments sacro-sciatiques et à l'ischio-coccygien","Au grand fessier, par ses fibres les plus inférieures","Aux seuls élévateurs de l'anus, en avant","Au psoas, par son tendon terminal"],"r":0,"e":"Il résulte de la fusion de 4 à 5 vertèbres coccygiennes et porte des petites cornes et des cornes latérales.","s":16},{"q":"L'annulus fibrosus est constitué :","o":["De fibrocartilage, en feuillets fibreux concentriques","D'une substance gélatineuse et molle, comme le noyau","De cartilage hyalin, comme les plateaux","D'os spongieux, comme le corps vertébral"],"r":0,"e":"Le noyau pulpeux, gélatineux et mou, occupe le centre du disque.","s":16},{"q":"Le ligament vertébral commun antérieur s'étend :","o":["De l'occipital à S2, sur la face antérieure des corps","De l'occipital au coccyx, en arrière","Dans le canal rachidien, de C2 à S1","Entre les lames, de l'axis à S1, comme le ligament jaune"],"r":0,"e":"Le ligament vertébral commun postérieur chemine, lui, dans le canal rachidien, de l'occipital à la première coccygienne. Il part de l'apophyse basilaire de l'occipital.","s":16},{"q":"Le ligament jaune relie :","o":["Les lames adjacentes, de l'axis à S1","Les épineuses, de C7 au sacrum","Les transverses, de T1 à L5","Les corps vertébraux, de C2 à S1"],"r":0,"e":"Les ligaments interépineux et supra-épineux unissent, eux, les apophyses épineuses.","s":16},{"q":"Au niveau cervical, le ligament supra-épineux devient :","o":["Le ligament cervical postérieur, de C7 à l'occiput","Le ligament jaune, entre les lames de C1 à C7","Le ligament nucal antérieur, devant les corps","Le ligament intertransversaire, de C2 à C7"],"r":0,"e":"Le ligament supra-épineux est un cordon médian apical et impair. Il est triangulaire et atteint la protubérance occipitale externe.","s":16},{"q":"L'union des processus transverses est assurée par :","o":["Les ligaments intertransversaire et costotransversaire","Les ligaments jaunes, tendus entre les lames voisines","Les ligaments interépineux, entre les épineuses","Le ligament vertébral commun antérieur, en avant"],"r":0,"e":"Chaque groupe de structures vertébrales possède son système ligamentaire propre. Le costotransversaire en cause est le ligament supérieur.","s":16},{"q":"L'articulation entre corps vertébraux est classée comme :","o":["Une amphiarthrose, donc semi-mobile","Une diarthrose, donc très mobile","Une synarthrose, donc totalement immobile","Une arthrodie, à surfaces planes"],"r":0,"e":"Le disque intervertébral en est l'élément central, de taille, forme et épaisseur variables selon les régions.","s":16},{"q":"Combien de paires de côtes y a-t-il ?","o":["10","11","12","13"],"r":2,"e":"12 paires de côtes.","s":17},{"q":"Combien de vraies côtes (vertébro-sternales) ?","o":["5","7","10","12"],"r":1,"e":"7 paires de vraies côtes (s'articulent directement avec le sternum via cartilages).","s":17},{"q":"Les côtes flottantes sont :","o":["8e et 9e","10e et 11e","11e et 12e","12e et 13e"],"r":2,"e":"11e et 12e côtes = côtes flottantes (pas d'articulation avec le sternum).","s":17},{"q":"Les côtes 8, 9, 10 sont appelées :","o":["Les vraies côtes, ou sternales","Les côtes vertébro-chondrales","Les côtes flottantes, sans attache","Les côtes articulaires, unies au sternum"],"r":1,"e":"8e, 9e, 10e = vertébro-chondrales (fusionnent avec le cartilage de la 7e côte).","s":17},{"q":"Le sternum est composé de :","o":["2 segments","3 segments","4 segments","5 segments"],"r":1,"e":"3 segments : manubrium, corps, processus xiphoïde.","s":17},{"q":"L'angle de Louis se trouve :","o":["Entre manubrium et corps","Entre corps et xiphoïde","Au sommet du manubrium","À l'apex du xiphoïde"],"r":0,"e":"L'angle de Louis = jonction manubrium-corps (repère pour la 2e côte).","s":17},{"q":"L'échancrure jugulaire se trouve :","o":["Sur le bord du sternum","Au sommet du manubrium","Sur le xiphoïde","Sur le corps"],"r":1,"e":"L'échancrure jugulaire (sternale) est au sommet du manubrium.","s":17},{"q":"Le sillon costal se trouve :","o":["Sur le bord supérieur","Sur le bord inférieur","Au milieu de la côte","Sur la tête"],"r":1,"e":"Le sillon costal (pour vaisseaux et nerfs intercostaux) est sur le bord INFÉRIEUR de la côte.","s":17},{"q":"Sur la 1ère côte, le tubercule de Lisfranc reçoit l'insertion du :","o":["Scalène moyen","Scalène antérieur","Scalène postérieur","Trapèze"],"r":1,"e":"Le tubercule de Lisfranc (1ère côte) = insertion du scalène antérieur, sépare les gouttières des vaisseaux sous-claviers.","s":17},{"q":"La 12e côte se caractérise par :","o":["Une grande courbure","L'absence d'angle postérieur","2 facettes articulaires","Un sillon costal très marqué"],"r":1,"e":"La 12e côte est plus petite et n'a pas d'angle postérieur.","s":17},{"q":"La tête de la côte s'articule avec :","o":["L'apophyse transverse d'une seule vertèbre","Les corps de deux vertèbres adjacentes","Le sternum, par une facette elliptique au bord latéral","Le manubrium, par l'incisure costale"],"r":1,"e":"La tête de côte s'articule avec les hémifacettes des corps vertébraux de 2 vertèbres adjacentes.","s":17},{"q":"La tubérosité costale s'articule avec :","o":["Le corps vertébral","L'apophyse transverse","Le sternum","La lame"],"r":1,"e":"La tubérosité costale s'articule avec l'apophyse transverse de la vertèbre.","s":17},{"q":"Les articulations costo-vertébrales sont des :","o":["Arthrodies","Énarthroses","Amphiarthroses","Synchondroses"],"r":0,"e":"Les articulations costo-vertébrales sont des arthrodies (planes).","s":17},{"q":"Les articulations costo-chondrales sont :","o":["Des arthrodies, à surfaces planes","Des synchondroses, à cartilage hyalin","Des amphiarthroses, à fibrocartilage","Des énarthroses, à tête sphérique"],"r":1,"e":"Côte-cartilage = synchondrose (cartilage hyalin).","s":17},{"q":"L'articulation sternale supérieure est :","o":["Arthrodie","Synchondrose","Amphiarthrose","Diarthrose"],"r":2,"e":"Manubrium-corps du sternum = amphiarthrose (fibrocartilage).","s":17},{"q":"Les côtes 11 et 12 ont :","o":["Deux facettes articulaires sur la tête","Une seule facette articulaire sur la tête","Pas de facette","Trois facettes"],"r":1,"e":"Les côtes flottantes (11-12) ont une seule facette articulaire sur la tête.","s":17},{"q":"L'extrémité antérieure de la côte présente :","o":["Une facette plane, pour le bord du sternum","Une facette elliptique, pour le cartilage costal","Une tubérosité rugueuse, pour l'insertion des scalènes","Une tête arrondie, pour le corps vertébral"],"r":1,"e":"L'extrémité antérieure de la côte présente une facette elliptique pour son cartilage costal.","s":17},{"q":"Le diaphragme est :","o":["La limite supérieure du thorax","La limite inférieure du thorax","Une côte","Un cartilage"],"r":1,"e":"Le diaphragme est la limite inférieure de la cage thoracique.","s":17},{"q":"Quel ligament n'appartient PAS à l'articulation costo-transversaire ?","o":["Costotransversaire postérieur","Costotransversaire supérieur","Costotransversaire interosseux","Costo-vertébral radié"],"r":3,"e":"Le ligament costo-vertébral radié appartient à l'articulation costo-vertébrale (pas costo-transversaire).","s":17},{"q":"Le sternum présente combien d'échancrures articulaires sur chaque bord latéral ?","o":["5","6","7","8"],"r":2,"e":"7 échancrures articulaires (pour les 7 cartilages costaux des vraies côtes).","s":17},{"q":"L'articulation entre les cartilages costaux entre eux est une :","o":["Synchondrose","Arthrodie","Amphiarthrose","Énarthrose"],"r":1,"e":"Interchondrale = arthrodie.","s":17},{"q":"La fonction principale de la cage thoracique est :","o":["Le mouvement du tronc et la posture du rachis","La digestion et le transit des aliments","La protection des viscères et la respiration","La phonation et la déglutition"],"r":2,"e":"Protection des viscères (cœur, poumons) + mécanique de la respiration.","s":17},{"q":"Le cartilage costal de la 7e côte reçoit :","o":["Les cartilages des côtes 8, 9 et 10","Les cartilages des côtes 11 et 12","Aucun cartilage, il s'insère seul sur le sternum","Le 1ᵉʳ cartilage costal, par en haut"],"r":0,"e":"Les cartilages des côtes 8, 9 et 10 fusionnent avec le cartilage de la 7e côte (puis vont au sternum).","s":17},{"q":"Les côtes vraies sont aussi appelées :","o":["Vertébro-chondrales","Vertébro-sternales","Flottantes","Atypiques"],"r":1,"e":"Vraies côtes = vertébro-sternales (s'articulent directement avec le sternum via leur cartilage).","s":17},{"q":"La limite supérieure du thorax passe par :","o":["Le xiphoïde, le rebord costal et T12","Le manubrium, la clavicule et T1","Le diaphragme, les côtes 11 et 12 et L1","Les dernières côtes, le sternum et T10"],"r":1,"e":"Limite supérieure = manubrium + clavicule + 1ère vertèbre thoracique.","s":17},{"q":"Le sillon costal contient :","o":["L'artère pulmonaire et ses branches","Les vaisseaux et nerfs intercostaux","Le canal thoracique et la veine azygos","La veine cave et le nerf phrénique"],"r":1,"e":"Le sillon costal (bord inférieur) contient l'artère, la veine et le nerf intercostaux.","s":17},{"q":"L'angle costal se trouve :","o":["À l'extrémité antérieure","À l'extérieur de la tubérosité","Au milieu de la côte","Sur la tête"],"r":1,"e":"L'angle de la côte est situé à l'extérieur de la tubérosité, c'est le point de plus grande courbure.","s":17},{"q":"Quelles côtes n'ont PAS de courbure de torsion ?","o":["1ère et 2e","11e et 12e","7e et 8e","Toutes"],"r":1,"e":"Les côtes flottantes (11e et 12e) n'ont pas de courbure de torsion.","s":17},{"q":"La face supéro-externe de la 2e côte reçoit :","o":["Le scalène antérieur et le sous-clavier","Les scalènes postérieurs et les dentelés","Le trapèze et l'élévateur de la scapula","Le grand pectoral et le petit pectoral, en avant"],"r":1,"e":"Face supéro-externe de la 2e côte = insertion des scalènes postérieurs et dentelés.","s":17},{"q":"Le processus xiphoïde est :","o":["Au sommet du sternum","Au milieu","À la base du sternum","Sur le bord latéral"],"r":2,"e":"Le processus xiphoïde est le segment INFÉRIEUR (base) du sternum.","s":17},{"q":"La limite supérieure de la cage thoracique passe par :","o":["Le manubrium, la clavicule et la 1ʳᵉ vertèbre thoracique","Le manubrium seul, avec l'incisure jugulaire en haut du sternum","La 1ʳᵉ côte seule, sur tout son trajet","L'angle de Louis et la 2ᵉ côte"],"r":0,"e":"Sa limite inférieure est le muscle diaphragme.","s":17},{"q":"La cage thoracique est constituée de :","o":["Vertèbres dorsales, côtes, cartilages costaux et sternum","Côtes, cartilages et sternum seulement, sans vertèbres","Vertèbres et côtes, sans le sternum","Sternum et cartilages, sans les côtes"],"r":0,"e":"C'est une cage ostéocartilagineuse, de fonction protectrice et respiratoire.","s":17},{"q":"Les bords latéraux du sternum présentent :","o":["Sept échancrures articulaires et six non articulaires","Sept échancrures au total, toutes articulaires","Douze échancrures, une pour chacune des douze côtes du thorax","Cinq échancrures, pour les cinq premières côtes"],"r":0,"e":"Le sternum comprend manubrium, corps et processus xiphoïde. Les échancrures articulaires reçoivent les cartilages costaux, les autres répondent aux espaces intercostaux.","s":17},{"q":"Les côtes 8, 9 et 10 sont dites :","o":["Vertébro-chondrales, car liées au cartilage de la 7ᵉ côte","Vertébro-sternales, car liées au sternum dès la 1ʳᵉ côte","Flottantes, car libres en avant, sans aucun cartilage","Vraies côtes, car fixées au sternum par leur cartilage"],"r":0,"e":"Les 7 premières paires sont vertébro-sternales, et les 11ᵉ et 12ᵉ flottantes.","s":17},{"q":"La surface interne du corps costal est :","o":["Concave, en rapport avec la plèvre","Convexe, sous les muscles","Plane, sans rapport particulier","Rugueuse, pour les insertions"],"r":0,"e":"La surface externe est convexe et le bord inférieur porte le sillon costal des vaisseaux et nerfs intercostaux.","s":17},{"q":"Une côte présente :","o":["Deux courbures et deux angles, postérieur et antérieur","Une seule courbure, sans aucun angle sur toute sa longueur","Trois courbures, de la tête à l'extrémité antérieure","Aucun angle, avec une courbure de torsion seule"],"r":0,"e":"Son extrémité la plus large est postérieure, avec une concavité interne.","s":17},{"q":"La tête d'une côte s'articule avec :","o":["Les corps de deux vertèbres dorsales voisines","Le corps d'une seule vertèbre, par une facette","L'apophyse transverse, par sa facette","Le sternum, par l'intermédiaire du cartilage costal"],"r":0,"e":"La tubérosité s'articule, elle, avec l'apophyse transverse.","s":17},{"q":"L'angle d'une côte se situe :","o":["En dehors de la tubérosité, à la plus forte courbure","À la tête, au contact direct du corps vertébral, en arrière","Au col, entre la tête et la tubérosité","À l'extrémité antérieure, près du cartilage"],"r":0,"e":"Le col se situe entre la tête et la tubérosité.","s":17},{"q":"Le tubercule de Lisfranc de la 1ʳᵉ côte :","o":["Reçoit le scalène antérieur, entre veine et artère","Reçoit le scalène postérieur, sur la face supérieure","S'articule avec le manubrium, par une facette plane latérale","Porte deux facettes, pour deux vertèbres voisines"],"r":0,"e":"La tête de la 1ʳᵉ côte ne présente qu'une seule facette articulaire. Il sépare les gouttières de la veine et de l'artère sous-clavières.","s":17},{"q":"La face supéro-externe de la 2ᵉ côte reçoit :","o":["Les scalènes postérieurs et les dentelés","Le scalène antérieur et le muscle sous-clavier","Le grand pectoral et le petit pectoral","Le diaphragme et le transverse du thorax"],"r":0,"e":"C'est sa particularité morphologique principale.","s":17},{"q":"Les 11ᵉ et 12ᵉ côtes se caractérisent par :","o":["Une facette unique sur la tête, rien sur la tubérosité","Deux facettes sur la tête, pour deux vertèbres","Une facette sur la tubérosité, pour la transverse","Un angle postérieur très marqué, avec torsion"],"r":0,"e":"La 12ᵉ est plus petite et dépourvue d'angle postérieur. Elles n'ont pas de courbure de torsion.","s":17},{"q":"Les cartilages costaux 8, 9 et 10 s'insèrent :","o":["Sur le cartilage sus-jacent, et non sur le sternum","Directement sur le bord latéral du sternum","Sur les corps vertébraux, en arrière","Sur le processus xiphoïde, par un ligament commun"],"r":0,"e":"Les sept premiers s'insèrent directement sur le sternum.","s":17},{"q":"Les articulations costo-vertébrales sont classées comme :","o":["Des arthrodies","Des amphiarthroses","Des synchondroses","Des synarthroses"],"r":0,"e":"Leurs moyens d'union sont une capsule peu développée et les ligaments costo-vertébraux antérieur ou radié, postérieur et interosseux.","s":17},{"q":"Les moyens d'union des articulations costo-transversaires comprennent :","o":["Une capsule faible et des ligaments costotransversaires","Une capsule épaisse, sans aucun ligament associé","Un seul ligament costotransversaire, sans capsule","Aucun ligament, la stabilité venant des muscles intercostaux"],"r":0,"e":"Elles unissent la tubérosité costale au processus transverse et sont classées comme arthrodies. Les ligaments sont postérieur, supérieur et interosseux.","s":17},{"q":"Les articulations costo-chondrales sont classées comme :","o":["Des synchondroses, à cartilage hyalin","Des arthrodies, à surfaces planes","Des amphiarthroses, à fibrocartilage","Des diarthroses, à cavité synoviale"],"r":0,"e":"Les articulations chondro-sternales et interchondrales sont, elles, des arthrodies.","s":17},{"q":"Les articulations sternales supérieure et inférieure sont classées comme :","o":["Des amphiarthroses à fibrocartilage","Des arthrodies à surfaces planes","Des synchondroses à cartilage hyalin","Des diarthroses à cavité synoviale large"],"r":0,"e":"Elles unissent respectivement manubrium et corps, puis corps et processus xiphoïde.","s":17},{"q":"Lors de l'inspiration, les côtes moyennes réalisent un mouvement :","o":["En anse de seau","En bras de pompe","De rotation","De translation"],"r":0,"e":"Les côtes supérieures réalisent, elles, un mouvement en bras de pompe.","s":17},{"q":"L'échancrure jugulaire du sternum se situe :","o":["Au sommet de la face antérieure","À la jonction manubrium-corps","Au processus xiphoïde","Sur le bord latéral"],"r":0,"e":"Les facettes articulaires de la clavicule et du 1ᵉʳ cartilage costal y sont adjacentes.","s":17},{"q":"Les cartilages costaux présentent :","o":["Une face antérieure convexe, entre la côte et le sternum","Une face antérieure concave, tournée vers la plèvre","Deux extrémités osseuses, soudées au sternum","Une seule extrémité, libre en avant, sans attache sternale"],"r":0,"e":"Ils assurent la liaison élastique entre les côtes et le sternum. L'extrémité interne rejoint le sternum ou le cartilage sus-jacent.","s":17},{"q":"L'expiration correspond à :","o":["Un abaissement et un retour à la position initiale","Une élévation du sternum et des côtes","Une augmentation des diamètres du thorax, en tous sens","Une rotation des côtes autour de leur axe"],"r":0,"e":"L'inspiration élève le sternum et les côtes et augmente les diamètres du thorax.","s":17},{"q":"Le membre supérieur libre comprend les os :","o":["Omoplate, clavicule, humérus, radius et cubitus","Humérus, radius, cubitus, carpe, métacarpe et phalanges","Humérus seul, sans l'avant-bras ni la main","Tous les os du membre, avec la ceinture scapulaire"],"r":1,"e":"Le membre supérieur libre = humérus, radius, cubitus, carpe (8), métacarpe (5), phalanges (14).","s":18},{"q":"La ceinture scapulaire est composée de :","o":["Sternum + clavicule","Omoplate + clavicule","Omoplate + humérus","Clavicule + 1ère côte"],"r":1,"e":"Ceinture scapulaire = omoplate (scapula) + clavicule.","s":18},{"q":"La cavité glénoïde de la scapula s'articule avec :","o":["L'acromion","La clavicule","La tête humérale","Le radius"],"r":2,"e":"La cavité glénoïde s'articule avec la tête humérale (articulation gléno-humérale).","s":18},{"q":"Le processus coracoïde reçoit l'insertion de :","o":["La longue portion du biceps et le grand rond","La courte portion du biceps et le coraco-brachial","Le triceps brachial et le deltoïde postérieur","Le deltoïde et le trapèze supérieur"],"r":1,"e":"Le coracoïde reçoit le tendon commun de la courte portion du biceps + coraco-brachial. Le petit pectoral s'insère sur son bord interne.","s":18},{"q":"La portion longue du biceps brachial s'insère sur :","o":["Le processus coracoïde de la scapula","Le tubercule supra-glénoïdien","Le trochiter de l'humérus","Le trochin, sur la face antérieure de l'humérus"],"r":1,"e":"La longue portion du biceps s'insère sur le tubercule supra-glénoïdien de la scapula.","s":18},{"q":"L'épine de la scapula divise sa face postérieure en :","o":["2 fosses","3 fosses","4 fosses","Aucune"],"r":0,"e":"L'épine de la scapula divise la face postérieure en 2 : fosse supra-épineuse et fosse sous-épineuse.","s":18},{"q":"Le sillon bicipital se trouve entre :","o":["Le trochiter et le trochin","Le col anatomique et le col chirurgical","La tête et le col","Les deux épicondyles"],"r":0,"e":"Le sillon (gouttière) bicipital est entre le trochiter (grand tubercule) et le trochin (petit tubercule).","s":18},{"q":"Le sillon radial de l'humérus contient :","o":["L'artère brachiale","Le nerf radial","Le nerf ulnaire","Le nerf médian"],"r":1,"e":"Le sillon radial (face postérieure de la diaphyse humérale) contient le nerf radial.","s":18},{"q":"L'épicondyle est :","o":["Médial","Latéral","Antérieur","Postérieur"],"r":1,"e":"L'épicondyle est latéral. L'épitrochlée est médiale.","s":18},{"q":"L'épitrochlée est :","o":["Médiale","Latérale","Postérieure","Inférieure"],"r":0,"e":"L'épitrochlée = épicondyle médial.","s":18},{"q":"La trochlée humérale s'articule avec :","o":["La tête radiale, par sa cupule","La grande cavité sigmoïde du cubitus","L'olécrane, par sa face postérieure","L'épine de la scapula"],"r":1,"e":"Trochlée humérale ↔ grande cavité sigmoïde du cubitus (articulation huméro-ulnaire).","s":18},{"q":"Le condyle huméral s'articule avec :","o":["L'olécrane","La tête du radius","Le processus coronoïde","Le triquetrum"],"r":1,"e":"Le condyle huméral (capitulum) s'articule avec la tête du radius.","s":18},{"q":"La fosse olécrânienne reçoit :","o":["Le processus coronoïde, en flexion","L'olécrane, en extension","La tête du radius, en supination","Le triquetrum du carpe"],"r":1,"e":"La fosse olécrânienne reçoit l'olécrane lors de l'extension du coude.","s":18},{"q":"Combien d'os y a-t-il au carpe ?","o":["6","7","8","10"],"r":2,"e":"8 os du carpe sur 2 rangées.","s":18},{"q":"La 1ère rangée du carpe (procarpe) comprend :","o":["Trapèze, trapézoïde, grand os, unciforme","Scaphoïde, lunatum, triquetrum, pisiforme","Lunatum, triquetrum, capitatum, hamatum","Scaphoïde, capitatum, trapèze, pisiforme"],"r":1,"e":"Procarpe = scaphoïde, semi-lunaire (lunatum), triquetrum (pyramidal), pisiforme.","s":18},{"q":"La 2e rangée du carpe (mésocarpe) comprend :","o":["Scaphoïde, lunatum, triquetrum, pisiforme","Trapèze, trapézoïde, capitatum, hamatum","Les phalanges proximales des cinq doigts","Aucun os, la rangée étant cartilagineuse"],"r":1,"e":"Mésocarpe = trapèze, trapézoïde, grand os (capitatum), unciforme (hamatum).","s":18},{"q":"Combien de phalanges a le pouce ?","o":["1","2","3","4"],"r":1,"e":"Le pouce n'a que 2 phalanges (proximale + distale).","s":18},{"q":"Combien de phalanges ont les autres doigts ?","o":["2","3","4","5"],"r":1,"e":"Index, majeur, annulaire, auriculaire = 3 phalanges chacun.","s":18},{"q":"L'articulation gléno-humérale est :","o":["Une arthrodie","Une énarthrose","Une trochléarthrose","Une condylarthrose"],"r":1,"e":"Gléno-humérale = énarthrose (sphéroïde, 3 degrés de liberté).","s":18},{"q":"L'articulation acromio-claviculaire est :","o":["Énarthrose","Arthrodie","Trochléarthrose","Condylarthrose"],"r":1,"e":"Acromio-claviculaire = arthrodie.","s":18},{"q":"L'articulation sterno-claviculaire est :","o":["Une arthrodie, à surfaces planes","Une énarthrose, à surfaces sphériques","Une articulation en selle, par emboîtement","Une trochoïde, en pivot autour d'un axe vertical"],"r":2,"e":"Sterno-claviculaire = articulation en selle (par emboîtement réciproque).","s":18},{"q":"Les ligaments coraco-claviculaires sont :","o":["Trapézoïde + conoïde","Antérieur + postérieur","Supérieur + inférieur","Coraco-acromial seul"],"r":0,"e":"Coraco-claviculaires = trapézoïdal + conoïde.","s":18},{"q":"La coiffe des rotateurs est formée par :","o":["Deltoïde, biceps, triceps et coraco-brachial","Supra et infra-épineux, petit rond, sous-scapulaire","Grand pectoral, grand dorsal, deltoïde et biceps","Sous-scapulaire seul, en avant de la scapula"],"r":1,"e":"Coiffe des rotateurs : supra-épineux, infra-épineux, petit rond, sous-scapulaire.","s":18},{"q":"L'articulation huméro-ulnaire est :","o":["Trochléarthrose","Énarthrose","Arthrodie","Condylarthrose"],"r":0,"e":"Huméro-ulnaire = trochléarthrose.","s":18},{"q":"L'articulation huméro-radiale est :","o":["Trochléarthrose","Condylarthrose","Arthrodie","Énarthrose"],"r":1,"e":"Huméro-radiale = condylarthrose (condyle huméral + tête radiale).","s":18},{"q":"L'articulation radio-ulnaire supérieure est :","o":["Trochléarthrose","Trocarthrose","Énarthrose","Condylarthrose"],"r":1,"e":"Radio-ulnaire supérieure = trocarthrose (rotation autour du ligament annulaire).","s":18},{"q":"L'articulation radio-carpienne est :","o":["Trochléarthrose","Condylarthrose","Énarthrose","Arthrodie"],"r":1,"e":"Le poignet (radio-carpienne) = condylarthrose (2 axes).","s":18},{"q":"L'articulation entre le 1er métacarpien et le trapèze est :","o":["Une arthrodie","Une condylarthrose","Une articulation en selle","Une trochléarthrose"],"r":2,"e":"Trapèze-1er métacarpien (trapézométacarpienne) = articulation en selle (épiphyarthrose) — permet l'opposition du pouce.","s":18},{"q":"Les articulations métacarpo-phalangiennes sont :","o":["Trochléarthroses","Arthrodies","Condylarthroses","En selle"],"r":2,"e":"MCP = condylarthroses (2 axes : flexion-extension + abduction-adduction).","s":18},{"q":"Les articulations interphalangiennes sont :","o":["Énarthroses","Arthrodies","Condylarthroses","Trochléarthroses"],"r":3,"e":"Interphalangiennes (proximales et distales) = trochléarthroses (1 axe : flexion-extension).","s":18},{"q":"La scapula est décrite comme :","o":["Un os pair, plat et triangulaire, au bord supérieur court","Un os long, avec une diaphyse et deux épiphyses","Un os court et impair, à peu près aussi épais que large et long","Un os irrégulier, impair et médian"],"r":0,"e":"Sa surface articulaire sphérique est externe ; elle se connecte à la clavicule et à l'humérus. Son bord supérieur est le plus court des trois.","s":18},{"q":"La fosse infrascapulaire, sur la face antérieure de la scapula, donne insertion :","o":["Au muscle sous-scapulaire","Au muscle supra-épineux","Au muscle infra-épineux","Au muscle petit rond"],"r":0,"e":"La face antérieure est concave et s'applique sur la paroi thoracique.","s":18},{"q":"La tubérosité infra-glénoïdienne donne insertion :","o":["À la longue portion du triceps brachial","À la longue portion du biceps brachial, en haut","Au petit pectoral, par son tendon","Au deltoïde, par ses fibres postérieures"],"r":0,"e":"Le tubercule supra-glénoïdien reçoit, lui, la portion longue du biceps brachial.","s":18},{"q":"Le bord interne du processus coracoïde reçoit :","o":["Le petit pectoral","Le coraco-brachial seul","Le biceps seul","Le sous-clavier"],"r":0,"e":"Le processus coracoïde reçoit par ailleurs le tendon commun de la portion courte du biceps et du coraco-brachial.","s":18},{"q":"L'angle supérieur de la scapula reçoit :","o":["L'élévateur de la scapula, ou angulaire","Le trapèze, par ses fibres moyennes","Les rhomboïdes, par leur bord inférieur","Le grand dentelé, par ses digitations supérieures"],"r":0,"e":"L'angle externe porte la cavité glénoïde et le tubercule supra-glénoïdien.","s":18},{"q":"L'acromion présente :","o":["Une facette pour la clavicule, sur son bord interne","Une facette pour la tête humérale, en dessous","Aucune facette, seulement des insertions","Deux facettes, pour la clavicule et pour le sternum"],"r":0,"e":"L'épine de la scapula divise la face postérieure en fosses supra-épineuse et sous-épineuse.","s":18},{"q":"La clavicule présente deux courbures :","o":["Interne concave en arrière, externe concave en avant","Interne et externe, toutes deux concaves en avant du corps","Interne et externe, toutes deux concaves en arrière","Interne concave en avant, externe concave en arrière"],"r":0,"e":"C'est un os long pair en forme de S italique, reliant sternum, 1ᵉʳ cartilage costal et omoplate.","s":18},{"q":"Le sillon sous-clavier de la clavicule reçoit :","o":["Le muscle sous-clavier, dans sa partie médiane","Le ligament conoïde, près du bord postérieur","Le trapèze, sur son bord postérieur externe","Le deltoïde, sur son bord antérieur, en dehors du sillon"],"r":0,"e":"La tubérosité costale reçoit le ligament chondroclaviculaire et le tubercule conoïde le ligament conoïde.","s":18},{"q":"Le bord antérieur de la clavicule reçoit :","o":["Le grand pectoral en dedans et le deltoïde en dehors","Le trapèze en dehors et le sterno-cléido-mastoïdien en dedans","Le sous-clavier en dedans et le trapèze en dehors","Le deltoïde seul, sur toute la longueur de l'os"],"r":0,"e":"Le bord postérieur reçoit le SCM en interne et le trapèze en externe. Le grand pectoral occupe les deux tiers internes, le deltoïde le tiers externe.","s":18},{"q":"Le trochiter de l'humérus présente trois facettes pour :","o":["Le supra-épineux, l'infra-épineux et le petit rond","Le sous-scapulaire, le supra-épineux et l'infra-épineux","Le deltoïde, le supra-épineux et le petit rond","Le biceps, le triceps et le deltoïde"],"r":0,"e":"Le trochin reçoit, lui, le sous-scapulaire.","s":18},{"q":"La face antéro-externe de la diaphyse humérale porte :","o":["Le V deltoïdien et le brachial antérieur","Le foramen nourricier et le grand rond","Le sillon radial et le nerf radial","Le coraco-brachial et le triceps"],"r":0,"e":"La face antéro-interne porte le foramen nourricier et l'insertion du coraco-brachial.","s":18},{"q":"La fosse coronoïde de l'humérus reçoit :","o":["Le processus coronoïde du cubitus, en flexion","L'olécrane du cubitus, en extension complète du coude","La tête radiale, en flexion et supination","Le trochin, lors de la rotation interne"],"r":0,"e":"La fosse olécrânienne reçoit, elle, l'olécrane en extension.","s":18},{"q":"La cavité glénoïde du radius s'articule avec :","o":["Le condyle huméral","La trochlée humérale","Le cubitus","Le scaphoïde"],"r":0,"e":"Le contour de la tête radiale s'articule avec la petite cavité sigmoïde du cubitus.","s":18},{"q":"La tubérosité bicipitale du radius reçoit :","o":["Le biceps brachial","Le brachial antérieur","Le triceps","Le supinateur"],"r":0,"e":"Elle se situe sous le col du radius.","s":18},{"q":"La face postérieure de la diaphyse radiale donne insertion :","o":["Au long abducteur et au court extenseur du pouce","Au long fléchisseur du pouce et au fléchisseur profond","Au carré pronateur, dans sa partie distale","Au rond pronateur, dans sa partie moyenne"],"r":0,"e":"La face externe reçoit le court supinateur et le rond pronateur.","s":18},{"q":"L'épiphyse distale du radius s'articule, par sa face inférieure, avec :","o":["Le scaphoïde en dehors et le semi-lunaire en dedans","Le seul scaphoïde, sans contact avec le lunatum","Le seul semi-lunaire, par une facette","Le pyramidal, par l'intermédiaire du disque"],"r":0,"e":"Sa face antérieure reçoit le carré pronateur et sa face postérieure porte deux sillons tendineux.","s":18},{"q":"L'olécrane s'engage dans la fosse olécrânienne :","o":["En extension","En flexion","En pronation","En supination"],"r":0,"e":"Le processus coronoïde s'engage, lui, dans la fosse coronoïde en flexion.","s":18},{"q":"La tête du cubitus s'articule en dessous avec :","o":["Le triquetrum, avec un fibrocartilage interposé","Le scaphoïde, par une facette directe","Le semi-lunaire, par une facette directe","Le pisiforme, par une facette directe et une capsule"],"r":0,"e":"Extérieurement, elle s'articule avec la cavité sigmoïde du radius.","s":18},{"q":"Le bord externe du cubitus, ou crête interosseuse, donne insertion :","o":["À la membrane interosseuse","À l'anconé","Au carré pronateur","Au fléchisseur commun profond"],"r":0,"e":"La face postérieure reçoit l'anconé à son sommet.","s":18},{"q":"La main compte au total :","o":["27 os","26 os","30 os","24 os"],"r":0,"e":"Soit 8 os du carpe, 5 métacarpiens et 14 phalanges.","s":18},{"q":"L'os iliaque est composé de :","o":["Deux parties, l'ilion et le pubis","Trois parties, l'ilion, l'ischion et le pubis","Quatre parties, avec le sacrum en plus","Une seule pièce, sans soudure, dès la naissance"],"r":1,"e":"L'os iliaque = ilion (haut) + ischion (postérieur) + pubis (antérieur).","s":19},{"q":"L'acétabulum (cavité cotyloïdienne) s'articule avec :","o":["Le sacrum","La tête fémorale","Le tibia","L'iliaque opposé"],"r":1,"e":"L'acétabulum reçoit la tête du fémur (articulation coxo-fémorale).","s":19},{"q":"L'EIAS est le site d'insertion de :","o":["Le sartorius et le tenseur du fascia lata","Le droit antérieur, par son tendon direct et réfléchi","Le pectiné, par son bord supérieur","Le quadriceps, par ses quatre chefs"],"r":0,"e":"EIAS (épine iliaque antéro-supérieure) = insertion du sartorius (couturier) + TFL (tenseur du fascia lata).","s":19},{"q":"L'EIAI est le site d'insertion de :","o":["Le sartorius, par son tendon","Le droit antérieur du quadriceps","Le pectiné, par son bord supérieur","Le grand fessier, par ses fibres antérieures"],"r":1,"e":"EIAI (épine iliaque antéro-inférieure) = insertion du droit antérieur (rectus femoris).","s":19},{"q":"La grande échancrure sciatique livre passage à :","o":["Au pyramidal, aux vaisseaux glutéaux et au sciatique","Au nerf obturateur et à ses vaisseaux satellites","À l'artère iliaque externe, vers la cuisse","Au seul psoas, avec le nerf fémoral"],"r":0,"e":"Grande échancrure sciatique = muscle pyramidal, vaisseaux + nerfs glutéaux supérieurs, vaisseaux ischiatiques, nerf sciatique. Les nerfs glutéaux et les vaisseaux ischiatiques y passent aussi.","s":19},{"q":"Le grand trochanter est sur :","o":["L'iliaque","Le fémur","Le tibia","Le péroné"],"r":1,"e":"Le grand trochanter est une apophyse du fémur (épiphyse supérieure).","s":19},{"q":"Le petit trochanter reçoit l'insertion du :","o":["Grand fessier","Psoas-iliaque","Pectiné","Adducteur"],"r":1,"e":"Le petit trochanter = insertion du muscle psoas-iliaque.","s":19},{"q":"La ligne âpre se divise en :","o":["Deux branches, médiale et latérale, vers les deux condyles","Trois branches, fessière, pectinéale et vaste interne","Quatre branches, dont une vers le petit trochanter","Une seule crête, sans aucune division"],"r":1,"e":"La ligne âpre se divise en 3 : crête du grand fessier (lat), crête pectinéale (moy), crête du vaste interne (méd).","s":19},{"q":"La trochlée fémorale s'articule avec :","o":["Le tibia","La rotule","Le péroné","Le talus"],"r":1,"e":"La trochlée fémorale s'articule avec la face postérieure de la rotule (articulation fémoro-patellaire).","s":19},{"q":"L'échancrure intercondylienne loge :","o":["Le ménisque","Les ligaments croisés","Le tendon rotulien","Le LLI"],"r":1,"e":"L'échancrure intercondylienne (entre les condyles) loge les ligaments croisés (LCA et LCP).","s":19},{"q":"La rotule est :","o":["Un os court, comme ceux du carpe","Un os long, avec deux épiphyses","Le plus gros os sésamoïde du corps","Un os irrégulier, comme les vertèbres du rachis"],"r":2,"e":"La rotule est le plus gros os sésamoïde du corps humain.","s":19},{"q":"La base de la rotule reçoit :","o":["Le ligament rotulien","Le tendon du quadriceps","Le tendon d'Achille","Le ligament patellaire"],"r":1,"e":"La base (haut) de la rotule reçoit le tendon du quadriceps. Le vertex (bas) reçoit le ligament rotulien (= patellaire).","s":19},{"q":"La malléole tibiale (interne) appartient à :","o":["Le fémur","Le tibia","Le péroné","Le talus"],"r":1,"e":"La malléole interne = malléole tibiale (face interne du tibia).","s":19},{"q":"La malléole externe (fibulaire) appartient à :","o":["Au tibia, par son extrémité distale","Au péroné, ou fibula, en bas","Au talus, par sa face latérale","Au calcanéum, en dehors"],"r":1,"e":"Malléole externe = malléole péronière/fibulaire.","s":19},{"q":"Le tubercule de Gerdy est sur :","o":["Le fémur, sur la face externe du condyle latéral","Le tibia, sur la face externe de sa tubérosité","Le péroné, sur la face antérieure de la tête","La rotule, sur son bord latéral"],"r":1,"e":"Le tubercule de Gerdy est sur la face externe de la tubérosité antérieure du tibia : insertion du tibial antérieur et du TFL.","s":19},{"q":"Combien d'os y a-t-il au tarse ?","o":["5","6","7","8"],"r":2,"e":"7 os du tarse.","s":19},{"q":"L'astragale est aussi appelé :","o":["Calcanéum","Talus","Naviculaire","Cuboïde"],"r":1,"e":"Astragale = talus (s'articule avec tibia et péroné en haut, calcanéum en bas, scaphoïde en avant).","s":19},{"q":"Combien de phalanges a le gros orteil ?","o":["1","2","3","4"],"r":1,"e":"Comme le pouce, le gros orteil n'a que 2 phalanges (proximale + distale).","s":19},{"q":"L'articulation sacro-iliaque met en jeu :","o":["Les corps vertébraux de L5 et S1, par le disque intervertébral","Les facettes auriculaires du sacrum et de l'ilium","Le coccyx et l'ilium, par un ligament","Le sacrum et la tête du fémur"],"r":1,"e":"L'articulation sacro-iliaque = entre les facettes auriculaires du sacrum et de l'ilium.","s":19},{"q":"Le ligament de Bertin est aussi appelé :","o":["Ligament rond","Ligament ilio-fémoral","Ligament pubo-fémoral","Ligament ischio-fémoral"],"r":1,"e":"Ligament ilio-fémoral = ligament de Bertin (le plus puissant de la hanche).","s":19},{"q":"La hanche est une articulation de type :","o":["Énarthrose","Arthrodie","Trochléarthrose","Condylarthrose"],"r":0,"e":"La coxo-fémorale est une énarthrose (sphéroïde, 3 axes).","s":19},{"q":"La symphyse pubienne est :","o":["Une diarthrose","Une amphiarthrose","Une synarthrose","Une énarthrose"],"r":1,"e":"La symphyse pubienne = amphiarthrose (disque interpubien fibrocartilagineux).","s":19},{"q":"Le genou est une articulation de type :","o":["Une énarthrose à surfaces sphériques","Une trochléarthrose pure, à une poulie","Une trochléo-bicondylo-méniscarthrose","Une arthrodie à surfaces planes et glissantes"],"r":2,"e":"Le genou = trochléo-bicondylo-méniscarthrose (3 articulations : fémoro-patellaire + fémoro-tibiale int + ext, avec ménisques).","s":19},{"q":"Le ménisque interne du genou est en forme de :","o":["C fermé","O","C ouvert","Triangle"],"r":2,"e":"Ménisque interne = C ouvert (plus mobile, plus vulnérable). Ménisque externe = C fermé.","s":19},{"q":"Le LCA (ligament croisé antérieur) part de :","o":["De l'épine tibiale antérieure au condyle latéral","De l'épine tibiale postérieure au condyle médial","De la trochlée fémorale à la pointe de la rotule","Du plateau tibial à la tête du péroné"],"r":0,"e":"LCA : épine tibiale antéro-médiale → portion postérieure de la face interne du condyle latéral. Il gagne la face interne du condyle latéral.","s":19},{"q":"L'articulation tibio-tarsienne (cheville) est de type :","o":["Énarthrose","Arthrodie","Trochléarthrose","Condylarthrose"],"r":2,"e":"La cheville (tibio-tarsienne) est une trochléarthrose : trochlée du talus + mortaise tibio-fibulaire.","s":19},{"q":"Le ligament deltoïde est :","o":["Au coude, sur sa face médiale","Au genou, sur sa face médiale","À la cheville, sur sa face médiale","Au poignet, sur sa face médiale et palmaire"],"r":2,"e":"Le ligament deltoïde = couche superficielle du ligament latéral INTERNE de la cheville. C'est la couche superficielle du ligament latéral interne.","s":19},{"q":"L'articulation de Chopart unit :","o":["Le tarse et le métatarse, en avant","Le tarse postérieur et le tarse antérieur","Les trois cunéiformes entre eux","Les métatarsiens entre eux, à leur base postérieure"],"r":1,"e":"Chopart = articulation médiotarsienne (entre tarse postérieur et antérieur). C'est l'articulation médiotarsienne.","s":19},{"q":"L'articulation de Lisfranc est :","o":["Médiotarsienne","Tarso-métatarsienne","Métatarso-phalangienne","Tibio-tarsienne"],"r":1,"e":"Lisfranc = articulation tarso-métatarsienne.","s":19},{"q":"Le ligament rond se trouve :","o":["Au coude, entre radius et cubitus","À la hanche, dans l'articulation","Au genou, entre les deux ménisques latéraux","Au pied, sous la voûte plantaire"],"r":1,"e":"Le ligament rond est intra-articulaire à la hanche, va du fond de la fosse acétabulaire à la fovéa de la tête fémorale.","s":19},{"q":"Le membre inférieur libre comprend :","o":["Fémur, jambe, rotule, tarse, métatarse et phalanges","Fémur et tibia seulement, sans le pied","Os iliaque, fémur, tibia, péroné et rotule, sans le pied","Fémur, tibia et huit os du tarse"],"r":0,"e":"La ceinture pelvienne est formée des deux os iliaques. La jambe comprend tibia et péroné ; le tarse compte 7 os, le métatarse 5 et les phalanges 14.","s":19},{"q":"Sur la fosse iliaque externe, la zone postérieure donne insertion :","o":["Au grand fessier","Au moyen fessier","Au petit fessier","Au pyramidal"],"r":0,"e":"Deux lignes semi-circulaires y délimitent trois zones : grand fessier en arrière, moyen fessier au milieu, petit fessier en antéro-inférieur.","s":19},{"q":"L'encoche la plus profonde de l'acétabulum est :","o":["L'encoche inférieure, ischio-pubienne","L'encoche antérieure, ilio-pubienne","L'encoche postérieure, sciatique","Aucune, elles sont toutes égales"],"r":0,"e":"L'acétabulum comprend une partie périphérique articulaire et une partie centrale non articulaire.","s":19},{"q":"Le foramen obturateur est fermé par :","o":["La membrane obturatrice","Le ligament sacro-sciatique","La capsule","Une lame osseuse"],"r":0,"e":"Il est délimité par le cotyle en haut, le pubis en avant et l'ischion en arrière.","s":19},{"q":"Sur la face interne de l'os iliaque, la ligne innominée sépare :","o":["La fosse iliaque en haut, la facette auriculaire en bas","Deux fosses iliaques, antérieure et postérieure","L'ilion de l'ischion, sur la face externe","Le pubis de l'ischion, au niveau du foramen obturé, en bas"],"r":0,"e":"La fosse iliaque interne donne insertion au muscle iliaque et la facette auriculaire s'articule avec le sacrum. En bas se trouvent aussi la tubérosité iliaque et le foramen obturateur.","s":19},{"q":"L'échancrure fémoro-cutanée livre passage :","o":["Au nerf fémoro-cutané","Au nerf fémoral","Au nerf obturateur","Au nerf sciatique"],"r":0,"e":"Elle se situe sur le bord antérieur, entre EIAS et EIAI.","s":19},{"q":"La petite échancrure sciatique livre passage :","o":["À l'obturateur interne, avec vaisseaux et nerfs","Au pyramidal, avec le nerf sciatique","Au grand fessier, avec les vaisseaux glutéaux supérieurs","Au psoas, avec le nerf fémoral"],"r":0,"e":"La grande échancrure sciatique livre passage au muscle pyramidal, aux vaisseaux et aux nerfs.","s":19},{"q":"La crête iliaque est décrite comme :","o":["En S italique, avec insertion des abdominaux","Rectiligne, avec insertion des fessiers","Circulaire, avec insertion du carré des lombes seul","En V, avec insertion du psoas"],"r":0,"e":"Elle s'étend de l'EIAS en avant à l'EIPS en arrière.","s":19},{"q":"La cavité digitale du grand trochanter reçoit :","o":["L'obturateur externe et les jumeaux","Le moyen fessier, par son tendon terminal","Le pyramidal, par son tendon","Le vaste externe, par sa crête"],"r":0,"e":"La face externe reçoit le moyen fessier, le bord supérieur la facette du pyramidal et le bord inférieur la crête du vaste externe.","s":19},{"q":"La ligne âpre du fémur se divise en trois branches :","o":["Crêtes fessière, pectinéale et du vaste interne","Deux branches seulement, médiale et latérale","Quatre branches, dont deux pour les adducteurs","Une seule crête, sans division vers le bas"],"r":0,"e":"Elle occupe le bord postérieur de la diaphyse fémorale. La fessière est latérale, la pectinéale moyenne, celle du vaste interne médiale.","s":19},{"q":"L'échancrure supra-trochléaire du fémur :","o":["Loge la rotule en extension","Loge les ligaments croisés","Reçoit le tendon rotulien","S'articule avec le tibia"],"r":0,"e":"L'échancrure intercondylienne loge, elle, les ligaments croisés.","s":19},{"q":"Le condyle fémoral externe présente :","o":["La tubérosité du LCP, avec deux excavations","La tubérosité du LCA, sur sa face externe","Le tubercule du grand adducteur, en haut","La trochlée fémorale, sur sa face antérieure"],"r":0,"e":"Le condyle interne porte le tubercule du grand adducteur et la tubérosité du LCA. Les excavations reçoivent le jumeau externe et le poplité.","s":19},{"q":"La rotule est décrite comme :","o":["Le plus gros sésamoïde, triangulaire à base supérieure","Un os long, avec une diaphyse et deux épiphyses","Un os plat, triangulaire à base inférieure et pointe haute","Un os court, cubique et à six faces"],"r":0,"e":"Elle est rattachée au tendon du quadriceps et s'articule avec le fémur.","s":19},{"q":"La face postérieure de la rotule présente :","o":["Une crête verticale entre deux facettes articulaires","Une surface plane, sans crête ni facette","Trois facettes séparées par deux crêtes","Des sillons verticaux et des orifices vasculaires nombreux"],"r":0,"e":"Les sillons verticaux et orifices vasculaires occupent, eux, la face antérieure. Les deux facettes, interne et externe, répondent à la trochlée.","s":19},{"q":"La tubérosité interne du tibia reçoit :","o":["Le semi-membraneux","Le ligament rotulien","Le tibial antérieur","Le tenseur du fascia lata"],"r":0,"e":"La tubérosité externe porte la facette fibulaire et la tubérosité antérieure reçoit le ligament rotulien.","s":19},{"q":"La face interne de la diaphyse tibiale donne insertion :","o":["Aux muscles de la patte d'oie, avec le sartorius","Au tibial antérieur, sur toute la hauteur de la diaphyse","Au soléaire, par sa ligne oblique","Au poplité, en haut de la face"],"r":0,"e":"La face postérieure porte la ligne oblique du soléaire, du poplité, du tibial postérieur et du fléchisseur commun. La patte d'oie réunit semi-tendineux, sartorius et droit interne.","s":19},{"q":"L'épiphyse distale du tibia présente en externe :","o":["L'échancrure péronière","La malléole tibiale","La gouttière du fléchisseur commun","La surface articulaire du talus"],"r":0,"e":"La malléole tibiale occupe la face interne et la gouttière du fléchisseur commun la face postérieure.","s":19},{"q":"Le sillon péronier de la fibula se situe :","o":["Sur la face externe, pour les tendons péroniers","Sur la face interne, pour le tibial postérieur","Sur la face postérieure, pour le soléaire","Sur le bord antérieur, pour le long extenseur"],"r":0,"e":"La face postérieure donne insertion au soléaire en haut et au fléchisseur du gros orteil en bas.","s":19},{"q":"L'épiphyse supérieure du péroné comprend :","o":["La tête, une facette tibiale, le col et la styloïde","La seule tête, sans facette ni processus","La malléole externe, avec sa facette pour le talus en bas","La crête interosseuse, en avant de la tête"],"r":0,"e":"L'épiphyse inférieure porte la malléole fibulaire, sa facette articulaire interne pour le talus et la gouttière externe des tendons péroniers.","s":19},{"q":"Le tubercule de Gerdy donne insertion :","o":["Au tibial antérieur et au tenseur du fascia lata","Au ligament rotulien, par sa partie distale","Au semi-membraneux et au gracile, par leurs tendons","Au poplité, par son tendon d'origine"],"r":0,"e":"Il se situe sur la face externe de la tubérosité antérieure du tibia.","s":19}]};
